quests[1945] = { id = 1945, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lachende Schwestern", description = "Als Dank für Eure Dienste habe ich veranlasst, dass Euch neue Roben angefertigt werden, sofern Ihr die erforderlichen Materialien beschaffen könnt...\n\nFür diese Roben müsst Ihr ins Eschental zurückkehren und Locken vom Haar der lachenden Schwestern beschaffen - Dryaden, die sich in der Nähe des Rajenbaums tummeln.\n\nWenn Ihr das Haar habt, bringt es zu Kil'hala, einem Trollschneider in der Siedlung des Wegekreuzes im Brachland. Er wird Euch erwarten und Eure Roben zuschneiden.", sourceObjective = "Bringt 12 Haarlocken der lachenden Schwestern zu Kil'hala beim Wegekreuz.", sourceObjectiveStatus = "unverified-source-field" }
quests[1946] = { id = 1946, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Netherspitzengewand" }
quests[1947] = { id = 1947, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reise in die Marschen", description = "Jetzt ist es an der Zeit, Euch Euren Magierzauberstab zu verdienen. Um diese Aufgabe zu beginnen, solltet Ihr mit der Menscheneinsiedlerin Tabetha in den Düstermarschen sprechen. Ihr findet ihre Hütte tief in den Marschen, westlich von Theramore.\n\nSprecht mit ihr, denn sie verfügt über umfangreiches Wissen. Tabethas Hütte befindet sich westlich von Theramore und direkt nördlich der Ruinen der Steinbrecher.", sourceObjective = "Sprecht mit Tabetha.", sourceObjectiveStatus = "unverified-source-field" }
quests[1948] = { id = 1948, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gegenstände der Macht", description = "Es ist nicht leicht, einen Magierzauberstab anzufertigen. Es sind rare Substanzen erforderlich und ein Gefäß muss gemacht werden, das große Mengen magischer Energie speichern kann. Ihr müsst diese Sachen sammeln und mir bringen.\n\nIch habe auf dieses Pergament geschrieben, was Ihr braucht und wie Ihr es bekommt. Bringt mir exakt das, was auf der Liste steht und folgt meinen schriftlichen Anweisungen auf den Buchstaben genau, denn wenn Ihr das nicht macht, geht bei der Herstellung Eures Zauberstabes vielleicht etwas...schief.", sourceObjective = "Bringt 1 Stück Jade und den vom Blitz aufgeladenen Dornbusch zu Tabetha in den Düstermarschen.", sourceObjectiveStatus = "unverified-source-field" }
quests[1949] = { id = 1949, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verborgene Geheimnisse", description = "Um Euren Zauberstab herzustellen, muss ich einige wichtige Stellen in einem bestimmten Buch lesen. Dieses Buch wurde von dem Magus Tirth geschrieben und heißt 'Rituale der Macht'.\n\nIch besitze kein Exemplar dieses Buchs und es ist in keiner der großen Bibliotheken der Welt zu finden. Daher müsst Ihr mit Tirth sprechen und es von ihm bekommen.\n\nViel Glück. Tirth war ein großer Magier und Gelehrter, aber heute verbringt er seine Zeit bei den Gnomen- und Goblinrennen in der Schimmernden Ebene und trinkt und spielt.", sourceObjective = "Sprecht mit Magus Tirth in der Schimmernden Ebene.", sourceObjectiveStatus = "unverified-source-field" }
quests[1950] = { id = 1950, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Knüller schlechthin", description = "Ich kann Euch mit dem Buch helfen, doch vorher müsst Ihr mir helfen!\n\nDer Foliant, den Ihr sucht, befindet sich in meiner magisch versiegelten Geldkassette. Um sie zu öffnen, muss ein bestimmter Satz gesprochen werden, aber ich kann mich nicht mehr an ihn erinnern! Normalerweise merkt sich mein Assistent so etwas, aber der ist unauffindbar.\n\nWenn Ihr mein Buch möchtet, sucht meinen Lehrling! Fragt auf der Rennbahn - wenn Ihr Glück habt, hat ihn jemand gesehen. Schleppt ihn entweder hierher oder entlockt ihm wenigstens meinen magischen Satz, damit wir die Kassette aufbekommen!", sourceObjective = "Bringt den Satz für Tirths Geldkassette in Erfahrung und kehrt zu Tirth zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[1951] = { id = 1951, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rituale der Macht", description = "Hm, wenn ich so darüber nachdenke, ich habe mein Buch nicht! Wisst Ihr, ich hatte Spielschulden, und um sie zu bezahlen, verkaufte ich das letzte Exemplar von 'Rituale der Macht' an ein Mitglied der Kleriker...\n\nEin Mitglied der Scharlachroten Bruderschaft. Er muss es zur Bibliothek im Scharlachroten Kloster in Tirisfal gebracht haben!\n\nWenn Ihr das Buch wollt, müsst Ihr in das Kloster gehen und es suchen. Und entschuldigt den ganzen Ärger. Ich bin neuerdings nicht mehr ich selbst...", sourceObjective = "Bringt das Buch 'Rituale der Macht' zu Tabetha in den Düstermarschen.", sourceObjectiveStatus = "unverified-source-field" }
quests[1952] = { id = 1952, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Zauberstab des Magiers", description = "Ich werde jetzt die Zauberstäbe machen.", sourceObjective = "Sprecht nach ihrem Ritual mit Tabetha.", sourceObjectiveStatus = "unverified-source-field" }
quests[1953] = { id = 1953, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr in die Marschen", description = "{name}, es wird Zeit, dass Ihr mit Tabetha sprecht... der Einsiedlerin in den Düstermarschen. Sie wird Euch in der Herstellung einer mächtigen Magiergerätschaft unterweisen.\n\nTabethas Hütte liegt tief in den Düstermarschen, westlich von Theramore.", sourceObjective = "Sprecht mit Tabetha.", sourceObjectiveStatus = "unverified-source-field" }
quests[1954] = { id = 1954, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Höllenkugel", description = "Als ersten Schritt müsst Ihr eine Kugel voll Macht beschaffen. Die Hexenmeister der Brennenden Klinge haben hübsche, hochwertige Kugeln... zu dumm, dass sie Dämonen darin eingebunden haben! Aber das können wir ändern, ja.\n\nGeht nach Desolace und nehmt einem Beschwörer der Brennenden Klinge eine Höllenkugel ab. Beschwörer findet Ihr beim Zirkel der Mannoroc.\n\nKommt zu mir zurück, wenn Ihr die Kugel habt.", sourceObjective = "Bringt eine Höllenkugel zu Tabetha in den Düstermarschen.", sourceObjectiveStatus = "unverified-source-field" }
quests[1955] = { id = 1955, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Austreibung", description = "Jetzt, da wir eine Beschwörerkugel haben, müssen wir den Dämon darin austreiben. Ich kann es machen. Das ist der einfache Teil.\n\nIhr habt die schwere Aufgabe. Ihr müsst den Dämon töten, wenn er draußen ist.\n\nUnd Ihr müsst Euch beeilen. Wenn Ihr zu lange braucht, springt er in die Kugel zurück und wir müssen von vorn anfangen!\n\nAlso macht Euch bereit. Bereitet Eure stärksten Zauber vor, habt Eure Tränke parat und holt einen Freund, wenn Ihr einen habt. Denn das hier wird nicht angenehm.", sourceObjective = "Tötet den Dämon der Kugel und sprecht dann mit Tabetha.", sourceObjectiveStatus = "unverified-source-field" }
quests[1956] = { id = 1956, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kraft in Uldaman", description = "Jetzt, nachdem der Dämon entfernt wurde, müssen wir eine Kraftquelle finden. Leider sind die besten Kraftquellen meistens die ältesten und die, an die man am schwersten rankommt. Ist schon lustig, wie einem das Schicksal manchmal mitspielt, wie?\n\nAlso müsst Ihr nach Uldaman und dort den Obsidianwächter besiegen. Der Kerl ist groß, er ist zäh und seine Kraftquelle hat ganz schön Pep.\n\nIch wünsche Euch viel Glück, {name}. Falls Ihr kein Glück haben solltet, tja... dann war es schön, Euch gekannt zu haben.", sourceObjective = "Beschafft Euch eine Obsidiankraftquelle und bringt sie in die Düstermarschen zu Tabetha.", sourceObjectiveStatus = "unverified-source-field" }
quests[1957] = { id = 1957, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Manawogen", description = "Wir sind fast fertig, aber dieser letzte Schritt ist der gefährlichste, {name}.\n\nIch habe die leere Beschwörerkugel und bin bereit, sie zu ermächtigen. Das machen wir, indem wir die Energie eines Manarisses anzapfen. Ich wirke einen Zauber, der vorübergehend einen Riss auftut, aus dem Kreaturen, Manawogen, herauskommen. Ihr müsst die Manawogen vernichten, damit ihre Macht freigesetzt wird, die ich dann einsammle.\n\nZerschlagt genug Manawogen, bevor sich der Riss schließt, und ich versiegle ihre gesammelte Energie in Eurer Kugel.", sourceObjective = "Vernichtet 12 Manawogen innerhalb des Zeitlimits.", sourceObjectiveStatus = "unverified-source-field" }
quests[1958] = { id = 1958, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Himmlische Macht" }
quests[1959] = { id = 1959, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meldung bei Anastasia", description = "Die Magier von Unterstadt haben eine magische Störung in der Stadt bemerkt und die Magier der Horde um Untersuchung gebeten.\n\nAnastasia Hirschbrunn kann Euch mehr sagen. Sprecht mit Ihr im Magieviertel in Unterstadt.", sourceObjective = "Sprecht mit Anastasia Hirschbrunn.", sourceObjectiveStatus = "unverified-source-field" }
quests[1960] = { id = 1960, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Untersuchungen im Alchemistenladen", description = "Algernons Alchemistenladen im Apothekarium ist das Zentrum einer seltsamen Störung. Unsichtbare, aus reiner Magie bestehende Kreaturen halten sich in dem Laden auf - dafür muss es einen Grund geben, und den müssen wir herausfinden!\n\nUntersucht die Störung und fangt diese Kreaturen. Nehmt Euch von dort hinten eine Truhe mit Kästen und eine Rolle. Benutzt im Laden die Rolle, um die Kreaturen sichtbar zu machen, überwältigt sie mit Euren Zaubern und fangt sie dann mit einem Kasten ein. Kommt mit den gefüllten Kästen, den leeren Kästen und der Anrufung zu mir zurück.", sourceObjective = "Besorgt eine Inkantation der Manifestation und eine Truhe mit Verwahrungskästen von Anastasia Hirschbrunn. Bringt 3 gefüllte Verwahrungskästen, die Truhe mit Verwahrungskästen sowie die Inkantation der Manifestation zu Anastasia in Unterstadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[1961] = { id = 1961, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Materialsammlung", description = "Jetzt ist es Zeit, Eure erste Magierrobe anzulegen, {name}. Sie ist ein Zeichen Eures Ranges und ein Zeugnis für Euren Wert.\n\nUm die Robe zu bekommen, müsst Ihr Manaedelsteine von den Magiern von Dalaran im Silberwald sammeln. Ihre Überzeugungen ähneln den unseren, daher ist es ein wenig geschmacklos, sie zu töten, aber wenn sie keine Kraft haben, uns Widerstand zu leisten, verdienen sie es nicht, zu leben.\n\nBringt die Edelsteine und das Leinen zu Josef Gregorian in der Schneiderei im Magieviertel.", sourceObjective = "Bringt 10 Leinenstoff und 6 Manaedelsteine aus Dalaran zu Josef Gregorian.", sourceObjectiveStatus = "unverified-source-field" }
quests[1962] = { id = 1962, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Roben des Zauberfeuers" }
quests[1963] = { id = 1963, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zerschmetterte Hand", description = "Die Methoden des Kriegshäuptlings sind zu zimperlich. Er wagt nicht, die Macht der Horde zu entfesseln. Einst waren wir stärker, allesamt mächtige Eroberer. Diesen Stolz müssen wir zurückerlangen, und der Klan der Zerschmetterten Hand wird dies bewerkstelligen.\n\nWir sammeln Kraft aus den Schatten und schlagen im Verborgenen gegen exponierte Feinde zu. Eine Aufgabe müsst Ihr für mich erledigen, um Euren Wert zu beweisen.\n\nDer Troll Tazan treibt Handel mit den Piraten bei Ratschet. Er hat Informationen, die ich haben muss. Tötet ihn und bringt mir seinen Ranzen.", sourceObjective = "Tötet Tazan und bringt seinen Ranzen zu Therzok in der Kluft der Schatten in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[1978] = { id = 1978, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Todespirscher", description = "Das Syndikat? Darauf wäre ich nie gekommen. Offenbar sind die Lords von Alterac in den Jahren seit ihrem Verrat tief gesunken.\n\nLord Varimathras wird es mit Freuden hören, und da wir diese Entdeckung weitgehend Euch verdanken, ist es nur recht und billig, dass Ihr ihm die Nachricht überbringt.\n\nAh, und wie konnte ich das vergessen?\n\nWillkommen bei den Todespirschern.", sourceObjective = "Bringt Androns Geschäftsbuch zu Varimathras in der Halle der Dunklen Fürstin in Unterstadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[1998] = { id = 1998, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fenwick Thatros", description = "Lord Varimathras hat mir soeben in einer Botschaft über eine Gefahr für die Verlassenen berichtet, die unverzüglich ausgeschaltet werden muss. Sein Name ist Fenwick Thatros. Lord Varimathras glaubt, dass er einer der Anführer der Untoten sei, die sich im Silberwald angesiedelt haben.\n\nMir kam sofort Euer Name in den Sinn, {name}. Ich habe Vertrauen in Eure Fähigkeiten und glaube, Ihr werdet diese Mission fehlerfrei abschließen.\n\nDie letzte Meldung von den Todespirschern im Silberwald deutet darauf hin, dass Thatros nahe der verfallenen Fähre am Lordameresee zu finden ist.", sourceObjective = "Tötet Fenwick Thatros und bringt seinen Kopf zu Mennet Carkad im Schurkenviertel von Unterstadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[1999] = { id = 1999, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Werkzeuge des Handwerks", description = "Die Hexer der Kirin Tor bei Mühlenbern haben wichtige Dokumente eingelagert, die den aktuellen Zustand von Dalaran betreffen. Das wissen wir durch die Aussagen eines unserer Gefangenen. Lord Varimathras hat die Aufgabe, diese zu beschaffen, den Todespirschern übertragen.\n\nDas ist eine Arbeit für Euch, {name}. Ihr braucht allerdings etwas Ausrüstung und Kenntnisse im Schlossknacken. Sprecht mit Estelle Gendry, unserer Lageristin, und bittet sie um ein Werkzeugset, bevor Ihr aufbrecht.", sourceObjective = "Sucht den Statusbericht von Dalaran und bringt ihn zu Mennet Carkad im Schurkenviertel von Unterstadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[2000] = { id = 2000, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rokar Klingenschatten", description = "Ihr habt zu viel Müßiggang, {name}. Es ist Zeit, dass Ihr mehr über unser Handwerk lernt. Erst gestern Nacht fand man fünf von uns tot in einer der Spalten in Orgrimmar, aber kaum Hinweise. Es gibt Widerständler gegen uns, die uns mit unseren eigenen Waffen schlagen möchten.\n\nDaher habe ich beschlossen, dass Ihr die Kunst des Schlossknackens lernen sollt.\n\nLeider ist das eine Fertigkeit, für die meine Hände nicht geschaffen sind. Ihr solltet Rokar aufsuchen, der in den Hügeln bei Durotar lebt. Ich glaube, er hat es trotz seines hohen Alters noch drauf.", sourceObjective = "Sprecht mit Rokar Klingenschatten in Durotar.", sourceObjectiveStatus = "unverified-source-field" }
quests[2018] = { id = 2018, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rokars Test", description = "Ah, also schickt mir Therzok jetzt schon seine Studenten-Grünschnäbel, hm? Ja, ich denke, ich kann Euch das eine oder andere beibringen. Nicht, dass mir viel an Eurer Sache gelegen wäre, aber ich möchte mein Gewissen nicht damit belasten, dass ich Euch in den Tod schicke.\n\nAber zuerst müsst Ihr Euch als würdig erweisen.\n\nIch sage es offen und ehrlich, {name}. Ich mag diese Venture Company nicht besonders. Dieses Land erinnert mich an Draenor und mir gefällt die Vorstellung nicht, dass diese Goblins es zerstören. Wenn ihr Vorarbeiter am Schlickmoor getötet wird, wird das Unternehmen lahm gelegt sein.", sourceObjective = "Tötet Vorarbeiter Glibby und bringt seine Pfeife zu Rokar Klingenschatten in Durotar.", sourceObjectiveStatus = "unverified-source-field" }
quests[2019] = { id = 2019, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Werkzeuge des Handwerks", description = "Da habt Ihr sie, {name}. Sie sollten Euch nützlich sein. Ich habe sie eigenhändig gefertigt und schwöre, Ihr findet keine besseren.\n\nAber sagt mir nichts von Euren Plänen. Therzoks Ränke interessieren mich nicht, ich möchte nur in Frieden meinen Ruhestand genießen.\n\nSolltet Ihr je ein anderes Werkzeugset brauchen, kommt zu mir und ich fertige Euch ein neues an. Aber geht sorgfältig damit um!", sourceObjective = "Kehrt zu Therzok in der Kluft der Schatten in Orgrimmar zurück.\n\nBereitgestellter Gegenstand:", sourceObjectiveStatus = "unverified-source-field" }
quests[2038] = { id = 2038, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bingles' verschwundene Werkzeuge", description = "Als wäre es nicht schlimm genug gewesen, in den Loch zu stürzen, haben mich auch noch Troggs von der nahe gelegenen Insel angegriffen und mir mein Werkzeug und meinen speziellen Sprengstoff Superspreng aus der Blastenheimer-Sprengstoffstube gestohlen. Ohne Gyrokopter und Sprengstoff hat die Bewegung keine Chance!\n\nBeschafft mir meine Werkzeuge wieder und findet mein Superspreng aus der Sprengstoffstube, {name}. Für Gnomeregan!", sourceObjective = "Sucht Bingles' Werkzeuge und bringt sie ihm zurück. Es sind:\n\nBingles' Schraubenschlüssel, Bingles' Schraubendreher, Bingles' Hammer und Bingles' Sprengstofftube.", sourceObjectiveStatus = "unverified-source-field" }
quests[2039] = { id = 2039, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sucht Bingles", description = "Wir haben den Kontakt mit Bingles verloren! Er wurde zu einer Aufklärungsmission über Gnomeregan geschickt und hat sich seit mehr als einer Woche nicht mehr gemeldet. Ich weiß, er hat sich selbst in die Luft gejagt.\n\nZuletzt sah man ihn über dem Loch fliegen. Vielleicht könnt Ihr dies untersuchen, {name}?", sourceObjective = "Sucht Bingles Blastenheimer am Loch Modan.", completion = "Gnoarn hat also kein Vertrauen in meine Aufklärungsfähigkeiten? Warum nur...\n\nUnwichtig, ich brauche Eure Unterstützung! Mehr noch! Die Bewegung braucht Eure Unterstützung!", sourceObjectiveStatus = "unverified-source-field" }
quests[2040] = { id = 2040, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unterirdischer Angriff", description = "Gnomeregan ist diesen elendigen Troggs in die Hände gefallen! Die Situation ist ernst, aber vielleicht könnt Ihr helfen, {name}.\n\nTief in den Todesminen gibt es einen funktionierenden Goblinschredder. Sucht diesen Schredder und bringt die intakte Energieversorgung mit. Mit der Energieversorgung des Schredders können wir unseren gyrobohrmatischen Exkavationatoren die erforderliche Energie zuführen, um durch die felsigen, unterirdischen Grenzen von Gnomeregan zu brechen und einem Gnomenangriff den Weg zu ebnen!", sourceObjective = "Holt das Gnoamsprenkelspross aus den Todesminen und bringt es Shoni der Schtillen in Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[2041] = { id = 2041, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sprecht mit Shoni", description = "Vielleicht... Vielleicht könnt Ihr uns im Kampf um Gnomeregan unterstützen.\n\nIn Sturmwind findet Ihr die Kommandantin unserer Untergrundkampftruppe, Shoni die Schtille. Shoni braucht Hilfe für ihre gyrobohrmatischen Exkavationatoren.\n\nIhr findet sie wahrscheinlich bei den Zwergen in Sturmwind.\n\nViel Glück, {name}.", sourceObjective = "Sprecht mit Shoni der Schtillen im Zwergendistrikt von Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[2078] = { id = 2078, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gyromasts Rache", description = "Landratte, Ihr müsst meinen Ersten Maat finden.\n\nNehmt diesen Schlüssel, steckt ihn in sein' Gulliver und schafft ihn her, dasser seim Käpt'n dient.\n\nDiese Murlocs und ihr Häuptling werden nich' so froh sein, wenn der Erste Maat sie zu fassen kriegt!", sourceObjective = "Sucht Gelkaks Ersten Maat, den Dreschonator 4100, und führt ihn zu Gelkak zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[2098] = { id = 2098, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gyromasts Rettung", description = "Das Piratenleben ist eines der Schwersten, Landratte. Es dreht sich nicht nur um Plündern und Saufen! Wehe, mein Schiff sank vor der Küste! Schuld daran sind diese dreisten Dreschadons.\n\nIch muss mein' Ersten Maat funktionstüchtig wiederham!\n\nAls ich an Land gespült wurde, zerbrach der Schlüssel für meinen Ersten Maat an den Felsen und wurde von den Biesterchen von Dunkelküste geraubt. Aus den Augenwinkeln sah ich tobende Kriecher, riesige Waldschreiter und Murlocs, die das Wrack durchstöberten...", sourceObjective = "Sucht die drei Stücke von Gelkaks Schlüssel und bringt sie Gelkak Gyromast.", sourceObjectiveStatus = "unverified-source-field" }
quests[2118] = { id = 2118, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verseuchtes Land", description = "Eine Erkrankung breitet sich in Dunkelküste aus und befällt Körper und Geist aller, die damit in Kontakt kommen.\n\nDie Distelbären wurden am schwersten von der Seuche getroffen. Die einst edlen Tiere sind jetzt ein Instrument der Zerstörung - tollwütig und rasend. Ich habe möglicherweise ein Heilmittel für dieses Leiden.\n\nGeht mit dieser Falle in den Wald und legt sie auf den Boden. Jeder tollwütige Distelbär, der das Licht kreuzt, wird für kurze Zeit friedfertig. Wenn der Bär erst einmal friedfertig ist, wird er Euch folgen. Führt ihn hierher, {name}.", sourceObjective = "Fangt einen lebenden tollwütigen Distelbären und bringt ihn zu Tharnariun.\n\nWendet Euch an Tharnariun Baumwahrer, falls Ihr fehlschlagen und Eure Falle verlieren solltet.", sourceObjectiveStatus = "unverified-source-field" }
quests[2138] = { id = 2138, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausrottung der Infizierten", description = "Wie ich befürchtete, das Heilmittel wirkt nicht.\n\nEs stimmt mich traurig, Geschöpfe der Natur zum Tode zu verurteilen, aber die kranken und besudelten Distelbären müssen ausgerottet werden.\n\nKehrt in den Wald zurück und vernichtet 20 tollwütige Distelbären, {name}. Das wird die Seuche sicher nicht stoppen, aber den Schaden, den die Tiere unserem Wald und seinen Bewohnern zufügen, zumindest für kurze Zeit verringern.", sourceObjective = "Befreit den Wald von 20 tollwütigen Distelbären und kehrt dann zu Tharnariun Baumwahrer in Dunkelküste zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[2139] = { id = 2139, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tharnariuns Hoffnung", description = "Das Überleben unseres Volkes und unserer Länder ist mit bedauerlichen Kosten verbunden, {name}.\n\nIhr habt das Blut der Diener der Natur vergossen; viele kranke Tiere habt Ihr erledigt. Das Volk von Auberdine steht in Eurer Schuld, denn die Qualen des Waldes sind gelindert - wenn auch nur vorübergehend.\n\nIch habe eine letzte Aufgabe für Euch, doch seid gewarnt, Ihr werdet wieder töten müssen. Dies wird hoffentlich das letzte Mal sein, dass ich Euch rufen muss, {name}.\n\nIn einer Höhle im Nordosten, nahe Bashal'Aran, haust die Höhlenmutter. Tötet sie.", sourceObjective = "Sucht und tötet die Höhlenmutter.", sourceObjectiveStatus = "unverified-source-field" }
quests[2158] = { id = 2158, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruhe und Entspannung", description = "Jeder Abenteurer sollte ausruhen, wenn ihn die Erschöpfung überkommt - und es gibt keinen besseren Platz für Ruhe und Entspannung als das Gasthaus \"Zur Höhle des Löwen\"!\n\nGastwirt Farley, der Inhaber der \"Höhle des Löwen\", ist mein bester Freund. Wenn Ihr ihm sagt, dass ich Euch geschickt habe, dann gewährt er Euch vielleicht einen Spezialrabatt auf Essen und Trinken.\n\nDas Gasthaus \"Zur Höhle des Löwen\" findet Ihr, wenn Ihr auf der Straße nach Süden reist - Ihr könnt es nicht verfehlen!", sourceObjective = "Sprecht im Gasthaus \"Zur Höhle des Löwen\" mit Gastwirt Farley.", sourceObjectiveStatus = "unverified-source-field" }
quests[2159] = { id = 2159, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lieferung für Dolanaar", description = "Seid mir gegrüßt, {class}. Könnt Ihr mir helfen? Ich habe ein Päckchen Kräuter, das ich in die Stadt Dolanaar liefern muss. Aber ich habe noch etwas mit den Druiden des Laubschattentals zu regeln und kann nicht weg.\n\nKönntet Ihr das Päckchen für mich zustellen? Es muss zu Gastwirt Keldamyr im Gasthaus von Dolanaar. Das liegt an der Straße nach Süden.", sourceObjective = "Bringt die Lieferung für Dolanaar zu Gastwirt Keldamyr.", progress = "Wie vermag ich Euch dienlich zu sein, junger Freund? Seid Ihr hier, um Euch im Gasthaus auszuruhen? Benötigt Ihr einen Ruhestein?", completion = "Ah, ja, die Lieferung Kräuter aus dem Laubschattental. Ein Jammer, dass Porthannius nicht selbst kommen konnte, denn wir hätten viel zu besprechen. Dennoch bin ich froh, dass ich die Kräuter habe und dass Ihr gekommen seid.\n\nBitte ruht Euch aus, solange Ihr hier seid. Helden müssen Körper und Geist fit halten und Ruhe und Entspannung suchen, wann immer sie können. Vernachlässigt man Ruhe für Körper und Geist, wird man keine Leistung bringen können.\n\nAlso... entspannt Euch eine Weile.", sourceObjectiveStatus = "unverified-source-field" }
quests[2160] = { id = 2160, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorräte für Tannok", description = "He! Ihr seht wie ein beherzter Abenteurer aus. Wenn Ihr vorhabt, den Pass zu überqueren, könntet Ihr da wohl ein Päckchen ins Gasthaus von Kharanos bringen?\n\nIhr hattet doch vor, im Gasthaus abzusteigen, nicht? Wenn Ihr den Pass bezwungen habt, werdet Ihr Euch dort ganz bestimmt etwas ausruhen wollen.\n\nWie auch immer, bringt das zu Tannok Frosthammer, dem Gehilfen des Gastwirts. Ich selbst kann nicht über den Pass und es dauert Tage, bis wieder eine Gebirgsjägereskorte vorbeikommt!", sourceObjective = "Bringt die Kiste mit Gasthausvorräten zu Tannok Frosthammer in Kharanos.", sourceObjectiveStatus = "unverified-source-field" }
quests[2161] = { id = 2161, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bürde eines Peons", description = "Entschuldigung? Könntet Ihr mir helfen?\n\nIch habe hier eine Ladung Essen. Ich bin die Straße entlanggelaufen und habe Skorpiden und Spinnen und Schlimmerem getrotzt! Ich habe das Essen ins Tal der Prüfungen gebracht, weil ich dachte, sie könnten es brauchen und weil ich gern behilflich bin. Aber sie brauchen kein Essen! Jetzt muss ich es nach Klingenhügel zurückbringen und fürchte mich vor den ganzen Bestien unterwegs...\n\nKönnt Ihr es für mich hinbringen? Ich bin nur ein Peon, Ihr aber seid <ein Held/eine Heldin>. Ihr fürchtet nichts!\n\nBringt es zu Gastwirt Grosk im Gasthaus von Klingenhügel. Danke!", sourceObjective = "Bringt Ukors Bürde zu Gastwirt Grosk in Klingenhügel.", sourceObjectiveStatus = "unverified-source-field" }
quests[2178] = { id = 2178, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schreitereintopf", description = "Riecht Ihr dieses köstliche Aroma? Das ist mein Geheimrezept, {name} - frischer Schreitereintopf. Köstlich!\n\nVielleicht möchtet Ihr das Rezept ja wissen?\n\nBevor ich Euch das Rezept verrate, müsst Ihr beweisen, dass Ihr den Wildtieren gewachsen seid.\n\nIch erwarte nicht, dass Ihr loszieht und eines zähmt und darauf zu mir zurückgeritten kommt, aber wenn Ihr einige Wildtiere töten könnt und mir etwas von ihrem saftigen Fleisch bringt, verrate ich Euch vielleicht das Schreiterrezept.", sourceObjective = "Bringt 5 Stücke Schreiterfleisch zu Alanndarian Nachtweise in Auberdine.", sourceObjectiveStatus = "unverified-source-field" }
quests[2198] = { id = 2198, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die zerrissene Halskette", description = "Ihr habt eine angelaufene Halskette gefunden, doch unter der Stumpfheit des Metalls lässt sich noch die feine und magische Handarbeit erkennen. Die Halskette ist beschädigt, in ihrer Fassung scheinen drei Edelsteine zu fehlen. Auf der Unterseite der Halskette kann man vage den Stempel des Stadtsiegels von Eisenschmiede erkennen. Unter dem Siegel befinden sich drei winzige eingravierte Buchstaben: \"TdK\".\n\nWenn Ihr etwas über die Halskette in Erfahrung bringen wollt, müsst Ihr herausfinden, woher sie stammt. Vielleicht sind das Siegel und die Initialen ein Anfang...", sourceObjective = "Sucht nach dem Erschaffer der zerrissenen Halskette, um etwas über ihren möglichen Wert zu erfahren.", sourceObjectiveStatus = "unverified-source-field" }
quests[2199] = { id = 2199, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lehren haben ihren Preis", description = "Ich genieße als Juwelier hier in Eisenschmiede ein hohes Ansehen! Oder sagen wir besser: Ich genoss es einmal. Dank der gemeinen Tricks eines Konkurrenten mache ich gerade eine schwere Zeit durch. In dieser Branche bedeutet ein schlechter Ruf das finanzielle Desaster. Und so muss ich feststellen, dass mein guter, wenn auch momentan leicht beschmutzter Name keinen roten Heller mehr wert ist.\n\nIch möchte, dass Ihr mir fünf Silberbarren beschafft, die ich für einen Auftrag brauche - den ersten seit einer Ewigkeit.\n\nBringt mir die fünf Silberbarren, dann beantworte ich Eure Fragen über die Halskette.", sourceObjective = "Bringt fünf Silberbarren zu Talvash del Kissel in Eisenschmiede.", sourceObjectiveStatus = "unverified-source-field" }
quests[2200] = { id = 2200, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr nach Uldaman", description = "Einer meiner Konkurrenten brachte das Gerücht in Umlauf, meine Halskette habe den Paladin verflucht. Und natürlich kauft einem Juwelier niemand verfluchte Gegenstände ab.\n\nIch schlag Euch etwas vor, {name}: Ihr findet die Edelsteine und ich repariere die Halskette - aber nur, wenn Ihr herumerzählt, dass ich KEINE verfluchten Gegenstände herstelle!\n\nFangt am besten an, in Uldaman nach Hinweisen zu suchen; vielleicht liegt der Paladin dort begraben, von ihm wissen wir, dass er die Kette als Letzter hatte! Wenn Ihr die Edelsteine gefunden habt, solltet Ihr dies hier benutzen; dadurch könnt Ihr mit mir in Eisenschmiede Kontakt aufnehmen.", sourceObjective = "Sucht in Uldaman nach Hinweisen auf den momentanen Zustand von Talvashs Halskette. Der getötete Paladin, den Talvash erwähnte, hatte die Kette zuletzt.\n\nBereitgestellter Gegenstand:", sourceObjectiveStatus = "unverified-source-field" }
quests[2201] = { id = 2201, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suche nach den Edelsteinen", description = "Das Tagebuch des Paladins liefert Euch die vielleicht einzigen Hinweise darauf, wo sich die Edelsteine aus der Halskette befinden könnten. Wenn der Paladin alles korrekt aufgezeichnet hat, dann müsst Ihr Euch um die Zwerge der Schattenschmiede und die Troggs kümmern, die um die Vorherrschaft über die Grabungsstätte konkurrieren.\n\nMit diesem Wissen bewaffnet, könnt Ihr Eure Suche nach den Edelsteinen jetzt ernsthaft beginnen. Sobald Ihr Euch alle Edelsteine angeeignet habt, solltet Ihr gemäß seinen Anweisungen Talvash in Eisenschmiede mithilfe der Wahrsagephiole informieren", sourceObjective = "Findet den Rubin, den Saphir und den Topas, die in ganz Uldaman verstreut sind. Wenn Ihr sie habt, wendet Euch aus der Ferne an Talvash del Kissel, indem Ihr die Wahrsagephiole nutzt, die er Euch zuvor gegeben hat.\n\nAus dem Tagebuch, wisst Ihr...\n* Der Rubin wurde in einer Bastion der Zwerge der Schattenschmiede versteckt.\n* Der Topas steckt in einer Urne in einem der Trogggebiete, in der Nähe einiger Zwerge der Allianz.\n\n* Der Saphir wurde von Grimlok, dem Anführer der Troggs, mitgenommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[2202] = { id = 2202, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uldaman Reagent Run" }
quests[2203] = { id = 2203, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reagenziensuche im Ödland II", description = "Ihr seid mir eine große Hilfe gewesen, {class}. Ich würde Euch ja das Rezept des Gebräus geben, das Ihr vorhin gekostet habt... doch zuvor muss ich Euch um einen gefährlichen Gefallen bitten. Hört meine Bitte.\n\nDiese Schließkassette enthält drei leere thaumaturgische Gefäße; sie sind mit einer Aura der Einstimmung magieerfüllt, die einem versengten Behütergroßdrachen das Blut aussaugt. Wenn Ihr sie gegen die Bestie benutzt, wird sie höchst erbost reagieren, also seid gewarnt. Bringt sie mir, wenn Ihr alle drei gefüllt habt.\n\nGelingt Euch das, gehört das Rezept Euch.", sourceObjective = "Benutzt die leeren thaumaturgischen Gefäße bei versengten Wächtergroßdrachen im Ödland. Wenn Ihr sie gefüllt habt, bringt sie zu Jarkal Moosblut in Kargath.", sourceObjectiveStatus = "unverified-source-field" }
quests[2204] = { id = 2204, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Restaurierung der Halskette", description = "Ihr müsst etwas \"Wumms\" für die Halskette finden und wenn ich es mir recht überlege, dann ist Uldaman sogar der beste Ort dafür. Ich vermute mal, da drinnen laufen eine Menge Konstrukte rum, hab ich Recht? Gut, dann sucht Euch das größte und böseste Konstrukt, das Ihr finden könnt, macht es fertig und schnappt Euch seine Kraftquelle! Ich bin mir ziemlich sicher, dass ich die Kraftquelle mit der Halskette verbinden kann.\n\nOhne die Kraftquelle wird es unmöglich sein, die Halskette zu reparieren! Kommt wieder zu mir nach Eisenschmiede zurück, wenn Ihr die Kraftquelle habt, dann repariere ich die Halskette für Euch.", sourceObjective = "Besorgt Euch eine Kraftquelle vom mächtigsten Konstrukt, das Ihr in Uldaman finden könnt, und liefert sie bei Talvash del Kissel in Eisenschmiede ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[2205] = { id = 2205, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufsuchen des SI:7", description = "Das Abzeichen? Oh, das ist gar nichts, Dumpfbacke – jedenfalls nichts, mit dem Ihr fertigwerden könntet. Wenn ich Euch so ansehe, würde ich sagen, dass Mathias Euch wahrscheinlich statt für einen anständigen Schurken für einen Käselieferanten halten wird. Aber wie dem auch sei, ich habe eine Aufgabe zugewiesen bekommen und ich habe versprochen, sie zu erledigen.\n\nDa wir gerade davon sprechen, bringt Mathias dieses Päckchen, dann gibt er Euch vielleicht eine kleine Aufgabe oder auch zwei.\n\nZischt ab.", sourceObjective = "Liefert Keryn Sylvius' Päckchen an Meister Mathias Shaw in der Kaserne von Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[2206] = { id = 2206, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schneller Eingriff", description = "Unsere Agenten vor Ort melden starke Banditenaktivitäten südlich von Goldhain. Die Berichte deuten an, dass die Banditen Jerods Anlegestelle erobert haben und sie nun benutzen, um große Mengen Hehlerware vom Rotkammgebirge nach Westfall zu schmuggeln.\n\nIhr müsst Euch in das Dockhaus einschleichen und mir den Lieferzeitplan beschaffen, {name}. Ihr findet ihn wahrscheinlich tief in den Taschen des Dockmeisters.\n\n... und, {name}, solltet Ihr entdeckt werden, wird der SI:7 strikt leugnen, dass er Euch kennt.", sourceObjective = "Sucht den Dockmeister der Defias und beschafft den Lieferzeitplan für Meister Mathias Shaw.", sourceObjectiveStatus = "unverified-source-field" }
quests[2218] = { id = 2218, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Straße der Rettung", description = "Eine weitere verirrte Seele, die nach Führung sucht, hm? Ich nehme an, Ihr wollt ein Ziel finden - Euer Ziel. Das habe ich schon tausend Mal gesehen, ein Held, der Arbeit sucht.\n\nAber heute ist Euer Glückstag. Hogral hat ein Heilmittel für Eure Leiden.\n\nIhr macht Folgendes: Schlagt diesen Weg nach Eisenschmiede ein und begebt Euch zum Düsteren Viertel. Wenn Ihr dort seid, sucht die Diebesgilde und sprecht mit Hulfdan Schwarzbart. Er wird Euch den Weg zur Rettung weisen.", sourceObjective = "Sprecht mit Hulfdan Schwarzbart in Eisenschmiede.", sourceObjectiveStatus = "unverified-source-field" }
quests[2238] = { id = 2238, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einfache List", description = "Ihr seht's ja, der König ist dabei, im Steinbruch nach Erz und Edelsteinen graben zu lassen. Mehr Reichtümer, als ein Zwerg normalerweise in zehn Leben zu sehen bekommen würde.\n\nDer Verborgene Kreis hat auch Werte, {name}. Wertsachen! Versteht Ihr, was ich meine?\n\nWir finden, der König sollte uns was von der Beute abgeben, aber der alte Stinkebart soll nicht erfahren, dass er was abgibt - ich hoffe, Ihr könnt mir folgen.\n\nIhr müsst mit Onin MacHammar drüben bei Gnomeregan reden und 'nen Bericht zurückbringen. Der listige Zwerg hat sich bei den Lepragnomen versteckt. Seid vorsichtig.", sourceObjective = "Sucht Onin MacHammar bei Gnomeregan.", sourceObjectiveStatus = "unverified-source-field" }
quests[2239] = { id = 2239, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Onins Bericht", description = "Der Steinbruch? Ja, ich sehe fast jeden Tag diese monströsen Dampfpanzer hier vorbeirollen.\n\nMeine Kontakte im Osten sagen mir, dass der Panzer in Eisenschmiede startet, im Steinbruch von Gol'Bolar seine Ladung abholt, zum Auftanken in Kharanos hält und dann aus einem unerfindlichen Grund den langen Weg um Gnomeregan herum fährt, ehe er seine Ladung in Eisenschmiede ablädt.\n\nEs steht alles in dem Bericht, {race}. Bringt ihn zu Hulfdan, damit er den nächsten Schritt planen kann.", sourceObjective = "Bringt Onins Bericht zu Hulfdan in Eisenschmiede.", sourceObjectiveStatus = "unverified-source-field" }
quests[2240] = { id = 2240, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die geheime Kammer", description = "Jetzt zur anstehenden Aufgabe:\n\nEs gibt eine geheime Kammer, die Kammer von Khaz'mul, die erforscht werden muss. Das Problem dabei ist, dass die Kammer hinter einer riesigen verschlossenen Tür liegt! Glücklicherweise weiß ich, wie man sie öffnet.\n\nIch habe alles in dem Tagebuch hier auf dem Tisch beschrieben. Meine Leute und ich sitzen hier zurzeit fest...also müsst Ihr die Kammer von Khaz'mul für uns finden, {name}.\n\nLest mein Tagebuch, erforscht die Kammer und meldet Euch dann bei Ausgrabungsleiter Sturmlanze in der Forscherliga in Eisenschmiede.", sourceObjective = "Lest Baelogs Tagebuch, erforscht die geheime Kammer und erstattet dann Ausgrabungsleiter Sturmlanze Bericht.", sourceObjectiveStatus = "unverified-source-field" }
quests[2241] = { id = 2241, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Apfel fällt", description = "Sie sagen, ich bin 'liebeskrank', was immer das heißen mag.\n\nKlar, ich denke ununterbrochen an Syurna. Klar, mein Haus ist voll von Bildern und Zeichnungen von Syurna. Klar, es kommt vor, dass ich tagelang nicht esse, schlafe oder trinke, während ich über die Liebe lamentiere, die uns nicht zuteil wurde. Ist das so falsch?\n\nJetzt will sie mich nicht sehen! MICH! Ich habe versucht, ihr Nachrichten zu schicken, aber sie redet mit keinem, es sei denn, er wäre ein Schurke.\n\nKönntet Ihr diese Blume zu ihr bringen? Und vergesst nicht, ihr zu sagen, dass sie von Jannok ist.", sourceObjective = "Bringt Jannoks Rose zu Syurna in Darnassus.", sourceObjectiveStatus = "unverified-source-field" }
quests[2242] = { id = 2242, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schicksal ruft", description = "Wir glauben, dass es ein Wesen gibt, das uns verstehen helfen könnte, was mit den Wäldern von Teldrassil geschieht. Leider hatte es verheerende Folgen, als wir versuchten, dieses Wesen zur Mitarbeit zu überreden.\n\nEr versteckt sich auf einem Ast am Rand der Lichtung des Orakels. Alle, die sich dem Satyr bisher genähert haben, sei es mit Gewalt oder Diplomatie, fanden ein böses Ende. Vielleicht ist Verstohlenheit die Lösung, {name}.\n\nFindet heraus, was Sethir der Uralte in seinen Rucksäcken hat und berichtet mir davon.", sourceObjective = "Sucht Sethir den Uralten und bringt alle Hinweise, die Ihr finden könnt, zu Syurna.", sourceObjectiveStatus = "unverified-source-field" }
quests[2258] = { id = 2258, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Badlands Reagent Run" }
quests[2259] = { id = 2259, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erion Schattenflüsterer", description = "Keine Bange, {name}, ich schicke Euch nicht zu Syurna. Erion verlangt nach Eurer Anwesenheit in der Enklave des Cenarius. Beeilung!", sourceObjective = "Kontaktiert Erion Schattenflüsterer in Darnassus.", sourceObjectiveStatus = "unverified-source-field" }
quests[2260] = { id = 2260, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erions Befehl", description = "Die Kunde von Euren Taten ist in aller Munde, {name}. Ihr seid so berühmt, dass der Geheimdienst von Sturmwind nach Euch persönlich gefragt hat.\n\nDie Reise ist anstrengend und nicht ungefährlich, aber die Gelegenheit einer Ausbildung beim SI:7 sollte man nicht in den Wind schlagen.\n\nEine neue Welt erwartet Euch, {name}. Begebt Euch in die Altstadt von Sturmwind und sprecht mit Renzik \"Das Messer\" im Hauptquartier des SI:7.", sourceObjective = "Reist nach Sturmwind und meldet Euch bei Renzik \"Das Messer\".", sourceObjectiveStatus = "unverified-source-field" }
quests[2278] = { id = 2278, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Platinscheiben", description = "Die Kernstücke dieser Schatzkammer sind vier riesige Platinscheiben, von denen jede mit zahlreichen Siegelzeichen unbekannter Herkunft bedeckt ist. Als Ihr sie berührt, beginnt Eure Hand zu kribbeln. Unmittelbar, nachdem Ihr die Scheiben berührt habt, erscheint das Gesicht eines großen Steinbeobachters.\n\n\"Willkommen. Ich bin ein Hüter des Wissens. Die Schöpfungssynthese der Irdenen wurde hier in den Scheiben von Norgannon für diese Welt aufgezeichnet und aufbewahrt.\"\n\nIhr habt eine Fülle an bislang unbekanntem Wissen über die Welt entdeckt!", sourceObjective = "Sprecht mit dem Steinbehüter und findet heraus, welche uralten Lehren er aufbewahrt. Sobald Ihr alles erfahren habt, was er weiß, aktiviert die Scheiben von Norgannon.", progress = "Die Stimme des Steinbeobachters scheint in jeder Faser Eures Körpers widerzuhallen:\n\n\"Ihr müsst zunächst den Datenaufnahmevoraussetzungen der Scheiben von Norgannon genügen. Sobald Ihr diese Bedingung erfüllt habt, wird es Euch erlaubt werden, eine tragbare Version der hier aufbewahrten Daten an Euch zu nehmen. Bitte stellt erst sicher, dass Ihr die Informationen in diesem Datenspeicher wirklich alle erkundet habt.\"", completion = "Ihr folgt den Anweisungen des Steinbehüters und greift noch einmal auf die Scheiben von Norgannon zu, nachdem Ihr jetzt die Geschichte der Irdenen, der Troggs und der Zwerge kennt. Aus dem Inneren der Scheiben ertönt ein kurzes, fast unhörbares Summen. Dann spricht der Steinbeobachter erneut:\n\n\"Die Scheiben sind jetzt synthetisiert. Greift noch einmal auf die Scheiben von Norgannon zu, um Euer persönliches Exemplar zu erhalten.\"", sourceObjectiveStatus = "unverified-source-field" }
quests[2279] = { id = 2279, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Platinscheiben", description = "Als Ihr die Scheiben von Norgannon ein weiteres Mal berührt, kribbelt Eure Hand erneut. Jetzt aber ist aus dem Inneren der Scheiben ein seltsames, knirschendes Geräusch zu hören.\n\nPlötzlich ist Euer Rucksack schwerer als noch eine Sekunde vorher. In seinem Inneren findet Ihr eine Miniaturausgabe der Scheiben!\n\nZweifellos wäre ein solcher Gegenstand von unschätzbarem Wert für jeden, der sich für die Frühgeschichte von Azeroth interessiert. Die Forscherliga in Eisenschmiede beispielsweise ist eine solche Gruppe und sie ist in der ganzen Allianz bekannt - vielleicht können die etwas mit diesem Fund anfangen.", sourceObjective = "Bringt die Miniaturausgabe der Scheiben von Norgannon zur Forscherliga nach Eisenschmiede.", sourceObjectiveStatus = "unverified-source-field" }
quests[2280] = { id = 2280, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Platinscheiben", description = "Als Ihr die Scheiben von Norgannon ein weiteres Mal berührt, kribbelt Eure Hand erneut. Jetzt aber ist aus dem Inneren der Scheiben ein seltsames, knirschendes Geräusch zu hören.\n\nPlötzlich ist Euer Rucksack schwerer als noch eine Sekunde vorher. In seinem Inneren findet Ihr eine Miniaturausgabe der Scheiben!\n\nZweifellos wäre ein solcher Gegenstand von unschätzbarem Wert für jeden, der sich für die Frühgeschichte von Azeroth interessiert. Irgendjemand wird sich mit Sicherheit dafür interessieren!", sourceObjective = "Bringt die Miniaturausgabe der Scheiben von Norgannon zu jemandem, der sich brennend dafür interessiert.", progress = "Was habt Ihr denn da? Was habt ihr von diesen Scheiben lernen können?", completion = "Diese Scheiben werden alles auf den Kopf stellen. Ihre Geheimnisse gehören nun uns.", sourceObjectiveStatus = "unverified-source-field" }
quests[2281] = { id = 2281, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rendezvous im Rotkammgebirge", description = "Euch jetzt in den Einsatz zu schicken wäre Selbstmord. Renzik braucht nicht noch einen toten Schurken. Aber keine Sorge, {name}... Renzik wird Euch schon Beine machen.\n\nGeht ins Rotkammgebirge und sprecht mit einem Mitglied des SI:7 namens Lucius. Ihr werdet ihn auf den Docks von Seenhain finden, wo er mit den anderen halbseidenen Taugenichtsen herumhängt.", sourceObjective = "Geht nach Seenhain im Rotkammgebirge und sprecht mit Lucius.", sourceObjectiveStatus = "unverified-source-field" }
quests[2282] = { id = 2282, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Althers Mühle", description = "Wir bilden hier schon seit Jahren Diebe aus! Schließlich wird nicht jeder Langfinger mit der Anmut und Finesse des alten Lucius geboren.\n\nOben an der Straße findet Ihr Althers Mühle. Ich habe dort oben eine Truhe mit wichtigem Inhalt. Holt sie für mich! Bringt mir diese Marke und Ihr bekommt Euer Zertifikat der Diebeskunst!", sourceObjective = "Öffnet Lucius' Schließkassette, nehmt die Marke der Diebeskunst heraus und bringt sie zu Lucius nach Seenhain.", sourceObjectiveStatus = "unverified-source-field" }
quests[2283] = { id = 2283, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiederbeschaffung der Halskette", description = "Wir haben Arbeit für Euch, falls Ihr den Mut habt, Euch daranzuwagen.\n\nTief im Ödland befindet sich Uldaman, eine Grabungsstätte. Wir haben eine Geschichte gehört von so einem dummen Paladin, der kürzlich dort gestorben ist. Das würde uns ja alles nicht interessieren, aber er hatte eine sehr wertvolle Halskette bei sich. Angeblich sind drei große Edelsteine dabei: ein Rubin, ein Saphir und ein Topas.\n\nKurz gesagt: Wir wollen die Kette haben und wir bezahlen GUTES SILBER, um sie zu kriegen. Vielleicht ist sie beschädigt, aber das tut nichts zur Sache. Wir reparieren sie, wenn Kratzer daran sein sollten.", sourceObjective = "Sucht in der Grabungsstätte von Uldaman nach einer wertvollen Halskette und bringt sie nach Orgrimmar zu Dran Droffers. Die Halskette ist vielleicht beschädigt.", sourceObjectiveStatus = "unverified-source-field" }
quests[2284] = { id = 2284, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiederbeschaffung der Halskette, Teil 2", description = "Genauso sicher, wie Malton ein Idiot ist, sind diese Edelsteine noch irgendwo in Uldaman. Ihr werdet wohl dorthin zurückgehen müssen und nach ihnen suchen.\n\nIch hab's ja schon mal gesagt: Wenn unsere Informationen stimmen, dann gehören zu der Halskette ein Rubin, ein Saphir und ein Topas. Findet sie und fügt sie in die Halskette ein.\n\nAber wo die Edelsteine sind - wer weiß das schon? Vielleicht habt Ihr ja Glück und findet die Leiche dieses Paladins. Wenn er noch nicht völlig ausgeplündert worden ist, dann hat er sie ja vielleicht sogar bei sich.", sourceObjective = "Sucht in den Tiefen von Uldaman nach einem Hinweis auf den Verbleib der Edelsteine.", sourceObjectiveStatus = "unverified-source-field" }
quests[2298] = { id = 2298, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Königliche Erpressung", description = "Wir war'n also grade dabei, Phase III zu planen, da platzen 'n paar von Magnis Holzköpfen hier rein, schwafeln was von 'ner Art Razzia und verhaften ein paar vom Verborgenen Kreis.\n\nSo springt keiner mit dem alten Schwarzbart um! Die Diskussion wurde immer hitziger und irgendwann fiel Euer Name!\n\nMein Rat? Nehmt den ersten Greif aus Eisenschmiede raus und geht nach Sturmwind. Geht in die Altstadt und sprecht dort mit einem alten Freund von mir, der Renzik \"Das Messer\" genannt wird.", sourceObjective = "Reist nach Sturmwind und sucht Renzik \"Das Messer\" auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[2299] = { id = 2299, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Hulfdan!", description = "Wo seid Ihr gewesen, {name}? Hulfdan sucht schon überall nach Euch. Wir dachten schon, der König hätte Euch in Eisen legen lassen.\n\nGeht so schnell wie möglich nach Eisenschmiede und sprecht mit Hulfdan!", sourceObjective = "Reist nach Eisenschmiede und sprecht mit Hulfdan Schwarzbart.", sourceObjectiveStatus = "unverified-source-field" }
quests[2300] = { id = 2300, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der SI:7", description = "Renzik hat nach Euch gesucht, Dumpfbacke.\n\nIch an Eurer Stelle würde Mathias' Stellvertreter nicht warten lassen.", sourceObjective = "Reist nach Sturmwind und sucht Renzik \"Das Messer\" auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[2318] = { id = 2318, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Übersetzung des Tagebuchs", description = "Ihr befindet Euch in einer Art Sackgasse, denn Ihr wisst, dass Ihr das Buch erst in eine Sprache übersetzen lassen müsst, die Ihr versteht. Es gibt etliche Leute auf der Welt, die das machen könnten - der nächste Ort, wo sich vielleicht jemand finden ließe, der dazu in der Lage ist, wäre vermutlich der Kargath-Außenposten im Ödland. Vielleicht wäre das ein guter Ort, um anzufangen.", sourceObjective = "Sucht jemanden, der das Tagebuch des Paladins übersetzen kann. Der nächstgelegene Ort, wo Ihr so jemanden finden könntet, ist Kargath im Ödland.\n\nBereitgestellter Gegenstand:", sourceObjectiveStatus = "unverified-source-field" }
quests[2338] = { id = 2338, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Übersetzung des Tagebuchs", description = "Droffers und Sohn Bergungen' sind nicht schlau genug, die Magie der Halskette wiederherzustellen, aber ich kann es. Ich muss nur die Halskette studieren, damit ich lerne, wie ich selbst solche Ketten herstellen kann. Und dazu benötige ich Eure Halskette. Leiht sie mir, und im Gegenzug für die Zeit, in der ich die Kette studieren kann, werde ich das Tagebuch für Euch übersetzen. Ich sollte genug Zeit haben, alles Nötige zu erfahren, während Ihr nach den Edelsteinen sucht.\n\nEs ist ein einfacher Handel und niemand wird etwas davon erfahren. Also, was sagt Ihr?", sourceObjective = "Leiht Jarkal die Halskette. Im Gegenzug wird er das Tagebuch für Euch übersetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[2339] = { id = 2339, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Findet die Edelsteine und die Kraftquelle", description = "Hier ist das Tagebuch, übersetzt, sodass Ihr es lesen könnt. Kurz gesagt steht darin, dass Zwerge den Rubin versteckt haben, Troggs versteckten den Topas und ein Trogg namens Grimlok hat den Saphir.\n\nEs ist so, Ihr braucht eine Kraftquelle, um die Halskette wieder funktionstüchtig zu bekommen. Dran Droffers weiß das nicht. Um eine Kraftquelle zu finden, würde ich Folgendes tun: Begebt Euch so tief wie möglich nach Uldaman hinein und tötet das stärkste Konstrukt, das Ihr finden könnt. Ich zweifle nicht daran, dass das stärkste Konstrukt dort auch dasjenige ist, das die Kraftquelle hat.\n\nWenn Ihr alles zusammenhabt, dann kommt wieder hierher!", sourceObjective = "Beschafft in Uldaman alle drei Edelsteine sowie eine Kraftquelle für die Halskette und bringt sie anschließend zu Jarkal Moosblut nach Kargath. Jarkal glaubt, dass sich eine Kraftquelle vielleicht im stärksten Konstrukt in Uldaman findet.\n\nAus dem Tagebuch, wisst Ihr...\n* Der Rubin wurde in einer Bastion der Zwerge der Schattenschmiede versteckt.\n* Der Topas steckt in einer Urne in einem der Trogggebiete, in der Nähe einiger Zwerge der Allianz.\n* Der Saphir wurde von Grimlok, dem Anführer der Troggs, mitgenommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[2340] = { id = 2340, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ablieferung der Edelsteine", description = "Jede Halskettenfassung und jeder Edelstein wird funktionieren, solange sie aus demselben Material bestehen. Doch es ist die Kraftquelle, die der Halskette die Magie wieder zurückgeben wird. Hoffe ich zumindest.\n\nIch werde Euch gern die Edelsteine zur Verfügung stellen, die Ihr für Eure Version der Halskette benötigt, wenn die Kraftquelle einwandfrei funktioniert.\n\nBegebt Euch nach Orgrimmar und haltet Euren Teil der Abmachung mit 'Droffers und Sohn Bergungen' ein. Haltet lediglich den Mund über unser Geschäft, und wenn Ihr zurückkommt, habe ich vielleicht schon eine wundervolle Überraschung für Euch.", sourceObjective = "Liefert die Halskette und die geborgenen Edelsteine bei Dran Droffers in Orgrimmar ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[2341] = { id = 2341, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiederbeschaffung der Halskette, Teil 3", description = "Als Dran und Malton Droffers anfangen, sich um ihr neues Bergegut zu zanken, ist die Hälfte des Geschäftes bereits erledigt. Jetzt steht noch eine Reise ins Ödland an, um dort die Sache zum Abschluss zu bringen, denn Jarkal Moosblut aus Kargath hat eine besondere Belohnung für Euch in petto - oder vielleicht auch nicht.", sourceObjective = "Besucht Jarkal Moosblut in Kargath, um festzustellen, ob er Erfolg gehabt hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[2342] = { id = 2342, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiederbeschaffte Schätze", description = "Die Fledermausgehege mit diesem Besen auszukehren, das ist keine Aufgabe, die eines Garretts würdig wäre! Aber ich habe mit diesem verfluchten Job ein wenig Geld verdient und ich bin bereit, es für Euch auszugeben, wenn ich damit nur meine Situation verbessern kann.\n\nDie Lieblingswaffe der Familie Garrett liegt weggeschlossen in unserer Truhe in der Südlichen Bankenhalle von Uldaman. Das rührt noch von den Zeiten her, da wir Garretts dort als Buddler schufteten. Ohne sie werde ich für alle Zeiten hier festsitzen und im wahrsten Sinne des Wortes diesen höllischen Fledermäusen hinterherkehren.\n\nBeschafft den Schatz meiner Familie wieder und bringt ihn mir! Helft mir dabei, mein Geburtsrecht einzufordern!", sourceObjective = "Holt Patrick Garretts Familienschatz aus der Truhe der Familie in der Südlichen Bankenhalle von Uldaman und bringt diesen zu ihm nach Unterstadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[2358] = { id = 2358, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hörner von Nez'ra", description = "Vor vielen Jahren wurden die Hörner von Nez'ra aus dem Rabenholdtanwesen gestohlen. Über Ozeane und Kontinente hinweg habe ich nach ihnen gesucht, nur um schließlich zu erfahren, dass diese unbedeutenden Bestien sie die ganze Zeit über im Besitz hatten.\n\nErschlagt jeden Schwarzfelsorc, auf den Ihr trefft, bis Ihr die Hörner von Nez'ra wiedererlangt habt. Solltet Ihr die Hörner in Euren Besitz bekommen, dann sucht mich in Seenhain auf.\n\nWenn Ihr dies für mich tut, soll Euer Name in Rabenholdt Bekanntheit erlangen, {name}.", sourceObjective = "Bringt die Hörner von Nez'ra zu Arantir nach Seenhain.", sourceObjectiveStatus = "unverified-source-field" }
quests[2359] = { id = 2359, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klavens Turm", description = "Ich überwache diesen Turm jetzt schon seit Wochen, {name}. Kürzlich kam eine größere Lieferung aus dem Dämmerwald an und mit dieser Lieferung kamen auch diese Wachen.\n\nWas sie sind? Das weiß ich genauso wenig wie Ihr. Eines kann ich Euch aber sagen: Menschen sind das nicht.\n\nWie dem auch sei, bei der Lieferung war eine Truhe dabei und ich vermute mal, das ist es, was diese Monstrositäten bewachen. Die Kreatur mit den Stacheln hat einen Schlüssel, den wir brauchen.\n\nBeschafft Euch den Schlüssel, dringt in den Turm ein und stellt fest, was in dieser Truhe ist. Berichtet dann Mathias, was Ihr herausgefunden habt.", sourceObjective = "Stehlt den Turmschlüssel der Defias, brecht in den Turm der Defias ein und stellt fest, was sich in der Dämmerwaldtruhe befindet. Bringt Mathias Shaw in Sturmwind dann alle Informationen über das, was Ihr herausgefunden habt. Lest Kearnens Tagebuch, um neue Erkenntnisse über den Turm zu erlangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[2360] = { id = 2360, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mathias und die Defias", description = "Keinen Moment zu früh, {name}. Spähtrupps des SI:7 berichten von ungewöhnlich intensiven Aktivitäten der Defias in Westfall.\n\nEs sieht so aus, als hätten die Defias einen verlassenen Wachturm der Allianz südlich der Späherkuppe übernommen und verwendeten diesen als Operationsbasis, um Güter von der Lieferroute ins Rotkammgebirge hereinzuschmuggeln.\n\nBegebt Euch nach Westfall und kontaktiert Agentin Kearnen. Sie wird Euch Bericht erstatten. Sie hält sich in der Nähe des Turms versteckt; dort findet Ihr sie.\n\n... und, {name}, solltet Ihr entdeckt werden, wird der SI:7 strikt leugnen, dass er Euch kennt.", sourceObjective = "Reist nach Westfall und sucht Agentin Kearnen. Sie wird Euch Bericht erstatten.", sourceObjectiveStatus = "unverified-source-field" }
quests[2361] = { id = 2361, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Restaurierung der Halskette" }
quests[2378] = { id = 2378, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suche nach der Zerschmetterten Hand", description = "Ihr habt den Schattenpirschern gut gedient, {name}, aber vielleicht ist es an der Zeit, dass Ihr Euch nach draußen wagt. Zwar habt Ihr schon gezeigt, dass Ihr in der Kunst der Verstohlenheit und der Täuschung bewandert seid, doch Eure Ausbildung ist noch lange nicht beendet.\n\nDie Schattenpirscher haben Verbündete bei der Zerschmetterten Hand. Sucht jemanden auf, der nichts dagegen hat, uns zu helfen: Shenthul in Orgrimmar.", sourceObjective = "Reist nach Orgrimmar und sprecht an der Kluft der Schatten mit Shenthul.", sourceObjectiveStatus = "unverified-source-field" }
quests[2379] = { id = 2379, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zando'zan", description = "Entschlossenheit allein reicht nicht aus, um die Hindernisse zu überwinden, die vor uns liegen.\n\nSprecht mit Zando'zan, um Eure Ausbildung als <Agent/Agentin> der Zerschmetterten Hand zu beginnen.\n\nErst wenn Ihr die Kunst der Verstohlenheit und die Diebeskunst gemeistert habt, könnt Ihr den nächsten Schritt auf Eurem persönlichen Weg des Schicksals gehen.", sourceObjective = "Sprecht an der Kluft der Schatten mit Zando'zan.", sourceObjectiveStatus = "unverified-source-field" }
quests[2380] = { id = 2380, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach Orgrimmar!", description = "Noch seid Ihr <kein Meister/keine Meisterin> der Verstohlenheit und der Täuschung, doch das kann und wird sich alles ändern. Ganz offensichtlich habt Ihr die da oben mit Euren dürftigen Fähigkeiten beeindruckt, denn der große Shenthul selbst hat nach Euch gefragt.\n\nReist auf der Straße nördlich von hier nach Orgrimmar und sprecht in der Kluft der Schatten mit Shenthul.", sourceObjective = "Sprecht an der Kluft der Schatten in Orgrimmar mit Shenthul.", sourceObjectiveStatus = "unverified-source-field" }
quests[2381] = { id = 2381, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plundering the Plunderers" }
quests[2382] = { id = 2382, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wrenix aus Ratschet", description = "Zando'zan hat es gesehen! Ja, der Tag wird kommen! Thralls Tod... der Dolch in seinem Rücken, das Gift, das durch seine Adern fließt... Zando'zan hat schon zu viel gesagt.\n\n{name}! Zando'zan hat eine Aufgabe für {name}! {name} muss nach Ratschet reisen, östlich des Wegekreuzes, und mit Wrenix dem Jämmerlichen sprechen. Los!", sourceObjective = "Reist nach Ratschet im Brachland und sprecht mit Wrenix dem Jämmerlichen.", sourceObjectiveStatus = "unverified-source-field" }
quests[2383] = { id = 2383, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einfaches Pergament", description = "Ah, während Ihr fort wart, kam ein Pergament für Euch, {name}.\n\nLest es, wenn Ihr Zeit habt. Wenn ich mich nicht irre, kam es vom Kriegerlehrer Frang. Er würde gern mit Euch sprechen, wenn Ihr bereit seid. Ihr findet ihn außerhalb des Höhlenbaus, wo er sich in den Schatten verbirgt.", sourceObjective = "Lest das einfache Pergament und sprecht mit Frang im Tal der Prüfungen.", sourceObjectiveStatus = "unverified-source-field" }
quests[2398] = { id = 2398, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die verschollenen Zwerge", description = "Die Grabungsstätte von Uldaman war nicht immer so überlaufen. Wir Zwerge von Eisenschmiede kontrollierten früher das Gebiet, aber... das war, bevor die Troggs kamen. Sie kamen so schnell und waren so zahlreich, dass nicht einmal die Macht der Zwerge sie aufhalten konnte.\n\nUm ehrlich zu sein, kam ihr Angriff so plötzlich, dass ich fürchte, dass vielleicht einige unserer Leute hinter den feindlichen Linien festsitzen.\n\nMein Freund Baelog hatte eine kleine Gruppe Zwerge tief hinunter in die Grabungsstätte geführt, kurz bevor die Troggs auftauchten. Wenn er und seine Gefährten noch leben, dann möchte ich, dass Ihr sie findet.", sourceObjective = "Sucht in Uldaman nach Baelog.", sourceObjectiveStatus = "unverified-source-field" }
quests[2399] = { id = 2399, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die sprießenden Wedel", sourceObjective = "Die Wedel, die Denalan in seinem Garten angepflanzt hat, sind gesprossen und gediehen. Sie zittern leicht, als wollten sie gepflückt werden...", sourceObjectiveStatus = "unverified-source-field" }
quests[2418] = { id = 2418, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kraftsteine", description = "Vor einiger Zeit hatte ich einen kleinen Zwischenfall mit den Zwergen der Schattenschmiede. Sie brachten mich in die Festung Angor, um dort zwei Arten von seltsamen Steinen zu untersuchen, wie sie in Uldaman vorkommen. Ich habe entdeckt, dass die Steine langlebige und stabile Kraftquellen darstellen, wenn sie richtig behandelt werden. Es ist schon erstaunlich, was man alles in dieser alten Grabungsstätte finden kann!\n\nJedenfalls warfen sie mich aus der Festung Angor raus, nachdem ich ihnen das Geheimnis der Steine verraten hatte, und begannen, in Uldaman nach weiteren Steinen zu graben.\n\nIch will diese Steine für mich! Bringt mir beide Arten von Steinen und ich bezahle Euch gut dafür!", sourceObjective = "Bringt Riggelfuzz im Ödland 8 Kraftsteine aus Dentrium und 8 Kraftsteine aus An'Alleum.", sourceObjectiveStatus = "unverified-source-field" }
quests[2438] = { id = 2438, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Smaragdgrüne Traumfänger", description = "Einst erhielt ich von Gaerolas Talvethren, dem Bewacher der Druiden im Grabhügel von Ban'ethil, einen smaragdgrünen Traumfänger. Dieses mächtige Amulett ist in der Lage, Energie aus dem Smaragdgrünen Traum abzuziehen und damit denen, die es tragen, Glück zu bringen.\n\nLeider habe ich den Traumfänger nicht mehr aus meiner Kommode in Sternenhauch holen können. Sternenhauch war einst ein ruhiger Ort, aber jetzt ist er durch die Furbolgs, die sich dort aufhalten, der Verderbnis anheim gefallen.\n\nWärt Ihr vielleicht bereit, mir meinen Traumfänger wiederzubeschaffen, {class}?", sourceObjective = "Bringt den Smaragdgrünen Traumfänger an Euch.", progress = "Bitte sputet Euch. Ich kann nur hoffen, dass mein smaragdgrüner Traumfänger von den Furbolgs nicht beschädigt wurde.\n\nHabt Ihr ihn schon zurückgeholt, {name}?", completion = "Mein smaragdgrüner Traumfänger ist mir äußerst wichtig. Er ist ein Geschenk, das nicht jedem zuteil wird. Danke, dass Ihr ihn zurückgebracht habt, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[2439] = { id = 2439, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Platinscheiben", description = "Dieser Gegenstand ist ein unglaublicher Fund. Die alten Titanen oder 'Schöpfer', wie sie auf diesen Scheiben genannt werden, sind die Verbindung zu unserer verzauberten Erschaffung, wenn das hierin gespeicherte Wissen korrekt ist! Wir werden uns so eingehend wie möglich mit diesen Scheiben beschäftigen.\n\nWas Euch betrifft, {class}: Bringt diesen Gutschein zu Dinita Zasterstein in dem Gewölbe. Für ihn erhaltet Ihr etwas, das meiner Meinung nach eines solch unglaublichen Fundes würdig ist.\n\nKehrt umgehend zu mir zurück, wenn Ihr fertig seid - es gibt noch viel mehr für die Forscherliga zu tun!", sourceObjective = "Bringt Euren Belohnungsgutschein zu Dinita Zasterstein im Tresor von Eisenschmiede.", sourceObjectiveStatus = "unverified-source-field" }
quests[2440] = { id = 2440, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Platinscheiben", description = "Ich werde all meine Energien auf diese Scheiben fokussieren; wenn die Zeit gekommen ist, werden sie mir ihre Funktionsweise schon verraten.\n\nWas Euch betrifft, {name}, nun, Ihr sollt dafür belohnt werden, dass Ihr mir diese Sache kundgetan habt. Bringt den Belohnungsgutschein zu Bena Winterhuf, der Alchemielehrerin in Donnerfels. Sie wird Euch einen speziellen Gegenstand geben, der Euch bestimmt gefällt, und außerdem erhaltet Ihr von ihr eine Auswahl an Tränken aus meinem persönlichen Vorrat.\n\nKehrt bald zu mir zurück... ich spüre, dass wir in Bezug auf diesen Fund noch viel mehr zu tun haben.", sourceObjective = "Bringt den Belohnungsgutschein zu Bena Winterhuf nach Donnerfels.", sourceObjectiveStatus = "unverified-source-field" }
quests[2458] = { id = 2458, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Undercover", description = "Die Venture Company... Vielleicht habt Ihr von den Leuten schon gehört?\n\nEin Jahr lang haben wir daran gearbeitet, einen Agenten in ihre Reihen einzuschleusen. Endlich hatten wir - dank harter Arbeit und präziser Planung - Erfolg.\n\nVor Kurzem haben wir jetzt gehört, dass die Venture Company irgendetwas Großes plant. Begebt Euch zum Turm der Venture Company nördlich des Schlickmoores und kontaktiert dort unseren Undercover-Agenten, Zuchtmeister Fitzel.\n\nSobald Ihr den Turm gefunden habt, verwendet diese Leuchtfeuerwaffe und grüßt ihn mit dem Gruß der Zerschmetterten Hand.", sourceObjective = "Reist zum Turm der Venture Company nördlich des Schlickmoores und kontaktiert dort den Agenten der Zerschmetterten Hand, Zuchtmeister Fitzel.\n\nSobald der Turm in Sichtweite ist, verwendet die Leuchtfeuerwaffe, um Zuchtmeister Fitzel Eure Ankunft anzuzeigen. Feuert ZWEI Leuchtfeuergeschosse ab, nähert Euch dann Zuchtmeister Fitzel und zeigt den Gruß der Zerschmetterten Hand.\n\nEs ist wichtig, dass Ihr diese Aktionen in der richtigen Reihenfolge durchführt, da Fitzel jede Person, die er nicht erkennt, angreift und eliminiert.\n\nBereitgestellter Gegenstand:", sourceObjectiveStatus = "unverified-source-field" }
quests[2459] = { id = 2459, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ferocitas der Traumfresser", description = "Der Smaragd... Er ist weg! Mein Traumfänger ist beschädigt!\n\nEine Gruppe von Knarzklauenmystikern lebt im Norden von Sternenhauch. Ich habe gehört, dass ihr Anführer, Ferocitas der Traumfresser, seit einiger Zeit eine Halskette trägt, die des Nachts grün leuchtet. Jetzt, wo ich meinen Traumfänger sehe, bin ich mir sicher, dass er meinen Smaragd gestohlen hat... Er würde nie verstehen, dass dessen Macht völlig nutzlos für ihn ist.\n\nFindet das verlorene Juwel, {name}. Und wenn Ihr schon mal dort seid, erledigt auch gleich einige dieser verderbten Mystiker.", sourceObjective = "Tötet 7 Mystiker der Knarzklauen und findet das verlorene Juwel.", progress = "Ferocitas und die Knarzklauenmystiker müssen mir zurückgeben, was mir gehört. Bitte holt den Smaragd zurück, damit ich meinen smaragdgrünen Traumfänger reparieren kann.", completion = "Jetzt kann ich meinen Traumfänger reparieren. Danke, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[2460] = { id = 2460, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Gruß der Zerschmetterten Hand", description = "Als ein Schurke der Zerschmetterten Hand müsst Ihr unbedingt den geheimen Gruß erlernen. Dies ist die einzige Methode, mit der man ein anderes Mitglied der Hand zweifelsfrei identifizieren kann.\n\nSchaut zu, lernt, wiederholt.", sourceObjective = "Führt Shenthul gegenüber den Gruß der Zerschmetterten Hand aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[2478] = { id = 2478, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission: möglich, aber nicht sehr wahrscheinlich", description = "Ihr müsst den Turmschlüssel von Großknecht Silixiz stehlen, {name}. Sobald sich der Schlüssel in Eurem Besitz befindet, haltet ihn gut fest - ich könnte ihn später brauchen.\n\nVergesst nicht, das Gift hat alles in diesem Turm geschwächt. Wendet Eure Fähigkeiten an, um unter seinen Bewohnern Chaos und Zerstörung zu verbreiten. Erschlagt sie alle - zeigt keine Gnade!\n\nSobald sich dort drinnen nichts mehr rührt, knackt Ihr das Schloss von Gallywix' Schließkassette und stehlt den Vorrat an Zanzils Mixtur, der sich darin befindet. Bringt Shenthul in Orgrimmar sowohl Gallywix' Kopf als auch die Mixtur.", sourceObjective = "Stehlt Silixiz' Turmschlüssel von Großknecht Silixiz. Tötet dann 2 mutierte Drohnen der Venture Co., 2 Patrouillen der Venture Co. und 2 Ausgucker der Venture Co.\n\nEliminiert den obersten Großknecht Gallywix und nehmt seinen Kopf. Knackt dann das Schloss von Gallywix' Schließkassette und stehlt den Vorrat an Zanzils veränderter Mixtur. Bringt den Vorrat und Gallywix' Kopf zu Shentul nach Orgrimmar; er wird Euch weitere Anweisungen geben.", sourceObjectiveStatus = "unverified-source-field" }
quests[2479] = { id = 2479, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinotts Hilfe", description = "Bringt eine Probe der Mixtur zu Serge Hinott nach Tarrens Mühle.\n\nWenn Euch überhaupt irgendjemand heilen kann, dann ist das Serge. Falls Ihr lange genug lebt, kann Serge Euch in der Kunst der Herstellung und Anwendung von Giften unterweisen.", sourceObjective = "Reist nach Tarrens Mühle im Vorgebirge des Hügellands und liefert die Probe von Zanzils Mixtur bei Serge Hinott ab.\n\nUm nach Tarrens Mühle zu kommen, müsst Ihr den Zeppelin nach Unterstadt nehmen und dann auf der Straße nach Süden durch den Silberwald in Richtung Hügellandhof reisen. Folgt den Schildern!", sourceObjectiveStatus = "unverified-source-field" }
quests[2480] = { id = 2480, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinotts Hilfe", description = "Noch nie habe ich gesehen, dass ein Gift so wundervolle Auswirkungen hatte! Zanzil, sagt Ihr? Nie von ihm gehört. Aber ich muss ihm zur Kreation dieses Gebräus gratulieren.\n\nTja, ich soll Euch also hiervon heilen und Euch dann beibringen, wie man das Gift anwendet?\n\nGebt mir einen Moment Zeit, damit ich das Toxin untersuchen kann, {name}.", sourceObjective = "Wartet auf Serge Hinott, um das Heilmittel fertig zu stellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[2498] = { id = 2498, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Denalan", description = "Ich habe gerade erfahren, dass Denalan am Al'Amethsee herausgefunden hat, was der Grund für die Tumore sein könnte, von denen die Bäumlinge befallen sind. Bitte sprecht mit ihm und sagt ihm, dass ich Euch geschickt habe.\n\nSputet Euch, {name}; er braucht unsere Hilfe.", sourceObjective = "Rellian Grünwipfel möchte, dass Ihr am Al'Amethsee mit Denalan sprecht.", sourceObjectiveStatus = "unverified-source-field" }
quests[2499] = { id = 2499, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grimmeiche", description = "Ich habe es! Ich musste einfach hierher eilen, um Euch zu finden! Es ist eigentlich so einfach... die Verderbnis hat sich von Bäumling zu Bäumling verbreitet, doch ein einziger von ihnen ist die Quelle.\n\nGrimmeiche wird von dem größten Tumor vergiftet, den ich je gesehen habe... ich würde ihn sogar als riesengroß beschreiben.\n\nGrimmeiche lebte früher in einer Höhle in der Nähe meines Sees, hat aber seitdem einen Schlupfwinkel im Nordosten des Quellsees gefunden. {name}, macht Grimmeiche ausfindig und sammelt seinen Tumor ein; entfernt den Ursprung dieser Verderbnis aus meiner Heimat.", sourceObjective = "Erhaltet den riesengroßen Tumor von Grimmeiche.", progress = "Habt Ihr Grimmeiche schon gefunden, {race}?", completion = "Ich wusste doch, dass Ihr bestens in der Lage sein würdet, den See von dieser schrecklichen Bestie zu befreien.\n\nEs ist schon traurig: Einst war Grimmeiche ein großer Anführer unter seinesgleichen... Aber die Verderbnis unterscheidet leider nicht zwischen dem Geringen und dem Edlen.\n\nDie Größe dieses Tumors ist erschreckend. Aber ich muss ihn studieren, um mehr über diese Seuche herauszufinden, von der alle Bäumlinge betroffen sind.\n\nDanke, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[2500] = { id = 2500, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reagenziensuche im Ödland", description = "{class}, ich möchte Eure Dienste in Anspruch nehmen. Ich bin ein angesehener Alchemist und benötige Eure Unterstützung, um einige Reagenzien zu beschaffen, die im Ödland zu finden sind.\n\nIch brauche folgende Gegenstände, um meine Vorräte aufzufüllen: 5 Bussardmuskelmägen, 10 Klippenkojotenfangzähne und 5 Felselementarsplitter. Natürlich könnt Ihr Euch diese Reagenzien von den Viechern selbst holen; aber wenn Ihr keine Kämpfernatur seid, dann sucht Euch besser Freunde, die kämpfen können.\n\nBringt mir diese Gegenstände, dann springen ein paar Münzen für Euch dabei heraus.\n\nAlso, was sagt Ihr?", sourceObjective = "Beschafft die Reagenzien, die Ghak Heilsegen aus dem Ödland braucht, und bringt sie ihm nach Thelsamar.", sourceObjectiveStatus = "unverified-source-field" }
quests[2501] = { id = 2501, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reagenziensuche im Ödland II", description = "Ihr seid mir eine große Hilfe gewesen, {name}. Ich würde Euch gern das Rezept des Gebräus geben, das Ihr vorhin gekostet habt... doch zuvor muss ich Euch um einen recht gefährlichen Gefallen bitten.\n\nDiese Schließkassette enthält drei leere thaumaturgische Gefäße; sie sind mit einer Einstellungs-Aura magieerfüllt, die einem versengten Wächtergroßdrachen das Blut aussaugt. Wenn Ihr ein solches Gefäß gegen die Bestie einsetzt, wird sie höchst erbost reagieren, also seid vorsichtig. Bringt sie mir, wenn Ihr alle drei gefüllt habt.\n\nGelingt Euch das, gehört das Rezept Euch.", sourceObjective = "Benutzt die leeren thaumaturgischen Gefäße bei versengten Wächtergroßdrachen im Ödland. Wenn Ihr sie gefüllt habt, bringt sie zu Ghak Heilsegen in Thelsamar.", sourceObjectiveStatus = "unverified-source-field" }
quests[2518] = { id = 2518, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tränen des Mondes", description = "Einst wurde Lady Sathrah von Elune geliebt. Grazil und rein spann die Spinne ihre silbernen Fäden im Mondlicht, wo sie den Abendnebel einfingen. Der silbrige Tau hatte starke Heilkräfte und wurde darum hier im Tempel aufbewahrt.\n\nDoch in jüngster Zeit ist Sathrah dem Wahnsinn verfallen. Auch die ihr nachfolgenden Generationen sind nun gefährdet.\n\nFindet Lady Sathrah, {name}, und beendet ihr Leiden. Sie hält sich nordöstlich von hier am Fluss auf. Sammelt ihre silbrigen Spinndrüsen und bringt sie mir.", sourceObjective = "Erhaltet Lady Sathrahs silbrige Spinndrüsen.", progress = "Ich bedauere, dass ich Euch vor diese Aufgabe stellen muss, aber für Lady Sathrah gibt es keine Hoffnung mehr.\n\nMit den Spinndrüsen wollen wir Elune ein Opfer bringen. Wir hoffen, dass Elune aufgrund dieses Opfers Sathrah segnen wird, damit sie wiedergeboren werden und endlich Frieden finden kann.", completion = "Der Wald trauert um Lady Sathrah, doch es musste getan werden. Ich hoffe, sie kann nun in Frieden ruhen.\n\nDanke, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[2519] = { id = 2519, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Tempel des Mondes", description = "Ein einstmals großes Wesen des Waldes benötigt Hilfe, {race}.\n\nEine schwierige Aufgabe muss getan werden.\n\nBitte sucht Priesterin A'moora auf: Sie wird Euch alles erklären. Ihr findet sie südöstlich von hier im Tempel des Mondes.", sourceObjective = "Schwester Aquinne möchte, dass Ihr im Tempel des Mondes mit Priesterin A'moora sprecht.", sourceObjectiveStatus = "unverified-source-field" }
quests[2520] = { id = 2520, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sathrahs Opferung", description = "Jetzt müsst Ihr die Aufgabe vollenden, die Euch auferlegt worden ist. Nehmt die Spinndrüsen und bringt Elune Lady Sathrahs Opfer dar. Verschafft der großen Spinne die ewige Ruhe.\n\nBegebt Euch zum zentralen Brunnen in diesem Tempel. Dort könnt Ihr das Opfer niederlegen. Die heiligen Wasser werden die Verderbnis, durch die Sathrah in den Wahnsinn getrieben wurde, läutern und säubern.\n\nKommt zu mir zurück, sobald Ihr dies erledigt habt.", sourceObjective = "Priesterin A'moora möchte, dass Ihr Lady Sathrahs silbrige Spinndrüsen am Brunnen innerhalb des Tempels ablegt und dann zu ihr zurückkehrt.", sourceObjectiveStatus = "unverified-source-field" }
quests[2521] = { id = 2521, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Dienst für Kum'isha", description = "{race}, kann Euer winziges Gehirn überhaupt verstehen, wie selten eine völlig fehlerlose Draenethystsphäre ist? Viele Draenei suchten ein Leben lang nach einem dieser Kristalle, doch war ihnen kein Erfolg beschert und sie alle endeten auf tragische Weise.\n\nUnd nun steht Ihr vor Kum'isha, wissend, was Kum'isha wünscht, und Ihr möchtet dennoch behilflich sein? Nun gut, {race}... Solltet Ihr auf Euren Reisen durch die Lande irgendwann auf eine fehlerlose Draenethystsphäre stoßen, dann bringt sie mir, und ich belohne Euch mit Reichtümern, wie Ihr sie Euch niemals erträumen könnt.", sourceObjective = "Falls Ihr auf Euren Reisen durch die Verwüsteten Lande je auf eine fehlerlose Draenethystsphäre stoßen solltet, bringt sie zu Kum'isha dem Sammler.\n\nDoch seid gewarnt. Der Edelstein ist einer der rarsten Kristalle von ganz Azeroth. Jedes Wesen in diesem Land könnte eine fehlerlose Draenethystsphäre bei sich haben.\n\nIhr erhaltet eine Belohnung für jede fehlerlose Draenethystsphäre, die Ihr beschaffen könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[2522] = { id = 2522, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kum'ishas Bemühungen", description = "Obwohl die Herbeizauberung des Portals fehlgeschlagen ist, hoffe ich doch weiterhin, dass ich mit meinem nächsten Versuch Erfolg haben werde.\n\nDie Hoffnung der Draenei ist ebenso groß wie Eure Gier nach Tand, {race}. Begebt Euch wieder hinaus in dieses verfluchte Land und beschafft mir eine weitere fehlerlose Draenethystsphäre.\n\nNatürlich liegt es ganz allein an Euch, ob Ihr diese Aufgabe annehmen wollt oder nicht... <grinst>.", sourceObjective = "Findet eine fehlerlose Draenethystsphäre und bringt sie Kum'isha dem Sammler.", sourceObjectiveStatus = "unverified-source-field" }
quests[2523] = { id = 2523, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verderbte Liedblume" }
quests[2541] = { id = 2541, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der schlafende Druide", description = "Die hier lebenden Schamanen der Knarzklauen haben einen Weg entdeckt, wie man den Geist eines schlafenden Druiden von seinem Körper trennen kann. Die Furbolgs haben meinen physischen Körper reanimiert und lassen ihn jeden angreifen, der versucht, den Grabhügel von Ban'ethil zu erforschen. Ich selbst bin im Smaragdgrünen Traum gefangen und kann diesem Treiben keinen Einhalt gebieten.\n\nIhr müsst mir helfen. Die Knarzklauenschamanen tragen einen seltsamen Glücksbringer bei sich, mit dem dieses Ritual durchgeführt wird, und ich würde einen solchen Glücksbringer gern untersuchen. Bitte, {name}, bringt mir einen.", sourceObjective = "Bringt einen Voodooglücksbringer des Schamanen zu Oben Zornklaue in den Grabhügel von Ban'ethil.", progress = "Wenn ich den Glücksbringer untersuchen kann, gelingt es mir vielleicht, die Verzauberung zu brechen. Habt Ihr einen gefunden?", completion = "Danke, {name}.\n\nWas für ein seltsamer Gegenstand das doch ist... Ich kann die üble Aura spüren, die von ihm ausgeht: eine mächtige Verzauberung.", sourceObjectiveStatus = "unverified-source-field" }
quests[2561] = { id = 2561, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Druide der Klaue", description = "Nachdem ich den Glücksbringer untersucht habe, weiß ich jetzt, was zu tun ist, {name}. Bitte nehmt ihn und führt aus, worum ich Euch bitte.\n\nIhr müsst Euch der Tür zu der nahegelegenen Kammer nähern. Dahinter findet Ihr meinen seelenlosen Körper. Und obwohl es mich sehr schmerzt, Euch das jetzt zu sagen, sehe ich keine andere Möglichkeit, wie ich mich der Kontrolle der Knarzklauen entziehen kann.\n\nDamit ich mich von ihnen befreien kann, müsst Ihr meinen physischen Körper töten. Sobald das getan ist, wendet den Voodooglücksbringer auf meinen gefallenen Körper an. Und wenn Ihr diese Aufgabe erfüllt habt, kommt zu mir zurück.", sourceObjective = "Tötet den seelenlosen Körper von Oben Zornklaue und benutzt dann den Voodooglücksbringer.", progress = "{name}, seid vorsichtig, wenn Ihr Euch meinem Körper nähert: Die Verzauberung, der er unterliegt, ist sehr mächtig.", completion = "Ich habe mich endlich der Kontrolle der Knarzklauen entzogen. Danke, {name}.\n\nNun kann mein Geist auf immer friedlich im Smaragdgrünen Traum verweilen.\n\nVielleicht treffen wir uns eines Tages wieder, junger Freund. Doch zunächst nehmt bitte diese Belohnung als Zeichen meiner Dankbarkeit an.", sourceObjectiveStatus = "unverified-source-field" }
quests[2581] = { id = 2581, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kicherfangunterkiefer", description = "Es ist eine wohl bekannte Tatsache, dass Hyänen unglaubliche Kraft in ihrem Unterkiefer haben, aber drei Zoll Thoriumstahl durchbeißen? Unmöglich, völlig unwahrscheinlich, und dennoch habe ich es mit meinen eigenen Augen gesehen.\n\nWagt Euch hinaus in die Verwüsteten Lande und bringt mir drei Kicherfangunterkiefer. Und während Ihr nach den Kicherfanghyänen sucht, haltet auch nach Ebern und Skorpoks Ausschau, denn für die erste Zubereitung der Inhaltsstoffprobe benötige ich auch zwei feuerverbrannte Eberlungen und eine Skorpokzange.", sourceObjective = "Bringt Blutmagier Drazial 3 Kicherfangunterkiefer, 2 feuerverbrannte Eberlungen und 1 Skorpokzange.", sourceObjectiveStatus = "unverified-source-field" }
quests[2582] = { id = 2582, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wut der Zeiten", description = "Ah, {name}, willkommen. Es scheint, als habe es Euch gefallen, so von Kraft erfüllt und handlungsfähig zu sein, wie es durch die Wirkung der Kicherfangdroge möglich wurde. Doch seid gewarnt: Zwar zeigt sich unmittelbar nach der Einnahme des Präparates ein gigantischer Stärkeschub, doch auf lange Sicht gesehen könnte das Mittel nachteilige Auswirkungen auf Euren Geist und Eure Intelligenz haben.\n\nUnd jetzt, wo Ihr dies wisst - braucht Ihr noch mehr? Falls ja, dann bringt mir drei weitere Kicherfangunterkiefer, zwei feuerverbrannte Eberlungen und eine Skorpokzange.", sourceObjective = "Bringt Blutmagier Drazial 3 Kicherfangunterkiefer, 2 feuerverbrannte Eberlungen und 1 Skorpokzange.", sourceObjectiveStatus = "unverified-source-field" }
quests[2583] = { id = 2583, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lebenskraft des Ebers", description = "Hier in den Verwüsteten Landen leben zwei Arten von Ebern: der Aschmähneneber und der Hölleneber.\n\nEs scheint, als mache die Ausdauer dieser Wildtiere sie so gut wie völlig immun gegen Schaden jeglicher Art, da die anderen Tiere zu große Schwierigkeiten haben, sie zu töten, und daher in Ruhe lassen.\n\nWir müssen weitere Analysen durchführen, {name}. Wenn Ihr mir drei feuerverbrannte Eberlungen, zwei Skorpokzangen und ein Basiliskengehirn bringt, dann werde ich aus den Überresten der Inhaltsstoffprobe ein himmlisches Elixier kreieren. Und Ihr seid mein erstes Versuchsobjekt!", sourceObjective = "Bringt Blutmagier Drazial 3 feuerverbrannte Eberlungen, 2 Skorpokzangen und 1 Basiliskengehirn.", sourceObjectiveStatus = "unverified-source-field" }
quests[2584] = { id = 2584, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geist des Ebers", description = "Schon als ich das Elixier zum ersten Mal einsetzte, konnte ich sehen, dass eine oder zwei Anwendungen Euer Verlangen danach nicht stillen würden, {name}. Selbst jetzt bleibt mir die Gier in Euren Augen nicht verborgen. Das Gebräu hat suchterzeugende Eigenschaften, denen, so scheint es, noch nicht einmal jemand mit äußerst starkem Willen widerstehen kann.\n\nSo sei es denn! Solltet Ihr mehr von dem Lungensaftcocktail benötigen, dann wagt Euch wieder hinaus ins Ödland und besorgt mir drei feuerverbrannte Eberlungen, zwei Skorpokzangen und ein Basiliskengehirn.", sourceObjective = "Bringt Blutmagier Drazial 3 feuerverbrannte Eberlungen, 2 Skorpokzangen und 1 Basiliskengehirn.", sourceObjectiveStatus = "unverified-source-field" }
quests[2585] = { id = 2585, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Entscheidungsschlag", description = "Habt Ihr jemals gesehen, wie sie kämpfen, {name}? Die Skorpoks, meine ich. Habt Ihr jemals die Anmut und Gewandtheit ihrer Bewegungen gesehen? Gesehen, wie entschlossen sie zuschlagen?\n\nWenn wir nur irgendwie diese Beweglichkeit einfangen und für uns nutzbar machen könnten, dann würden wir so reich werden, wie... ähem, dann wäre das ein unschätzbarer Segen für die wissenschaftliche Gemeinschaft, meine ich natürlich.\n\nHelft mir, {name}, dann lasse ich Euch auch von der fertigen Inhaltsstoffprobe kosten.\n\nUm eine reaktionsstabile Probe herzustellen, benötige ich drei Skorpokzangen, zwei Geiermuskelmägen und eine feuerverbrannte Eberlunge.", sourceObjective = "Bringt Blutmagier Drazial 3 Skorpokzangen, 2 Geiermuskelmägen und 1 feuerverbrannte Eberlunge.", sourceObjectiveStatus = "unverified-source-field" }
quests[2586] = { id = 2586, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salz der Skorpok", description = "Ihr lebt noch! Das sind wahrlich gute Neuigkeiten. Ich vermute mal, Ihr seid wieder da, weil Ihr mehr von der Skorpokinhaltsstoffprobe möchtet?\n\nTja, {name}, dann mal ab ins Ödland mit Euch, und kommt erst zurück, wenn Ihr drei Skorpokzangen, zwei Geiermuskelmägen und eine feuerverbrannte Eberlunge eingesammelt habt.", sourceObjective = "Bringt Blutmagier Drazial 3 Skorpokzangen, 2 Geiermuskelmägen und 1 feuerverbrannte Eberlunge.", sourceObjectiveStatus = "unverified-source-field" }
quests[2601] = { id = 2601, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Biss des Basilisken", description = "In der Einöde wimmelt es nur so von Rotsteinbasilisken, {name}. Diese Basilisken haben sich an ihre Umgebung angepasst und sind in ihr gediehen, mehr als jede andere wilde Tierart in diesem Gebiet.\n\nIch habe sie schon oft von weitem beobachtet, wenn sie jagen und ihren täglichen Aktivitäten nachgehen: Diese Wildtiere zeigen Denkprozesse, die komplexer sind als die mancher Humanoiden!\n\nIch muss ihre Gehirne studieren!\n\nBringt mir zehn ihrer Gehirne, {name}. Doch für das Präparat benötige ich auch zwei Geiermuskelmägen. Diese bilden die Grundlage der Lösung.", sourceObjective = "Bringt Blutmagierin Lynnore 10 Basiliskengehirne und 2 Geiermuskelmägen.", sourceObjectiveStatus = "unverified-source-field" }
quests[2602] = { id = 2602, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unfehlbare Gedanken", description = "Eure fokussierte Konzentration hat so schnell nachgelassen? Dann muss unbedingt weitergeforscht werden!\n\nAch ja, und der Preis ist noch immer derselbe, {name}. Wagt Euch in die Verwüsteten Lande hinaus und kommt mit zehn Rotsteingehirnen und zwei Geiermuskelmägen wieder.", sourceObjective = "Bringt Blutmagierin Lynnore 10 Basiliskengehirne und 2 Geiermuskelmägen.", sourceObjectiveStatus = "unverified-source-field" }
quests[2603] = { id = 2603, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lebensenergie des Geiers", description = "Hier in den Verwüsteten Landen besitzt der Tod tatsächlich Flügel, {race}. Ich habe gesehen, wie die schwarzen Töter und die Knochenpflücker sich am Kadaver so manch eines gefallenen Forschers gütlich taten - und manchmal fraßen sie sogar die übelsten, von Seuchen zerfressenen Leichen auf. Da ist es schon ein Wunder, wie ihre inneren Organe die Pestilenz überwinden, die in diesen Landen wütet.\n\nHelft mir bei meinen Studien, {name}! Ich brauche Muskelmägen! Aber ich benötige auch zwei Kicherfangunterkiefer. Diese stellen die Grundlage für das Gebräu dar.\n\nFür Eure Anstrengungen erhaltet Ihr eine doppelte Belohnung.", sourceObjective = "Bringt Blutmagierin Lynnore 10 Geiermuskelmägen und 2 Kicherfangunterkiefer.", sourceObjectiveStatus = "unverified-source-field" }
quests[2604] = { id = 2604, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geistige Beherrschung", description = "Wie ich sehe, ist Euer inneres Feuer erloschen. Was meint Ihr, hat das geistige Hochgefühl etwa eine Stunde angedauert?\n\nFalls Ihr mehr von der Muskelmagenkaumasse benötigt, dann benötige ich mehr Muskelmägen. Zurück in die Einöde mit Euch, {name}. Kommt erst wieder, wenn Ihr zehn Muskelmägen und zwei Unterkiefer beschafft habt.", sourceObjective = "Bringt Blutmagierin Lynnore 10 Geiermuskelmägen und 2 Kicherfangunterkiefer.", sourceObjectiveStatus = "unverified-source-field" }
quests[2605] = { id = 2605, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der durstige Goblin", description = "Ich hab da so eine Idee. Ich habe von einigen seltsamen Kreaturen namens 'Tausammler' gehört, die im Südwesten leben. Angeblich können sie in speziellen Drüsen Wasser speichern.\n\nIch glaube, wenn ich eine von diesen Drüsen bekäme, dann könnte ich ein Getränk kreieren, das meinen schrecklichen Durst löschen würde. Könntet Ihr mir vielleicht helfen, {name}?\n\nSucht bei den Kakteen, {name}: Dort findet Ihr die Tausammler.", sourceObjective = "Beschafft Euch eine volle Taudrüse und bringt sie nach Gadgetzan zu Marin Noggenfogger.", sourceObjectiveStatus = "unverified-source-field" }
quests[2606] = { id = 2606, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dem guten Geschmacke", description = "Bäh! Igitt! Das Zeug schmeckt ja eklig! So viel dazu...\n\nBitte, was meint Ihr? Ja, ich weiß schon, Ihr findet, ich sollte nicht so schnell die Flinte ins Korn werfen. Na dann.\n\nÄhm, da fällt mir was ein! Das ist genial! Bringt diesen Tau meiner Freundin Sprinkel - sie ist eine tolle Küchenchefin. Sagt ihr, was wir vorhaben, und dass wir das Zeug etwas aufpeppen wollen.\n\nIch meine, wenn es schon so fies schmeckt, dann sollte es wenigstens einen kleinen... Kick haben. Und davon kann ich nichts bemerken...", sourceObjective = "Marin Noggenfogger möchte, dass Ihr in Gadgetzan mit Sprinkel sprecht.", sourceObjectiveStatus = "unverified-source-field" }
quests[2607] = { id = 2607, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Berührung von Zanzil", description = "Es scheint, als hättet Ihr mehr Informationen bekommen, als selbst ich erwartet hätte. Es ist schon seltsam, wie das Schicksal manchmal spielt, {name}.\n\nEin Heilmittel? Hmm... Geht hinunter in den Keller und sprecht mit Dok Mixilpixil: Vielleicht kann er Euch helfen.", sourceObjective = "Sprecht im Keller der Kaserne mit Dok Mixilpixil.", sourceObjectiveStatus = "unverified-source-field" }
quests[2608] = { id = 2608, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Berührung von Zanzil", description = "Meine Güte, Ihr seht ja aus wie der Tod. Nein, falsch. Ich habe den Tod schon gesehen - Ihr seht schlimmer aus. Ihr seht aus wie das, was der Tod bei seiner letzten Vorsorgeuntersuchung ausgespuckt hat.\n\nHa! Habt Ihr das gehört, Noarm? Schreibt das auf!\n\n<hustet> Ähem, ja, damit ich Euch helfen kann, muss ich Euch Blut abnehmen. Und keine Sorge, es tut nur die ersten... fünfzig Male oder so weh... Wenn Ihr bereit für die Behandlung seid, {name}, solltet Ihr Euch bitte /hinlegen.", sourceObjective = "Ihr solltet Euch /hinlegen, damit Dok Mixilpixil Euch untersuchen kann. Denn wie soll er ein Heilmittel finden, wenn er die Ursache nicht finden kann?", sourceObjectiveStatus = "unverified-source-field" }
quests[2609] = { id = 2609, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Berührung von Zanzil", description = "Wir sind einstimmig zu folgendem Schluss gekommen, {name}... Ihr habt eine 'Itis'.\n\nZum Glück kann ich die 'Itis' heilen.\n\nUnd das brauche ich dafür: ein Bündel einfache Wildblumen, eine verbleite Phiole, eine Bronzeröhre und schließlich und endlich noch eine Rolle blassgelben Seidenfaden. Die alte Emma hat in 'Das feinste Band' eine Rolle davon für mich hinterlassen. Ihr findet den Laden an einem der Kanäle.\n\nBeeilt Euch jetzt, {name}, und vermeidet es möglichst, jemanden anzufassen, bis Ihr geheilt seid. Dr. Montgomery meint übrigens, Ihr könntet eine Dusche vertragen - das hat er gesagt, nicht ich.", sourceObjective = "Bringt Dok Mixilpixil 1 Bündel einfache Wildblumen, 1 verbleite Phiole, 1 Bronzeröhre und 1 Rolle blassgelben Seidenfaden. So eine 'Itis' heilt sich nicht von selbst, <junger Herr/junge Dame>.", sourceObjectiveStatus = "unverified-source-field" }
quests[2621] = { id = 2621, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Disgraced One" }
quests[2622] = { id = 2622, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die fehlenden Befehle", description = "Die Befehle? Jetzt sagt mir doch mal, was Ihr mit diesen Befehlen wollt!\n\nWas wollt Ihr damit andeuten, {name}? Natürlich habe ich die Befehle weitergegeben! Die Soldaten, denen ich die Befehle mitgab, wurden von Murlocs überfallen und auf brutalste Weise misshandelt. Nur ein Einziger von ihnen hat überlebt... wenn man das überleben nennen kann. Er kann kaum sprechen, kann nicht mehr laufen und muss durch einen Schlauch ernährt werden. Wenn Ihr wissen wollt, was mit diesen Befehlen passiert ist, dann sprecht mit Bengor. Er treibt sich hier mit Sicherheit irgendwo herum... und, {name}, seid vorsichtig, in was Ihr Eure Nase steckt. Nicht, dass sie Euch abgebissen wird!", sourceObjective = "Sprecht mit Bengor in Steinard in den Sümpfen des Elends.", sourceObjectiveStatus = "unverified-source-field" }
quests[2623] = { id = 2623, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Sumpfredner", description = "Befehle... vom Zentral-Kommandanten ausgegeben. Haben Befehle... genommen. Auf dem Weg in die Verwüsteten Lande... überfallen...\n\nMurlocs... Viele Murlocs... Einer... hieß Sumpfredner. Nahm mir Befehle ab, als Speer in meinen Schädel fuhr. Osten... Höhle...\n\n<Bengor verliert das Bewusstsein.>", sourceObjective = "Beschafft die Befehle des Kriegshäuptlings wieder und gebt sie dem gefallenen Helden der Horde zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[2641] = { id = 2641, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sprinkels Geheimzutat", description = "Als ich noch ein kleines Mädchen war, hat meine Schwester immer gekocht. Es war grauenhaft! Manche ihrer 'Gerichte' konnte ich kaum runterwürgen - bis ich irgendwann meine 'Geheimzutat' entdeckt habe! Egal, zu was man sie hinzufügt... im Nu schmeckt alles toll!\n\nUm was es sich dabei handelt, wollt Ihr wissen? Es ist ein Pilz namens violetter Tragan. Wenn Ihr wollt, dass ich dieses fürchterlich schmeckende Gebräu in etwas Genießbares verwandle, dann begebt Euch ins Hinterland und sucht dort nach einem kleinen See.\n\nUnd vergesst nicht: Violette Tragane findet man nur unter Wasser.", sourceObjective = "Sprinkel in Gadgetzan möchte, dass Ihr einen violetten Tragan sucht und ihr bringt.", sourceObjectiveStatus = "unverified-source-field" }
quests[2661] = { id = 2661, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lieferung für Marin", description = "Hier habt Ihr das violette Pulver, {name}. Bringt es zu Marin und sagt ihm, er schuldet mir was!", sourceObjective = "Sprinkel möchte, dass Ihr das violette Pulver nach Gadgetzan zu Marin Noggenfogger bringt.", sourceObjectiveStatus = "unverified-source-field" }
quests[2662] = { id = 2662, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noggenfoggers Elixier", description = "So, jetzt mische ich das Pulver unter den Tau.\n\nSprecht mich in einer Minute noch mal an... wenn ich Noggenfoggers fabelhaftes Elixier perfektioniert habe!", sourceObjective = "Marin Noggenfogger möchte, dass Ihr ihn nochmals ansprecht, wenn er sein Elixier fertiggestellt hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[2681] = { id = 2681, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Steine, die uns binden", description = "Allein wird es Euch nicht gelingen, die Streitmacht von Razelikh und seinen Untergebenen zu überwinden.\n\nSammelt eine Gruppe von geeigneten Abenteurern um Euch und befreit meine Männer aus der ewigen Qual! Achtzehn Steine müsst Ihr zerschmettern.\n\nKämpft hart und sterbt ehrenvoll, {name}.", sourceObjective = "Befreit 9 Diener von Razelikh, 3 Diener von Sevine, 3 Diener von Allistarj und 3 Diener von Grol. Kehrt zum gefallenen Helden zurück, sobald Ihr die Aufgabe erfüllt habt. Ihr müsst nahe bei den Steinen bleiben, sonst habt Ihr keinen Erfolg.", sourceObjectiveStatus = "unverified-source-field" }
quests[2701] = { id = 2701, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Helden der Vergangenheit", description = "Bitte, nehmt Euch ein Relikt der Vergangenheit. Wir haben für den Gegenstand keine Verwendung mehr.\n\nMöge es Euch in Eurem Kampf gegen die Legion gute Dienste leisten.", sourceObjective = "Öffnet die Truhe und nehmt Euch Eure Belohnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[2702] = { id = 2702, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Helden der Vergangenheit", description = "Mit Eurem Edelmut und Eurer Heldenhaftigkeit erweist Ihr mir Ehre, {name}.\n\nUnd auch ihnen habt Ihr Ehre erwiesen...", sourceObjective = "Sprecht mit Korporal Thund Spalthuf.", sourceObjectiveStatus = "unverified-source-field" }
quests[2721] = { id = 2721, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kirith", description = "Ein Kapitel Eurer Abenteuer mag jetzt beendet sein, doch ein weiteres Kapitel beginnt gerade, {name}.\n\nEiner meiner Männer ist noch immer verschollen, irgendwo in den Verwüsteten Landen verschwunden. Ich spreche natürlich von Leutnant Kirith.\n\nWie ich vorhin schon sagte, wurden wir beide von Allistarj gefangen genommen und gefoltert, aber ich fürchte, dass der arme Kirith nicht durchhielt und schwach wurde. Aus meinem Käfig heraus konnte ich die Experimente hören: Die gequälten Schreie hallten in der ganzen Höhle wider. Das war das Letzte, was ich von Kirith gesehen oder gehört habe.", sourceObjective = "Findet heraus, was aus Leutnant Kirith geworden ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[2741] = { id = 2741, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Super-Ei-o-Mat" }
quests[2742] = { id = 2742, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rin'ji steckt in der Falle!", description = "He, {race}!\n\nBitte, helft Rin'ji flüchten. Ich weiß, Ihr seid {race}, mögt Rin'jis Volk nicht, aber Rin'ji bittet und bettelt! Muss hier raus!\n\nHab auch was Schönes für {race}, wenn {race} nett ist und Rin'ji hier raushilft...\n\nRin'ji hat was Geheimes bei den Aussichtsklippen versteckt.", sourceObjective = "Eskortiert Rin'ji aus der Jagdhütte von Quel'Danil heraus und findet dann das, was er bei den Aussichtsklippen im Osten versteckt hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[2743] = { id = 2743, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Mantel der Dunkelheit", description = "Lasst uns nicht um den heißen Brei herumreden, {race}; ich habe nicht unbegrenzt Zeit.\n\nIhr müsst das Dreigestirn der Macht vernichten, das den Dämonenlord Razelikh beschützt. Doch das wird nicht ganz so einfach werden wie das Befreien einer verdammten Seele.\n\n<Kirith grinst.>\n\nIhr müsst wissen, dass jeder von Razelikhs Untergebenen ein Drittel eines von Razelikh geschaffenen Amuletts um den Hals trägt. Und genau dieses Amulett braucht Ihr, um den Erzdämon zu beschwören.\n\nGeht zu Trebor und sagt ihm, was benötigt wird, um Razelikh zu beschwören. Er kann Euch weitere Anweisungen geben.", sourceObjective = "Kehrt mit Euren neuen Erkenntnissen zum gefallenen Helden der Horde zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[2744] = { id = 2744, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Dämonenjäger", description = "Das Dreigestirn wird von Razelikh beschützt.\n\nAls Lohn für ihre Dienste hat Razelikh jeden von ihnen mit schier unbegrenzter Macht in den Verwüsteten Landen ausgestattet. Die Teile des Amuletts sind auf die Lebenskraft ihrer jeweiligen Besitzer eingestellt und verleihen diesen Unsterblichkeit. Solange die sich in den Verwüsteten Landen aufhalten, können sie nicht getötet werden, und auch ihre Lebensspanne ist bis zum Ende aller Tage ausgedehnt.\n\nDoch einen gibt es, der Euch vielleicht weiterhelfen kann, {name}. Reist nach Azshara und sucht dort nach dem Dämonenjäger Loramus Thalipedes. Ihr findet ihn vermutlich auf den Inseln.", sourceObjective = "Sprecht mit Loramus Thalipedes in Azshara.", sourceObjectiveStatus = "unverified-source-field" }
quests[2745] = { id = 2745, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eindringen ins Schloss", description = "Hmm, eine interessante Geschichte und eine, die man nicht auf die leichte Schulter nehmen sollte. Ja, ich kann Euch helfen, aber wenn Ihr das wirklich bis zum Ende durchziehen wollt, dann müsst Ihr andere Saiten aufziehen, die... nicht ganz legal sind.\n\nLescovar und Marzon müssen erledigt werden, und zwar schnell. Glaubt Ihr, Ihr seid zu so was fähig?\n\nDie Entscheidung liegt bei Euch. Falls ja, dann geht so schnell wie möglich ins Schloss und redet dort mit einem Freund von mir, einem Gnom namens Tyrion. Er beobachtet Lescovar jetzt schon seit ein paar Wochen. Er sollte Euch dabei helfen können, die Sache zu Ende zu bringen.", sourceObjective = "Sprecht in Schloss Sturmwind mit Tyrion.", sourceObjectiveStatus = "unverified-source-field" }
quests[2746] = { id = 2746, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht unwichtige Gegenstände", description = "Trias will also alles ein bisschen beschleunigen, wie? Na gut, können wir zwar machen, aber ich bin noch nicht bereit. Und damit eines mal klar ist: Ich hab den anstrengenderen Job, aber Ihr seid <derjenige, der/diejenige> die; sich die Hände schmutzig macht, verstanden? Gut.\n\nAlso, Ihr müsst mir ein paar Sachen besorgen, bevor ich meinen Plan in die Tat umsetzen kann. Ich hab schon die perfekte Verkleidung, um den Spionagebot an den Wachen vorbeizubekommen.\n\nBringt mir etwas Seide und ein paar Äpfel. Wo Ihr die Seide herkriegt, ist Eure Sache, aber auf Claras kleinem Hof draußen vor der Stadt gibt es Äpfel in genau der richtigen Größe.", sourceObjective = "Bringt 3 Stück Seidenstoff und 2 frische Äpfel von Clara nach Sturmwind zu Tyrion.", sourceObjectiveStatus = "unverified-source-field" }
quests[2747] = { id = 2747, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein außergewöhnliches Ei" }
quests[2748] = { id = 2748, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein gutes Ei" }
quests[2749] = { id = 2749, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein gewöhnliches Ei" }
quests[2750] = { id = 2750, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein schlechtes Ei" }
quests[2751] = { id = 2751, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Barbarische Waffenschmiedekunst", description = "Zwanzig Generationen von Omoshs haben diesen Hammer bereits in Händen gehalten, {name}. Hunderttausend Tonnen Metall haben wir geformt. Doch leider, leider endet alles mit Orokk, dem Fehlschlag der Omosh: ohne Verwandte und nicht in der Lage, sich fortzupflanzen.\n\nIch kann nicht zulassen, dass die geheimen Rezepturen der Omosh mit mir sterben! Jemand muss das Werk fortführen, ganz gleich, ob derjenige ein Omosh ist oder nicht!\n\nBeweist Orokk, dass Ihr fähig seid, {name}. Bringt Orokk die folgenden Dinge: zwei gemusterte bronzene Armschienen, zwei bronzene Großschwerter und zwei scharfe Klauen. Bringt sie Orokk, dann machen wir weiter.", sourceObjective = "Bringt 2 gemusterte bronzene Armschienen, 2 bronzene Großschwerter und 2 scharfe Klauen zu Orokk Omosh in Orgrimmar.", progress = "Bronze, {name}! Bringt mehr Bronze!", completion = "Die Blutlinie mag vielleicht vergehen, doch die Legende der Omoshs wird weiterleben!\n\nIhr habt bewiesen, dass Ihr ein wahrer Schmied seid, {name}. Für einen Schmied ist es Belohnung genug, wenn er seine Waffen und seine Rüstungen mit dem Blut der Feinde bedeckt sieht.\n\nMögen die Brustplatten, die Ihr für zukünftige Generationen anfertigt, im Blut Eurer Feinde gebadet werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[2752] = { id = 2752, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Über Eisenschulterstücke", description = "Orokk sieht den Eifer in Euren Augen, {name}. Wie ein Schwamm saugt Ihr das Wissen der Omoshs auf.\n\nDrei Lektionen werde ich Euch lehren.\n\nKehrt zum Amboss zurück, schwitzt in der Hitze der Schmiede und stellt für Orokk vier bronzene Streitäxte und vier bronzene Kriegshämmer her. Erst dann könnt Ihr etwas über Eisenschulterstücke lernen.", sourceObjective = "Bringt 4 bronzene Streitäxte und 4 bronzene Kriegshämmer zu Orokk Omosh in Orgrimmar.", progress = "Zeigt mir, dass Ihr es ernst meint, {race}.", completion = "Ihr macht Orokk alle Ehre, {name}. Lest und lernt etwas über Eisenschultern!", sourceObjectiveStatus = "unverified-source-field" }
quests[2753] = { id = 2753, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In den Boden getrampelt", description = "Nur zwei Lektionen noch hat Orokk für Euch, {name}. Eure Muskeln schmerzen, ich weiß, doch macht weiter - für die Omoshs!\n\nBringt Orokk vier grüne Eisenhelme, vier grüne Eisenarmschienen und zwei grüne Eisengamaschen - zur Belohnung werdet Ihr lernen und Eure Feinde werden leiden!", sourceObjective = "Bringt 4 grüne Eisenhelme, 4 grüne Eisenarmschienen und 2 grüne Eisengamaschen zu Orokk Omosh in Orgrimmar.", progress = "Ihre Schädel werden unter dem Druck Eurer Stiefel platzen!", completion = "Ihr erinnert Orokk an seinen Großvater, Häuptling Gorokk von Omosh! Lest und lernt etwas über Eisenstiefel!", sourceObjectiveStatus = "unverified-source-field" }
quests[2754] = { id = 2754, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hörner der Raserei", description = "Jetzt lehrt Orokk Euch die letzte Lektion, {name}. Zurück zum heiligen Amboss und der heiligen Schmiede mit Euch! Bringt Orokk zwei robuste Eisenschlägel, zwei bronzene Stiefel mit Versilberung und zwei bronzene Stulpen mit Versilberung.\n\nSeht die Furcht in den Augen der Feinde, wenn Ihr Euch nähert!", sourceObjective = "Bringt 2 robuste Eisenschlägel, 2 bronzene Stiefel mit Versilberung und 2 bronzene Stulpen mit Versilberung zu Orokk Omosh in Orgrimmar.", progress = "Zeigt dem Eisen, wer der Herr im Hause ist, {name}!", completion = "Erstaunlich! Ihr habt die Geheimnisse der Omoshs erlernt, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[2755] = { id = 2755, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freude der Omoshs", description = "Orokk weint nicht, {name}. Orokk hat Ruß ins Auge bekommen.\n\n<Orokk wischt eine Träne weg.>\n\nNoch ein letztes Familiengeheimnis der Omosh wird Orokk Euch beibringen. Dank {name} wird Orokk glücklich sterben.\n\nLernt den Freudentanz der Omoshs... und dann lernt Ihr Eisenfaust!", sourceObjective = "Seht zu und lernt den Freudentanz der Omoshs.", completion = "<Orokk japst.>\n\nLange her, dass Orokk den Freudentanz der Omoshs getanzt hat. Lernt jetzt, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[2756] = { id = 2756, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die alten Traditionen", description = "Früher, zur Zeit der Legenden, zerquetschte Aturk die Schädel seiner Feinde und zermahlte die Knochen zu einem feinen Pulver, das er zu Fasern verarbeitete. Diese Tage sind lange vergangen, {race}. Der Kriegshäuptling verlangt Frieden unter den Klans. Alte Feinde werden nur noch misstrauisch beäugt!\n\nEs ist unglaublich, ich weiß, doch es ist nun einmal Thralls Wille.\n\nAber genug gejammert! Ihr seid zum Lernen hier, und Ihr werdet etwas lernen! Bringt mir vier Stahlbrustplatten und vier Stahlhelme, dann bekommt Ihr den Geschmack des Krieges zu kosten!", sourceObjective = "Bringt 4 Stahlbrustplatten und 4 Stahlplattenhelme zu Aturk dem Amboss in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[2757] = { id = 2757, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf nach Beutebucht!", description = "Hört mal, wenn Ihr hier herumhängt, lernt Ihr nix.\n\nIch kenn da so 'n Typen, der 'n Typen kennt. Der treibt sich bei der Schmiede in Beutebucht rum. Wenn Ihr ihm das Insigne hier zeigt, dann erzählt er Euch alles über Mithril.\n\nAlso, was sagt Ihr? Überlasst diesen Babykram den Kleinkindern, {name} - für Euch ist es Zeit weiterzuziehen.\n\nFalls Ihr Interesse haben solltet, der Typ heißt McGavan. Zeigt ihm das hier, dann wird er sehen, dass es Euch ernst ist.", sourceObjective = "Sprecht mit McGavan in Beutebucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[2758] = { id = 2758, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Herkunft der Schmiedekunst", description = "Als ich etwa so alt war wie Ihr, nahm mich ein Zwerg namens Galvan unter seine Fittiche und bildete mich in der Kunst des Rüstungsschmiedens aus. Bevor er sich nach Beutebucht aufmachte, nahm er mir das Versprechen ab, dass ich all denjenigen ein Lehrer sein würde, die den Wunsch hätten und entschlossen genug wären, selbst eine Schmiedelaufbahn einschlagen zu wollen. Und hier bin ich nun - all die Jahre später.\n\nAlso, es ist jetzt Zeit für Euch, ein bisschen was zu lernen. Stellt mir sechs goldene Schuppenarmschienen her, dann zeige ich Euch, was echte Schmiedekunst ist, {name}.", sourceObjective = "Bringt 6 goldene Schuppenarmschienen zu Hank dem Hammer in Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[2759] = { id = 2759, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der Suche nach Galvan", description = "Obwohl Galvan Beutebucht schon vor vielen Jahren verlassen hat, leben noch immer Mitglieder des Ordens in der Stadt und hoffen, dass sie eines Tages jemanden finden werden, der der Lehre von Galvan würdig ist.\n\nNehmt dieses Insigne und zeigt es McGavan in Beutebucht.\n\nSolltet Ihr es tatsächlich bis dorthin schaffen, dann weiß er, dass Ihr würdig seid. Ich glaube an Euch, {name}!", sourceObjective = "Sprecht in Beutebucht mit McGavan.", sourceObjectiveStatus = "unverified-source-field" }
quests[2760] = { id = 2760, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Mithrilorden", description = "Die meisten unserer Rekruten schaffen es nicht bis Beutebucht, {name}. Der Glanz des Insigne reicht normalerweise aus, um selbst im zuverlässigsten Schmied die Beutegier ausbrechen zu lassen. Narren, alle zusammen, denn das Insigne ist nichts als Talmi im Vergleich zum Wert der Gegenstände, die Ihr zu sehen bekommen werdet!\n\nFindet Galvan den Alten und zeigt ihm diese Anstecknadel. Er lebt weit im Norden, zwischen Zul'Gurub und dem Ogerhügel der Mosh'Ogg.", sourceObjective = "Sprecht mit Galvan dem Alten im Schlingendorntal.", sourceObjectiveStatus = "unverified-source-field" }
quests[2761] = { id = 2761, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hier verhütten, da verhütten", description = "Viele Schmiede glauben, der Bergbau und die Schmiedekunst seien zwei völlig getrennte, voneinander unabhängige Dinge, aber wie kann es Schmiedekunst geben ohne Bergbau? Genau, das ist völlig unmöglich! Und daher muss der vollendete Schmied auch ein tüchtiger Minenarbeiter sein.\n\nZeigt Galvan, dass Ihr fähig seid, {name}. Bringt mir vierzig Barren Eisen und vierzig Barren Mithril. Dafür sagt Galvan Euch dann alles über verschnörkelte Mithrilhosen!", sourceObjective = "Bringt Galvan dem Alten im Schlingendorntal 40 Mithrilbarren und 40 Eisenbarren.", sourceObjectiveStatus = "unverified-source-field" }
quests[2762] = { id = 2762, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der große silberne Betrüger", description = "Es heißt, dass Echtsilber noch stärker und haltbarer sei als Mithril. Galvan widerspricht dieser Einschätzung der Mineralien zwar nicht, aber Echtsilber trägt seinen Namen zu Unrecht. Echtsilber ist nicht echt! Mithril ist ein wesentlich edleres Mineral! HA! Aber wie dem auch sei...für diese Lektion müsst Ihr den silbernen Betrüger finden, {name}.\n\nBringt mir vierzig Barren Mithril und fünf Barren Echtsilber. Im Gegenzug werdet Ihr in das Geheimnis der verschnörkelten Mithrilhandschuhe eingeführt, und, was noch wichtiger ist, Ihr werdet lernen, dass Echtsilber lügt!", sourceObjective = "Bringt Galvan dem Alten im Schlingendorntal 40 Mithrilbarren und 5 Echtsilberbarren.", sourceObjectiveStatus = "unverified-source-field" }
quests[2763] = { id = 2763, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kunst der Magieerfüllung", description = "Der Abbau von wertvollen Edelsteinen ist für unsere Zunft von äußerster Wichtigkeit, {name}. Und nur wenige Edelsteine sind wertvoller als der Citrin. Die magischen Eigenschaften, mit denen wir unsere Waren ausstatten, werden deutlich verstärkt, wenn Citrine im Spiel sind.\n\nIn dieser Lektion verstärken wir vierzig Barren Mithril mit vier Citrinen. So bekommt Ihr ein besseres Verständnis für die magische Edelsteinkunde und lernt außerdem, wie man verschnörkelte Mithrilschultern herstellt.", sourceObjective = "Bringt Galvan dem Alten im Schlingendorntal 40 Mithrilbarren und 4 Citrine.", sourceObjectiveStatus = "unverified-source-field" }
quests[2764] = { id = 2764, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Galvans bester Schüler", description = "Wenn Ihr bereit seid, Eure Ausbildung bei Galvan abzuschließen, dann solltet Ihr nach Gadgetzan reisen.\n\nDort findet Ihr meinen besten Schüler, Trenton Lichthammer. Er kann Euch viel über verschnörkeltes Mithril beibringen. Ansonsten bleibt hier und lernt weiter!\n\nAch ja, Gadgetzan liegt natürlich in Tanaris!", sourceObjective = "Sprecht in Gadgetzan mit Trenton Lichthammer.", sourceObjectiveStatus = "unverified-source-field" }
quests[2765] = { id = 2765, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schmiedkunstexperte!", description = "Schon als Ihr das erste Mal zu mir kamt, wusste ich, dass Ihr Euch als einer meiner besten Schüler herausstellen würdet! Ohne zu zögern trenntet Ihr Euch von einem nicht recht mächtigen Gegenstand und gabt ihn McGavan. Ihr tatet dies, nur damit Ihr mich treffen konntet. Solch blindes Vertrauen und Hingabe an unser Handwerk soll nicht unbelohnt bleiben.\n\nIhr seid zu einem wahren Experten der Schmiedekunst geworden, {name}. Nun erntet den Lohn dafür!", sourceObjective = "Fordert Eure Belohnung von Galvan dem Alten ein!", sourceObjectiveStatus = "unverified-source-field" }
quests[2766] = { id = 2766, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Findet OOX-22/FE!", description = "Ihr habt ein merkwürdiges Gerät aus Metall entdeckt, das die Form eines Eis hat. Als Ihr einen der Knöpfe berührt, erwacht das Ei zum Leben und verwandelt sich in eine Art Gnom-Roboter-Apparat! Aus dem Inneren des Roboteis erklingt eine rasselnde Stimme.\n\n\"Mein Name ist Glotz Widrikus und mein Leitroboter ist abgestürzt! Ich werde Euch belohnen, wenn Ihr ihn aufspürt. Bringt dem Roboter bitte diesen Signalgeber!\"\n\n\"Ich habe jetzt die Koordinaten des Roboters für Euch berechnet. Er ist in der Nähe des Wildschrammtals abgestürzt!\"", sourceObjective = "Bringt das Notrufsignal zu Glotz' Leitroboter in einer Höhle in der Nähe des Wildschrammtals.", sourceObjectiveStatus = "unverified-source-field" }
quests[2767] = { id = 2767, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettet OOX-22/FE", description = "Aus dem Roboter ertönt erneut die blecherne Stimme des Gnoms:\n\n\"Ich muss OOX-22/FE an einen offenen, sicheren Ort schaffen, wo er die langwierige Startprozedur beginnen kann. Er hat eine eingebaute Tarnvorrichtung, aber ich brauche etwas Zeit, um sie von hier aus wieder zum Funktionieren zu bringen. Eskortiert den Roboter von seinem momentanen Standort zu, ach, sagen wir mal, der Hauptstraße. Das sollte der perfekte Ort für mein Vorhaben sein, und bis Ihr dort seid, sollte ich auch alles vorbereitet haben und online gehen können.\"\n\n\"Eskortiert ihn dorthin und kommt dann zu mir nach Beutebucht! Glotz Widrikus - Ende!\"", sourceObjective = "Bringt OOX-22/FE in Sicherheit und meldet Euch dann bei Glotz Widrikus in Beutebucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[2768] = { id = 2768, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wünschel-mato-Rute", description = "Unteroffizier Bly hat mich bestohlen! Er sagte, er wolle sie sich nur ausleihen, aber er hat meine geliebte Wünschel-mato-Rute gestohlen! Wo soll ich denn bitte ohne diese Rute wissen, wo ich neue Wasserlöcher graben muss?\n\nFindet Bly und bringt mir meine Rute! Ich habe gehört, er hätte seine Bande von zwielichtigen Abenteurern auf eine Schatzsuche nach Zul'Farrak im Westen geführt. Ich möchte wetten, dort findet Ihr ihn.\n\nHoffen wir, dass die Trolle ihn schon erledigt haben, denn falls Ihr Euch wegen der Rute mit ihm anlegen müsst, dann steht Euch ein schwerer Kampf bevor.", sourceObjective = "Bringt die Wünschel-mato-Rute nach Gadgetzan zu Chefingenieur Bilgenritzel.", sourceObjectiveStatus = "unverified-source-field" }
quests[2769] = { id = 2769, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Brüder Kupferbolz", description = "Seid Ihr den Gebrüdern Kupferbolz schon mal begegnet? Sie sind drüben in der Schimmernden Ebene, in Kalimdor, um genau zu sein, und treten dort in Raketenwagenrennen gegen die Goblins an. Normalerweise gewinnen sie, aber das ist keine große Überraschung - der Wagen der Goblins fliegt so oft in die Luft, dass er es kaum jemals über die Ziellinie schafft!\n\nAber trotzdem suchen die Kupferbolz-Brüder ständig nach neuen Möglichkeiten, ihren Wagen noch schneller zu machen, und Wizzel hat mir gesagt, dass er für sein nächstes Experiment noch eine sehr seltene Komponente benötigt.\n\nWahrscheinlich kommt er an dieses Ersatzteil nicht allein ran. Sprecht mit ihm, dann erfahrt Ihr mehr darüber.", sourceObjective = "Sprecht mit Wizzel Kupferbolz in der Schimmernden Ebene.", sourceObjectiveStatus = "unverified-source-field" }
quests[2770] = { id = 2770, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gahz'rilla", description = "Tief im Inneren von Zul'Farrak, der Stadt der Sandtrolle in Tanaris, liegt ein hochheiliger Teich. An diesem Teich beschwören die Trolle eine gewaltige Bestie, Gahz'rilla! Der ist so wild, dass sogar seine Schuppen vor Energie knistern. Und genau diese Energie will ich in meinem Wagen einsetzen.\n\nBringt mir die energiegeladene Schuppe von Gahz'rilla!\n\nWie man Gahz'rilla allerdings beschwört, das verraten die Trolle niemandem. Wenn Ihr ihm begegnen wollt, müsst Ihr daher erst den Trollen das Geheimnis entreißen.", sourceObjective = "Bringt Wizzel Kupferbolz in der Schimmernden Ebene Gahz'rillas energiegeladene Schuppe.", sourceObjectiveStatus = "unverified-source-field" }
quests[2771] = { id = 2771, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein schlauer Kopf auf den Schultern", description = "Es scheint, als habe der Meister dies von Anfang an geplant. Ich habe nicht gelernt, solche Gegenstände herzustellen, wie Ihr es könnt, und Ihr habt nicht gelernt, solche Gegenstände herzustellen, wie ich es kann.\n\nDer Meister ist klug, {name}. Wir werden uns gegenseitig etwas beibringen!\n\nZeigt mir, wie man eine Mithrilhelmkappe und verschnörkelte Mithrilschultern herstellt, dann zeige ich Euch, wie man einen verschnörkelten Mithrilhelm macht.", sourceObjective = "Bringt Trenton Lichthammer 2 Mithrilhelmkappen und 1 verschnörkelte Mithrilschulter.", sourceObjectiveStatus = "unverified-source-field" }
quests[2772] = { id = 2772, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Welt zu Euren Füßen", description = "Bei der Talmeisterschaft der Schmiedekunst letztes Jahr mussten alle, die zusahen, erleben, wie mir so ein feiger Hund von der Gießerei der Venture Company die Beine unter dem Körper wegzog. Aber den Grund, warum ich weitermachen und die Meisterschaft am Ende gewinnen konnte, den wusste niemand. Genau, verschnörkelte Mithrilstiefel!\n\nAber für die Meisterschaft dieses Jahr muss ich lernen, wie man verschnörkelte Mithrilhosen fertigt, denn ich muss gegen einen Schredder der Venture Co. antreten! Bringt mir bei, wie man die Hosen anfertigt, und lernt, was es mit den Stiefeln auf sich hat!", sourceObjective = "Bringt Trenton Lichthammer 2 schwere Mithrilstiefel und 1 verschnörkelte Mithrilhose.", sourceObjectiveStatus = "unverified-source-field" }
quests[2773] = { id = 2773, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mithril-Kid", description = "Hier in der Gegend bin ich als Mithril-Kid bekannt. Ich beliefere Abenteurer aus aller Welt mit verschnörkeltem Mithril.\n\n<Trenton flüstert.>\n\nDie wissen aber nicht, dass ich bisher noch keine verschnörkelten Mithrilhandschuhe herstellen kann. Psst! Das bleibt unser kleines Geheimnis, ja?\n\nBringt mir bei, wie man verschnörkelte Mithrilhandschuhe fertigt, {name}, dann zeige ich Euch im Gegenzug den Höhepunkt meiner Ausbildung unter Galvan: die verschnörkelte Mithrilbrustplatte.", sourceObjective = "Bringt Trenton Lichthammer 2 schwere Mithrilbrustplatten und 1 verschnörkelten Mithrilhandschuh.", sourceObjectiveStatus = "unverified-source-field" }
quests[2781] = { id = 2781, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Kalif Skorpidstich", description = "GESUCHT: Kalif Skorpidstich!\n\nDie Gadgetzan Water Company aus Gadgetzan in Tanaris ist bereit, eine hohe Belohnung für den Kopf von Kalif Skorpidstich, dem Anführer der Wüstenläufernomaden, zu zahlen. Seine Verbrechen belaufen sich auf:\n\n1. Ermordung von Angestellten der Gadgetzan Water Company!\n2. Stehlen von Rohstoffen der Gadgetzan Water Company!\n3. Besetzen von Eigentum der Gadgetzan Water Company!\n\nBringt Beweise für Kalif Skorpidstichs Untergang zu Chefingenieur Bilgenritzel und Ihr werdet umgehend belohnt!", sourceObjective = "Bringt Chefingenieur Bilgenritzel in Gadgetzan den Kopf von Kalif Skorpidstich.", sourceObjectiveStatus = "unverified-source-field" }
quests[2782] = { id = 2782, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rin'jis Geheimnis", description = "Die Tafel ist mit Schriftzeichen der Bleichborkentrolle bedeckt. Rin'jis Geheimnis ist wirklich ein Mysterium... \n\nGut möglich, dass Ihr hier etwas ziemlich Wertvolles in Händen haltet. Andererseits könnte ebenso gut das Gegenteil der Fall sein. Ein Troll der Bleichborken in Not würde wahrscheinlich alles tun, um einen Ausweg aus seinen Problemen zu finden...", sourceObjective = "Oran Schlangenfuß, eine bekannte Gelehrte auf dem Gebiet der Bleichborkentrolle, könnte die Tafel vielleicht übersetzen. Normalerweise hält sie sich im Magierviertel von Unterstadt auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[2783] = { id = 2783, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kleinliches Gezänk", description = "Wir bekämpfen den falschen Feind, {name}.\n\nDie wahre Macht in diesem Land wird zahlen- und kräftemäßig immer stärker, während wir uns mit den Orcs über verbrannte Erde zanken.\n\nSollen wir wirklich in diesem Land einen Krieg gegen die Horde führen, nur um eines Tages von den Armeen der Brennenden Legion hinweggefegt zu werden? Es ist sinnlos.\n\nBegrabt Eure Streitigkeiten, {name}, und sprecht mit dem gefallenen Helden der Horde. Er kennt die Wahrheit über die Verwüsteten Lande.", sourceObjective = "Sprecht mit dem gefallenen Helden der Horde im Grenzgebiet zwischen den Verwüsteten Landen und dem Sumpf.", sourceObjectiveStatus = "unverified-source-field" }
quests[2784] = { id = 2784, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fall From Grace" }
quests[2801] = { id = 2801, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Geschichte voller Leid", description = "Bevor wir fortfahren können, müsst Ihr meine Geschichte hören.", sourceObjective = "Lauscht der Geschichte des gefallenen Helden der Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[2821] = { id = 2821, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Zeichen der Qualität", description = "Meine Einstellung zur Lederverarbeitung verlangt, dass die Arbeit von bestmöglicher Qualität zu sein hat - ohne Kompromisse. Jeder, der behauptet, Qualität sei unwichtig, wird auch versuchen, Euch ein Küstengrundstück in Dun Morogh zu verkaufen!\n\nAuf meiner jüngsten Suche nach hochwertigem Material fand ich dicke Yetibälge. Die Yetis sind in Feralas zuhause und viele findet man im Wildschrammtal. Ich hätte gern welche, und wenn Ihr mir zehn davon bringt, dürft Ihr Euch ein beliebiges Stück meiner Lederwaren aussuchen. Haltet Ihr das für angemessen? Dann sind wir im Geschäft.", sourceObjective = "Bringt Pratt McGrubben in der Mondfederfeste 10 dicke Yetibälge.", sourceObjectiveStatus = "unverified-source-field" }
quests[2822] = { id = 2822, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Zeichen der Qualität", description = "Ich bin stolz auf meine Lederarbeiten und ich glaube, das sieht man ihnen an; Qualität sollte niemals zweitrangig sein. Jeder, der behauptet, Qualität sei unwichtig, wird Euch wahrscheinlich auch glauben machen wollen, dass die Erde keine Geheimnisse enthält!\n\nAuf meiner jüngsten Suche nach hochwertigem Material habe ich dicke Yetibälge entdeckt. Die Yetis sind in Feralas beheimatet und man findet sie häufig westlich des Wildschrammtals. Ihr dürft Euch ein beliebiges Stück meiner Lederwaren aussuchen für einen Zehnerstapel Yetibälge. Wenn das für Euch akzeptabel ist, dann sind wir im Geschäft!", sourceObjective = "Bringt Jangdor Flinkschreiter im Camp Mojache 10 dicke Yetibälge.", sourceObjectiveStatus = "unverified-source-field" }
quests[2841] = { id = 2841, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maschinenkriege", description = "Vor zwei Jahren noch hat man sich jedes Mal darüber lustig gemacht, wenn die Rede auf Gnomentechnologie kam. Diese Zeiten haben sich definitiv geändert. Jetzt haben sie eine neue Maschine gebaut, die besser ist als all unsere Schreddermodelle zusammen. Ich brauche die Blaupausen dafür, {name}!\n\nDummerweise sind die Pläne in einem Safe bei Robogenieur Thermadraht sicher verwahrt. Was die Sache noch erschwert: Nur Robogenieur Thermadraht kennt die Kombination zu diesem Safe.\n\nTut, was Ihr tun müsst, um diese Kombination zu erlangen, {name}. Dann öffnet den Safe und bringt mir diese Blaupausen!", sourceObjective = "Besorgt die Maschinenblaupausen und Thermadrahts Safekombination aus Gnomeregan und bringt sie zu Nogg nach Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[2842] = { id = 2842, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chefingenieur Scooty", description = "In dem Moment, als wir durch Kernobee von der neuen Gnomenmaschine hörten, haben Scooty und ich mit der Arbeit am Transpolyporter 6000 begonnen: dem schnellsten und verlässlichsten Weg nach Gnomeregan.\n\nEndlich ist er bereit, Passagiere aufzunehmen, {name}. Wenn Ihr es einmal versuchen wollt, geht nach Beutebucht und redet mit Scooty am Windreiterhorst. Um nach Beutebucht zu gelangen, nehmt das Boot von Ratschet aus.\n\nNatürlich könnt Ihr auch versuchen, Euch durch die von Zwergen verseuchten Berge von Dun Morogh nach Gnomeregan durchzuschlagen!", sourceObjective = "Sprecht mit Scooty in Beutebucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[2843] = { id = 2843, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gnomer-weeeeg!", description = "Solange Ihr den Transponder bei Euch habt, müsst Ihr lediglich auf diese Plattform hier treten und Ihr werdet nach Gnomeregan teleportiert.\n\nIhr werdet vielleicht ein paar ungewöhnliche Nebenwirkungen erleben, aber keine davon sollte dauerhaft sein... zumindest nicht mehr.\n\nIch hätte fast den wichtigsten Teil vergessen - die Rückkehr. Wenn Ihr wieder zurückkommen wollt, tretet einfach auf die Transpolyporter-Plattform in Gnomeregan!\n\nJetzt lasst uns diesen Transponder auf Euer Gewicht und Eure Größe einstellen.", sourceObjective = "Wartet, bis Scooty den Goblintransponder kalibriert hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[2844] = { id = 2844, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Riesenwächter", description = "Ich bin so unfähig, {name}. Ich sollt' auf meine kleine Freundin, Shay, aufpassen, aber irgendwie ist sie mir verlor'n gegangen. Ich kann nicht genau sagen, was passiert ist, ehrlich, aber als ich sie das letzte Mal gesehen habe, lief'n wir durch die Ruinen direkt nördlich von hier.\n\nAlles war wunderbar, aber dann hab ich mich umgedreht, un'... sie war weg.\n\nUnd jetz' hab ich keine Ahnung, was ich tun soll. Habt Ihr 'ne Idee, {name}? Ich mache mir furchtbare Sorgen.\n\nHey, wie wär's, wenn Ihr nach Shay suchen würdet? Eure Beine sind viel schneller als meine.", sourceObjective = "Findet das verlorene Nachtelfenmädchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[2845] = { id = 2845, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Streunende Shay", description = "Glaubt Ihr, Ihr könnt mir helfen, meinen Weg zurück zu meinem Freund, Felsbeißer, zu finden? Er sollte auf mich aufpassen... Aber ich neige dazu, gelegentlich davonzuschlendern. Es gibt immer so viele Dinge zu sehen und ich lasse mich dann ablenken.\n\nEs gibt allerdings etwas, was immer meine Aufmerksamkeit erregt.\n\nIn dieser Truhe findet Ihr eine Glocke, die mir sehr teuer ist. Ich liebe einfach ihren Ton. Ihr habt mein Wort: Wenn ich davonschlendere, müsst Ihr lediglich damit klingeln und ich komme angelaufen.", sourceObjective = "Nehmt Shays Glocke aus der Truhe.\n\nBegleitet Shay Laubschleicher zu Felsbeißers Lager.", sourceObjectiveStatus = "unverified-source-field" }
quests[2846] = { id = 2846, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tiara der Tiefen", description = "Vor langer Zeit besaß ich ein wunderschönes Schmuckstück, die Tiara der Tiefen. Diese war nicht nur schön, sondern enthielt auch große Macht für diejenigen, die damit umzugehen wussten.\n\nAls nun die Kunde von der Tiara die Hydromantin Velratha erreichte, musste sie sie haben. Sie schickte Handlanger in mein Haus und die stahlen sie, während ich weg war. Diese Diebe!\n\nIch will meine Tiara wiederhaben! Geht nach Zul'Farrak, der Trollstadt in Tanaris, findet Velratha und ringt ihr die Tiara ab. Bringt sie mir zurück und Ihr steht in meiner Gunst.", sourceObjective = "Bringt die Tiara der Tiefen zu Tabetha in den Düstermarschen.", sourceObjectiveStatus = "unverified-source-field" }
quests[2847] = { id = 2847, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wildlederrüstung", description = "{name}, Ihr werdet ziemlich gut als Lederer! Ich kenne da einige Muster, an denen Ihr vielleicht interessiert seid... Wildlederrüstung! Wildleder zieht Kraft aus den mächtigen und chaotischen Eigenschaften von Wildranken, die man in Gegenden mit üppiger Vegetation auf einigen der Kreaturen dort findet. Die daraus gefertigte Rüstung ist garantiert das Beste, was jemand Eures Geschicks herstellen kann.\n\nIch werde es Euch beibringen, aber Ihr werdet dafür eine Weile für mich arbeiten. Das Lehrgeld beträgt nur 10 Stücke dickes Leder. Danach reden wir über Details.", sourceObjective = "Bringt Pratt McGrubben in der Mondfederfeste 10 Stücke dickes Leder.", sourceObjectiveStatus = "unverified-source-field" }
quests[2848] = { id = 2848, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wildlederschultern", description = "Wildlederschultern verstärken den Körper des Trägers unglaublich gut und bieten dabei erstklassigen Schutz für die Oberarme und die Schultern. Wie bei allen Wildlederrüstungen wird auch hier eine mächtige, allerdings zufällige Verbesserung erzeugt, wenn die Wildranke eingearbeitet wird.\n\nFür dieses Muster werde ich 6 dicke Rüstungssets und eine Wildranke benötigen. Das sollte für Euch kein allzu schwer zu erfüllender Auftrag sein.", sourceObjective = "Bringt Pratt McGrubben in der Mondfederfeste 6 dicke Rüstungssets und eine Wildranke.", sourceObjectiveStatus = "unverified-source-field" }
quests[2849] = { id = 2849, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wildlederweste", description = "Wildlederwesten sind die Grundlage aller Wildlederrüstungssets. Das Gerüst der Weste verbindet sich mit der Wildranke, um ein Produkt zu erzeugen, das sowohl maximalen Schutz für den Torso bietet als auch der mächtigen Magie erlaubt, sich in dem Gewand auszubreiten.\n\nFür dieses Muster werde ich 2 Schildkrötenschuppenbrustplatten, 2 Paar Schildkrötenschuppenhandschuhe und eine Wildranke benötigen. Das ist ein großer Auftrag, aber sicher keiner, bei dessen Erfüllung Ihr Schwierigkeiten haben werdet.", sourceObjective = "Bringt Pratt McGrubben in der Mondfederfeste 2 Schildkrötenschuppenbrustplatten, 2 Paar Schildkrötenschuppenhandschuhe und eine Wildranke.", sourceObjectiveStatus = "unverified-source-field" }
quests[2850] = { id = 2850, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wildlederhelm", description = "Ein Wildlederhelm bietet dem Träger verbesserten Kopfschutz, ohne dabei an der Bequemlichkeit zu sparen. Wie bei allen Wildlederrüstungen erzeugt die eingearbeitete Wildranke eine mächtige, aber zufällige Verbesserung der Struktur des Helms. Lederträger werden dieses Stück auf jeden Fall haben wollen!\n\nFür dieses Muster brauche ich 2 Tuniken des Nachtschleichers, 2 Stirnbänder des Nachtschleichers und eine Wildranke. Erfüllt diesen Auftrag und das Muster gehört Euch!", sourceObjective = "Bringt Pratt McGrubben in der Mondfederfeste 2 Tuniken des Nachtschleichers, 2 Stirnbänder des Nachtschleichers und eine Wildranke.", sourceObjectiveStatus = "unverified-source-field" }
quests[2851] = { id = 2851, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wildlederstiefel", description = "Ihr habt schon eine ganze Menge gelernt, {name}; dennoch gibt es noch mehr für Euch zu lernen. Als Nächstes sind Wildlederstiefel an der Reihe, der Grundstein eines jeden Sets.\n\nDiese Stiefel werden so gefertigt, dass sie den Fuß in Bequemlichkeit hüllen, während sie ihn gleichzeitig gegen die Gefahren des Abenteuerlebens wappnen. Die weichen Sohlen sind ein Segen für diejenigen, die bei ihrer Fußbekleidung auf leise Bewegung Wert legen.\n\nFür dieses Muster müsst Ihr mir 2 Hosen des Nachtschleichers und 2 Stiefel des Nachtschleichers besorgen. Ich werde außerdem zwei Wildranken benötigen, nicht nur eine. Wenn Ihr all das beisammen habt, gebt mir Bescheid.", sourceObjective = "Bringt Pratt McGrubben in der Mondfederfeste 2 Hosen des Nachtschleichers, 2 Stiefel des Nachtschleichers und 2 Wildranken.", sourceObjectiveStatus = "unverified-source-field" }
quests[2852] = { id = 2852, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wildledergamaschen", description = "Jetzt, nachdem Ihr die Grundlagen beherrscht, seid Ihr bereit, Euch komplexeren Dingen zuzuwenden, {name}. Wildledergamaschen gehören zur robustesten und stärksten Lederausrüstung überhaupt. Bauch, Hüften, Schenkel und Solarplexus werden ungeheuer gut geschützt. Und wenn dann noch die Verstärkung hinzukommt, die die Wildranke bewirkt, werden Euch die Abenteurer, die diese Rüstung besitzen, jedes Mal danken, wenn sie Euch sehen.\n\nFür dieses Muster müsst Ihr mir 2 Schildkrötenschuppenhelme, 2 Schildkrötenschuppenarmschienen und 2 Wildranken besorgen.", sourceObjective = "Bringt Pratt McGrubben in der Mondfederfeste 2 Schildkrötenschuppenhelme, 2 Schildkrötenschuppenarmschienen und 2 Wildranken.", sourceObjectiveStatus = "unverified-source-field" }
quests[2853] = { id = 2853, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meister des Wildleders", description = "Nun, {name}, Ihr gebt dem Wort Sorgfalt eine neue Bedeutung. Es steht nur noch ein Wildlederrüstungsmuster aus, denn Ihr habt alle anderen gemeistert. Ich werde nicht von Euch verlangen, Euch unnötig für dieses Muster abzuplagen. Ihr habt es Euch bereits mehr als verdient... Aber ich kann es Euch nicht selbst geben. Mein Lehrer, derjenige, der mich in dieses Handwerk einführte, muss Euch belohnen.\n\nBringt diesen Brief zu Telonis. Er lehrt Lederverarbeitung in Darnassus. Zeigt ihm den Brief und lasst Euch von ihm als Gleichgestellten anerkennen, so wie ich das auch tue.", sourceObjective = "Gebt Telonis, dem Lederverarbeitungsmeister von Darnassus, Pratts Brief.", sourceObjectiveStatus = "unverified-source-field" }
quests[2854] = { id = 2854, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wildlederrüstung", description = "{name}, Euer Ruf als Lederer eilt Euch voraus. Ich besitze Wissen über die Lederverarbeitung, das zu erwerben weise von Euch wäre... Wildlederrüstung! Wildleder zieht Kraft aus den mächtigen und chaotischen Eigenschaften von Wildranken, die man in Gegenden mit üppiger Vegetation auf einigen der Kreaturen dort findet. Die daraus gefertigte Rüstung ist garantiert das Beste, was ein Handwerker Eures Geschicks herstellen kann.\n\nIch werde es Euch beibringen, aber Ihr werdet dafür eine Weile für mich arbeiten. Das Lehrgeld beträgt nur 10 Stücke dickes Leder. Danach reden wir über Details.", sourceObjective = "Bringt Jangdor Flinkschreiter im Camp Mojache 10 Stücke dickes Leder.", sourceObjectiveStatus = "unverified-source-field" }
quests[2855] = { id = 2855, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wildlederschultern", description = "Wildlederschultern verstärken den Körper des Trägers unglaublich gut und bieten dabei besten Schutz für Oberarme und Schultern. Wie bei allen Wildlederrüstungen wird auch hier eine zufällige, aber magieerfüllte Verbesserung erzeugt, wenn die Wildranke eingearbeitet wird.\n\nFür dieses Muster werde ich 6 dicke Rüstungssets und eine Wildranke benötigen. Das sollte für Euch kein allzu schwer zu erfüllender Auftrag sein.", sourceObjective = "Bringt Jangdor Flinkschreiter im Camp Mojache 6 dicke Rüstungssets und eine Wildranke.", sourceObjectiveStatus = "unverified-source-field" }
quests[2856] = { id = 2856, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wildlederweste", description = "Wildlederwesten sind die Grundlage jeglicher Wildlederrüstungssets. Die Struktur der Weste und das Wildrankengeflecht darin erzeugen ein Produkt, das sowohl maximalen Schutz für den Torso bietet, als auch der mächtigen Magie erlaubt, sich in dem Gewand auszubreiten.\n\nFür dieses Muster werde ich 2 Schildkrötenschuppenbrustplatten, 2 Paar Schildkrötenschuppenhandschuhe und eine Wildranke benötigen. Dies ist keine einfache Lektion, aber eine, für die Ihr sicherlich das nötige Geschick habt.", sourceObjective = "Bringt Jangdor Flinkschreiter im Camp Mojache 2 Schildkrötenschuppenbrustplatten, 2 Schildkrötenschuppenhandschuhe und eine Wildranke.", sourceObjectiveStatus = "unverified-source-field" }
quests[2857] = { id = 2857, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wildlederhelm", description = "Ein Wildlederhelm bietet dem Träger verbesserten Kopfschutz, ohne dabei an der Bequemlichkeit zu sparen. Wie bei allen Wildlederrüstungen erzeugt die eingearbeitete Wildranke eine mächtige, aber zufällige magische Verstärkung der Struktur des Helms. Lederträger werden dieses Stück auf jeden Fall haben wollen!\n\nFür dieses Muster brauche ich 2 Tuniken des Nachtschleichers, 2 Stirnbänder des Nachtschleichers und eine Wildranke. Schließt diese Lektion erfolgreich ab und das Muster gehört Euch!", sourceObjective = "Bringt Jangdor Flinkschreiter im Camp Mojache 2 Tuniken des Nachtschleichers, 2 Stirnbänder des Nachtschleichers und eine Wildranke.", sourceObjectiveStatus = "unverified-source-field" }
quests[2858] = { id = 2858, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wildlederstiefel", description = "Euer Wissen über die Herstellung von Wildlederrüstungen wächst, {name}, aber trotzdem habt Ihr noch einiges zu lernen.\n\nWildlederstiefel sind die Grundlage eines jeden Sets. Diese Stiefel werden so gefertigt, dass sie den Fuß in Bequemlichkeit hüllen, während sie ihn gleichzeitig gegen die Gefahren des Abenteurerlebens wappnen. Die weichen Sohlen sind ein Segen für diejenigen, die bei ihrer Fußbekleidung auf leise Bewegung Wert legen.\n\nFür dieses Muster müsst Ihr mir 2 Hosen des Nachtschleichers und 2 Stiefel des Nachtschleichers herstellen. Ich werde außerdem zwei Wildranken benötigen, nicht nur eine. Wenn Ihr diese Dinge habt, werden wir weitermachen.", sourceObjective = "Bringt Jangdor Flinkschreiter im Camp Mojache 2 Hosen des Nachtschleichers, 2 Stiefel des Nachtschleichers und 2 Wildranken.", sourceObjectiveStatus = "unverified-source-field" }
quests[2859] = { id = 2859, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wildledergamaschen", description = "Ihr seid so weit, komplexere Lektionen zu meistern, {name}. Wildledergamaschen gehören zur robustesten und stärksten Lederausrüstung überhaupt. Bauch, Hüften, Schenkel und Solarplexus werden ungeheuer gut geschützt. Und wenn dann noch die Verstärkung hinzukommt, die die Wildranke bewirkt, werden Euch die Abenteurer, die diese Rüstung besitzen, jedes Mal danken, wenn sie Euch sehen.\n\nUm Euch dieses Muster zu geben, benötige ich 2 Schildkrötenschuppenhelme, 2 Schildkrötenschuppenarmschienen und 2 Wildranken.", sourceObjective = "Bringt Jangdor Flinkschreiter im Camp Mojache 2 Schildkrötenschuppenhelme, 2 Schildkrötenschuppenarmschienen und 2 Wildranken.", sourceObjectiveStatus = "unverified-source-field" }
quests[2860] = { id = 2860, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meister des Wildleders", description = "{name}, Ihr habt alles erlernt, was ich Euch lehren kann. Es gibt allerdings noch ein letztes Wildlederrüstungsmuster. Ich werde nicht von Euch verlangen, Euch unnötig dafür abzuplagen. Ihr habt es Euch bereits mehr als verdient. Jedoch kann ich dieses Muster nicht einfach mit Euch teilen.\n\nMein Lehrer, derjenige, der mich in dieses Handwerk einführte, muss Euch belohnen. Bringt diese Notiz zu Una. Sie lehrt Lederverarbeitung in Donnerfels. Zeigt ihr den Brief und lasst Euch von ihr als Gleichgestellten anerkennen, so wie ich das auch tue.", sourceObjective = "Gebt Una, der Lederverarbeitungsmeisterin von Donnerfels, Jangdors Schreiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[2861] = { id = 2861, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tabethas Aufgabe", description = "Gerüchte besagen, dass Tabetha, eine Magierkollegin, die tief in den Düstermarschen lebt, ein Hühnchen mit einem gewissen Sandtroll in Zul'Farrak zu rupfen hat. Wenn Ihr mit Tabetha sprecht, kann sie Euch sicher mehr dazu sagen.\n\nUnd nehmt ein paar Freunde mit, {name}. Falls Tabetha Euch nach Zul'Farrak schickt, wollt Ihr sicher nicht allein hingehen.\n\nIhr findet Tabethas Hütte westlich von Theramore und direkt nördlich der Ruinen der Steinbrecher.", sourceObjective = "Sprecht mit Tabetha in den Düstermarschen.", sourceObjectiveStatus = "unverified-source-field" }
quests[2862] = { id = 2862, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krieg gegen die Waldpfoten", description = "Die Gnolle... sie sind mehr als nur ein Ärgernis. Sie sind eine konstante Bedrohung für die Existenz dieses gesamten Lagers! Es ist unwichtig, ob sie Eingeborene des Feralas sind oder nicht. Wenn wir uns nicht gegen sie wappnen, werden wir uns eines Tages aus dem gesamten Gebiet vertrieben sehen.\n\nDie Gnollangriffe auf das Lager wurden in letzter Zeit heftiger. Wir brauchen Eure Hilfe dabei, ihre Anzahl zu reduzieren. Bringt mir zehn ihrer Mähnen und ich werde Euch stattlich für Eure Mühe entlohnen.\n\nLos!", sourceObjective = "Bringt Hadoken Flinkschreiter im Camp Mojache 10 Mähnen eines Waldpfotengnolls.", sourceObjectiveStatus = "unverified-source-field" }
quests[2863] = { id = 2863, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlag gegen die Alphas", description = "Der Plan besteht darin, verschiedene Anführer der Gnolle - Alphas, wie sie sich selbst nennen - in schneller Folge auszuschalten. Wenn wir einen solch schnellen und präzisen Schlag gegen sie erzielen können, würde es in ihren Rängen zu Chaos führen. Vielleicht würde es dann endlich auch in ihren dicken, von Flöhen zerbissenen Köpfen klar, dass wir sie vernichten können und werden!\n\nIch möchte, dass Ihr der Ausführende meines Willens seid. Eliminiert innerhalb einer Stunde fünf Alphas, wenn das klappen soll, {name}, sonst bleiben wir in dieser Pattsituation!", sourceObjective = "Tötet 5 Alphas der Waldpfoten und kehrt innerhalb einer Stunde zu Hadoken Flinkschreiter zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[2864] = { id = 2864, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tran'rek", description = "Mein Vetter Tran'rek ist in Schwierigkeiten. Er versprach mir vor einer Woche eine Fuhre Skarabäuspanzerschalen und hat bisher nicht geliefert. Er ist mein Vetter, also würde ich es wirklich hassen, wenn ich jemanden nach Gadgetzan schicken müsste, um ihm etwas zu brechen.\n\nKönnt Ihr für mich mit Tran'rek sprechen? Lasst ihn wissen, dass er diese Lieferung zusammenbekommen muss, bevor ich irgendetwas Unüberlegtes mache.\n\nGadgetzan liegt im nördlichen Tanaris, in Kalimdor.", sourceObjective = "Sprecht mit Tran'rek in Gadgetzan.", sourceObjectiveStatus = "unverified-source-field" }
quests[2865] = { id = 2865, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skarabäuspanzerschalen", description = "Die Skarabäen von Tanaris haben sehr harte Panzerschalen! Hart genug, um sie als Baumaterial für eine Menge Dinge zu verwenden. So viele Dinge!\n\nTatsächlich sind diese Panzer so nützlich... dass die Skarabäen beinahe bis zur Ausrottung gejagt wurden.\n\nIch weiß, wo es noch mehr Skarabäen gibt, und wenn Ihr mir versprecht, mir ihre Panzerschalen zu bringen, sage ich Euch, wo sie sind. Versprochen?\n\nO.k., die Skarabäen haben eine Kolonie in Zul'Farrak. Ich schätze, die Trolle jagen sie nicht wegen ihrer Panzerschalen.\n\nAber Ihr könnt das tun! Geht nach Zul'Farrak und besorgt mir unbeschädigte Skarabäuspanzerschalen!", sourceObjective = "Bringt Tran'rek in Gadgetzan 5 unbeschädigte Skarabäuspanzerschalen.", sourceObjectiveStatus = "unverified-source-field" }
quests[2866] = { id = 2866, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ruinen von Solarsal", description = "Südlich von uns befinden sich die Ruinen von Solarsal. Dies ist eine Gegend aus längst vergangener Zeit. Wir haben die Ruinen ursprünglich erforscht und nichts Besonderes darin gefunden. Daher sind wir friedlich wieder abgezogen.\n\nVor Kurzem haben die Hasskammnaga die Ruinen in alarmierender Anzahl besetzt. Zuerst hielten wir das für die Vorbereitungen auf einen Angriff. Obwohl diese Bedrohung immer noch gegeben ist, glauben wir, dass dort etwas anderes vorgeht.\n\nGeht dorthin, erforscht die Ruinen und achtet auf alles, was Euch ungewöhnlich vorkommt. Viel Glück, {name}.", sourceObjective = "Erforscht die Ruinen von Solarsal und findet etwas über die Anwesenheit der Naga dort heraus.", sourceObjectiveStatus = "unverified-source-field" }
quests[2867] = { id = 2867, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kehrt zur Mondfederfeste zurück", description = "Mit der Entdeckung des seltsamen Pavillons im Herzen der Ruinen von Solarsal ist es an der Zeit, zur Mondfederfeste zurückzukehren und General Shandris Mondfeder zu berichten, was hier entdeckt wurde.", sourceObjective = "Kehrt zu Shandris Mondfeder in der Mondfederfeste zurück und berichtet von Euren Entdeckungen.", sourceObjectiveStatus = "unverified-source-field" }
quests[2869] = { id = 2869, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gegen die Hasskämme", description = "Es ist derzeit die beste Handlungsweise, davon auszugehen, dass die Naga, was auch immer sie vorhaben, langfristig versuchen werden, die Insel für sich zu beanspruchen. Wir müssen aktive Schritte unternehmen, um diese Bedrohung auszuschalten, bevor es zu spät ist.\n\nBringt mir 10 Schuppen der Hasskämme in gutem Zustand. Es dürfte offensichtlich sein, wie man an diese herankommt. Ihr werdet Euch an den Naga das erste Mal Eure Sporen verdienen und wir haben dann eine geschwächte Nagapräsenz auf der Sardor-Insel - beides sind Aussichten, die uns zum Vorteil gereichen.", sourceObjective = "Bringt Latronicus Mondspeer in der Mondfederfeste 10 Nagaschuppen der Hasskämme.", sourceObjectiveStatus = "unverified-source-field" }
quests[2870] = { id = 2870, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gegen Lord Shalzaru", description = "{name}, unsere neuesten Spähberichte haben uns einen guten Einblick in die Kommandokette der Naga erlaubt. In ihren Truppen gibt es viele Adlige und die sind es, die den Ton angeben.\n\nUm genau zu sein, wir haben einen der grausameren Adligen als Lord Shalzaru identifiziert. Späher berichten, dass er höchstpersönlich bei einer kürzlich durchgeführten Nagaausgrabung in einer Höhle südlich der eigentlichen Ruinen, jenseits des Wassers, auf der Insel des Schreckens, ein seltsames Relikt gefunden hat.\n\nMacht dem ein Ende, indem Ihr ihm ein Ende macht, und bringt mir dieses Relikt, damit wir es untersuchen können.", sourceObjective = "Vernichtet Lord Shalzaru und bringt dann Latronicus Mondspeer in der Mondfederfeste das geheimnisvolle Relikt, das er entdeckt hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[2871] = { id = 2871, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überbringung des Relikts", description = "Wenn Ihr so nett wärt, das Relikt zu meiner Frau Vestia zu bringen, wüsste ich das zu schätzen. Sie ist nicht nur eine gute Priesterin für unsere Gemeinde, sondern auch eine der versiertesten Gelehrten, die es gibt. Ich könnte wahrscheinlich nicht einmal dann herausfinden, wo an diesem Ding oben oder unten ist, wenn mein Leben davon abhinge. Meine Frau wiederum... Also wenn irgendwer herausfinden kann, was das ist, dann sie... Und wir müssen es wissen!\n\nSie befindet sich gleich um die Ecke, ohne Zweifel am Studieren. Danke, {name}.", sourceObjective = "Bringt das geheimnisvolle Relikt zu Vestia Mondspeer in der Mondfederfeste.", sourceObjectiveStatus = "unverified-source-field" }
quests[2872] = { id = 2872, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stoleys Schuld", description = "Mein alter Kumpel Stoley schuldet mir eine ganz bestimmte Flasche Rum. Er schmeißt die Bar am Dampfdruckpier in Tanaris, Kalimdor, und er versprach mir, dass der Rum dort stärker ist als alles, was man in Beutebucht finden kann. Er ist so davon überzeugt, dass er sagt, wenn ich diesen Rum probiere und ihm nicht zustimme, würde er das Geld, das er mir schuldet, verdoppeln!\n\nNun, ich glaube, er ist nicht mehr so zuversichtlich wie damals, als wir zuletzt miteinander geredet haben, und hat jetzt wohl Angst, mir diesen Rum zu geben. Ich lasse eine Wette aber nicht auf sich beruhen, also wie wäre es, wenn Ihr für mich mit ihm redet?", sourceObjective = "Sprecht mit Stoley beim Dampfdruckpier.", sourceObjectiveStatus = "unverified-source-field" }
quests[2873] = { id = 2873, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stoleys Lieferung", description = "Ich schulde \"Seewolf\" MacKinley in Beutebucht etwas Rum, um eine Wette zu begleichen, aber mir ist der Rum ausgegangen! Kapitän Cuergo hat meine letzte Lieferung gestohlen und lagert sie in dieser ummauerten Piratenstadt im Süden.\n\nWenn Ihr meine Rumlieferung finden und zurückbringen könnt, dann kann ich MacKinley beweisen, dass Kalimdors Drinks die aus Beutebucht um Längen schlagen.", sourceObjective = "Bringt Stoleys Lieferung zu Stoley beim Dampfdruckpier.", sourceObjectiveStatus = "unverified-source-field" }
quests[2874] = { id = 2874, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lieferung für MacKinley", description = "Danke nochmals für Eure Hilfe, {name}. Hier habt Ihr eine Flasche Dampfdruckrum. Bringt sie zu MacKinley und er wird endlich seine verrückten Ansichten über Drinks aus Beutebucht über Bord werfen können.", sourceObjective = "Bringt Stoleys Flasche zu \"Seewolf\" MacKinley in Beutebucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[2875] = { id = 2875, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Andre Feuerbart", description = "Der niederträchtige Pirat Andre Feuerbart wird aufgrund seiner gegen die Einwohner des Dampfdruckpiers und Gadgetzan gerichteten Verbrechen gesucht.\n\nDurch Erlass der Ratsregierung ist hiermit jeder, der dies liest, zu tödlicher Gewaltanwendung bei der Festnahme von Andre und seinen Spießgesellen autorisiert.\n\nDes Weiteren gilt durch zusätzlichen Erlass, dass, sollte Andre verstorben oder anderweitig während seiner Anhörung unpässlich sein, sein Kopf als Ersatz gilt und die Aushändigung dieses Kopfes an Sicherheitschef Bilgenritzel als vertragsbindend angesehen wird.", sourceObjective = "Bringt Sicherheitschef Bilgenritzel beim Dampfdruckpier Andres Kopf.", sourceObjectiveStatus = "unverified-source-field" }
quests[2876] = { id = 2876, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schiffzeitpläne", description = "Auf dieser Schriftrolle sind die Zeitpläne für Lieferungen zwischen dem Dampfdruckpier und Beutebucht verzeichnet. Sowohl vergangene als auch zukünftige Lieferungen sind aufgeführt sowie Schiffsnamen. Große rote Kreuze befinden sich neben einigen der Schiffsreisen und Anmerkungen wie \"Große Beute\" oder \"Harter Kampf\" neben anderen.\n\nJemand beim Dampfdruckpier wird dieses Dokument sicher sehen wollen.", sourceObjective = "Berichtet den Behörden des Dampfdruckpiers von den Schiffzeitplänen.", sourceObjectiveStatus = "unverified-source-field" }
quests[2877] = { id = 2877, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Lauerfels aufräumen", description = "Wir Wildhämmer haben die Vergangenheit besser in Erinnerung als unsere Brüder in Eisenschmiede. Wenn Ihr Euch hier beliebt machen wollt, dann müsst Ihr Euch schon Eure Hände für uns schmutzig machen!\n\nDie Horde hat ihre Stellungen im Hinterland beim Lauerfels aufgegeben. Jetzt wimmelt es dort von üblen Schlicken und Schlammen. Wir haben Pläne für dieses Gebiet, aber zuerst muss uns eine Aufräummannschaft dort eine Bresche hineinschlagen.\n\nUnd hier kommt Ihr ins Spiel, Sonnenschein! Geht da runter und erledigt 10 grüne Schlicke und 10 jadegrüne Schlamme und meldet Euch dann wieder bei mir. Zieht los!", sourceObjective = "Tötet 10 grüne Schlicke sowie 10 jadegrüne Schlamme und meldet Euch dann wieder bei Fraggar Donnermantel beim Nistgipfel.", sourceObjectiveStatus = "unverified-source-field" }
quests[2878] = { id = 2878, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verderbte Liedblume" }
quests[2879] = { id = 2879, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Stock von Equinex", description = "Es sieht so aus, als könnte dieser Stock der Stock von Equinex sein. Der Stock von Equinex ist in Wirklichkeit ein Schlüssel. Mit ihm kann man den Monolithen von Equinex öffnen, der immer noch in den nördlichen Ruinen von Rabenwind steht.\n\nFindet die vier Feuer, die noch immer in den Ruinen brennen: Samha, Imbel, Byltan und Lahassa. Beschafft Euch deren Essenz. Und dann benutzt diese Essenz, während Ihr vor dem Monolithen von Equinex steht, um den Stock zu aktivieren. Wenn dies wirklich der Stock von Equinex ist, dann könnt Ihr den Monolithen öffnen und ein hochheiliges Artefakt daraus bergen.", sourceObjective = "Aktiviert Troyas Stock und findet den Monolithen von Equinex.", sourceObjectiveStatus = "unverified-source-field" }
quests[2880] = { id = 2880, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kopfgeld für Trollhalsketten", description = "Seid Euch darüber im Klaren, {race} - wir sind NICHT Teil der Allianz! Die Wildhämmer sind unabhängig. Um den Wert einer Person zu beweisen, verlassen sie sich lieber auf Taten und hören nicht auf das Geschwätz derer, die mit ihrem Gequassel versuchen, ihre Untätigkeit zu überspielen.\n\nWenn Ihr hier Freunde sucht, beweist uns erst Euren Wert! Die üblen Trolle, die die Hänge des Hinterlands überrennen, tragen manchmal Stammeshalsketten. Bringt mir 5 davon und wir werden das als einen Schritt in die richtige Richtung für Euch verbuchen.", sourceObjective = "Bringt Fraggar Donnermantel beim Nistgipfel 5 Trollstammeshalsketten.", sourceObjectiveStatus = "unverified-source-field" }
quests[2881] = { id = 2881, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kopfgeld für Trollhalsketten" }
quests[2882] = { id = 2882, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cuergos Gold", description = "Diese Karte zeigt ein Stück Strand an einer Südküste. Unter der Karte stehen elegant geschriebene Worte:\n\n\nSüdlich des Piers\nDürft Ihr drauf hoffen\nFindet Flagge, Mast und Knochen\nGrabt dort, wenn Ihr tapfer sein wollt\nGrabt und erbt Cuergos Gold!\nEinen Schlüssel werdet Ihr brauchen, einen Schlüssel werdet Ihr sehen\nDie Mannen dort woll'n als Bezahlung Euer Blut Euch nehm'n.", sourceObjective = "Findet Cuergos Gold!", sourceObjectiveStatus = "unverified-source-field" }
quests[2902] = { id = 2902, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waldpfotennachforschung", description = "Gnolle sind zwar nicht die Hellsten, aber sie werden bestimmt die Strategie ihrer jüngsten Aktivitäten irgendwo dokumentiert haben. Wenn wir diese Pläne finden würden, hätten wir eine bessere Vorstellung davon, was sie so aufbringt.\n\nIch möchte, dass Ihr zu den Waldpfoten zurückgeht und nach allem sucht, was Ähnlichkeit mit ihren Schlachtplänen haben könnte. Irgendwas muss es geben, ihre Angriffe waren einfach zu gut koordiniert. Findet diese Schlachtpläne und kommt zu mir zurück, sobald Ihr sie habt.", sourceObjective = "Findet die Schlachtpläne der Gnolle irgendwo in den Gnoll-Lagern südlich vom Camp Mojache.", sourceObjectiveStatus = "unverified-source-field" }
quests[2903] = { id = 2903, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlachtpläne", description = "Jetzt, nachdem die Schlachtpläne der Gnolle entdeckt wurden, bleibt nur noch, die Pläne zu Hadoken Flinkschreiter ins Camp Mojache zurückzubringen. Vielleicht kann er oder irgendjemand dort besser darauf schließen, was die Gnolle vorhaben.", sourceObjective = "Bringt die Schlachtpläne der Waldpfoten zu Hadoken Flinkschreiter ins Camp Mojache.", sourceObjectiveStatus = "unverified-source-field" }
quests[2904] = { id = 2904, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine schöne Bescherung", description = "<Kernobee stöhnt.> Was... Was ist passiert?\n\nDas Letzte, an das ich mich erinnere, ist, wie ich von einer Gruppe Dunkeleisenzwerge gefangen, halb tot geprügelt und dann hier zu diesen schmutzigen Troggs geworfen wurde.\n\nHolt mich hier raus, {name}!\n\nSo ist der Plan: Bringt mich zum Ausgang; Wenn wir es lebend hier herausschaffen, geht nach Beutebucht und lasst Scooty wissen, dass ich nach Ratschet gegangen bin, um Tüftelwiz zu warnen, dass die Dunkeleisenzwerge in die Herstellung dieser Supermaschine verwickelt sind.\n\nGehen wir!", sourceObjective = "Begleitet Kernobee zur Uhrwerkgasse und meldet Euch dann wieder bei Scooty in Beutebucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[2922] = { id = 2922, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettet Techbots Hirn!", description = "Als unsere geliebte Stadt Gnomeregan fiel, muss ein verirrter Funke mein armes Geschöpf, Techbot, völlig durcheinander gebracht haben. Früher half er mir und meinen Kollegen mit seinen zahllosen Dingsdas und seiner endlosen Speicherkapazität, aber sein positronisches Gehirn wurde polarisiert. Es ist jetzt negatronisch... und Techbots Verhalten wurde umgekehrt. Er wütet jetzt in ganz Gnomeregan!\n\nDoch vielleicht kann man ihn noch retten. Wenn Ihr seinen Speicherkern auffinden und zu mir bringen könnt, kann ich die Ursache der Polarisierung möglicherweise finden und meinen armen Techbot reparieren.", sourceObjective = "Bringt Techbots Speicherkern zu Tüftlermeister Oberfunks nach Eisenschmiede.", sourceObjectiveStatus = "unverified-source-field" }
quests[2923] = { id = 2923, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tüftlermeister Oberfunks", description = "Tüftlermeister Oberfunks ist ob des Schicksals seiner mechanischen Schöpfung, Techbot, ziemlich bestürzt. Ich erinnere mich an Techbot als ein freundliches und hilfsbereites Werkzeug der Gnome, aber Oberfunks erzählte mir, er hätte eine Fehlfunktion.\n\nWirklich traurig. Aber mit etwas Glück kann er vielleicht repariert werden!\n\nSprecht mit Tüftlermeister Oberfunks in Tüftlerstadt, Eisenschmiede. Er würde sich über Eure Hilfe freuen.", sourceObjective = "Sprecht mit Tüftlermeister Oberfunks in Eisenschmiede.", sourceObjectiveStatus = "unverified-source-field" }
quests[2924] = { id = 2924, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grundlegende Artifixe", description = "Ein beinahe universell einsetzbares mechanisches Bauteil - das grundlegende Artifix - war den Tüftlern und Schmieden von Gnomeregan von großem Nutzen. Doch während der panischen Flucht aus unserer Stadt hat niemand daran gedacht, einige von diesen Geräten mitzunehmen! Und ich brauche eine ganze Menge davon für eine Arbeit, die ich in Kürze in Angriff nehmen werde.\n\nBitte, geht nach Gnomeregan und bringt mir einige grundlegende Artifixe. Ihr werdet sie in den tieferen Bereichen unserer Stadt finden, in Künstliche Extrapolatoren genannten Behältern.\n\nDanke, {name}, und bitte beeilt Euch!", sourceObjective = "Bringt Klockmort Spannsplint in Eisenschmiede 12 grundlegende Artifixe.", sourceObjectiveStatus = "unverified-source-field" }
quests[2925] = { id = 2925, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klockmorts Grundlagen", description = "Ein Gnomenfreund, Klockmort Spannsplint, hat mich aus Eisenschmiede kontaktiert. Er teilt mir mit, dass er Hilfe bei einer gefährlichen, aber unverzichtbaren Mission nach Gnomeregan braucht, der einst so großen Gnomenstadt, die jetzt verseucht und voller verrückter Gnome und ihrer Gerätschaften ist.\n\nIch muss hier bleiben, aber mir blutet das Herz, wenn ich meinem Freund nicht helfen kann. Wenn Ihr an meiner Stelle gehen könnt, dann stünde ich tief in Eurer Schuld.\n\nIhr könnt Klockmort in Tüftlerstadt in Eisenschmiede finden.", sourceObjective = "Sprecht mit Klockmort Spannsplint in Eisenschmiede.", sourceObjectiveStatus = "unverified-source-field" }
quests[2926] = { id = 2926, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gnogaine", description = "Seit dem Unfall redet Gnoarn nur noch davon, Gnomeregan vom Troggbefall zu befreien und ein Heilmittel für die Erkrankung, die die Stadt verseucht, zu finden, {name}.\n\nZum Glück sind Razzle und ich gerade dabei, ein solches Heilmittel zu entwickeln... oder vielleicht auch ein Rezept für wirklich starken Rum. Genau wissen wir das aber erst, wenn wir es ausprobiert haben! Logischerweise benötigen wir zum Test unserer Theorie ein paar Dinge, vor allem Ablagerungen von den bestrahlten Troggs in Gnomeregan. Füllt diese Phiole mit dem grünen Leuchten und bringt sie zurück!", sourceObjective = "Sammelt mit der leeren bleiernen Sammelphiole radioaktive Ablagerungen bestrahlter Eindringlinge oder Plünderer. Sobald sie voll ist, bringt Ihr sie zu Ozzie Wechselvolt nach Kharanos zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[2927] = { id = 2927, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Tag danach", description = "Ihr glaubt doch wohl nicht, dass ich schon immer so kahlköpfig war, oder? Nein, <werter Herr/holde Dame>! Das Strahlungsleck in Gnomeregan rief diesen tragischen Haarverlust hervor. Vor jenem Tag hatte ich den einzigen Gnomenafro in ganz Azeroth.\n\n<Gnoarn schüttelt drohend die Faust.>\n\nVerdammt seien diese verdammten dreckigen Troggs, verdammt seien sie alle!\n\nVielleicht ist es noch nicht zu spät, {name}. Wir können sie vielleicht immer noch retten - die Stadt, meine ich! Sprecht mit Ozzie Wechselvolt in Kharanos. Er und sein Partner Razzle arbeiten an einer Lösung.", sourceObjective = "Sprecht mit Ozzie Wechselvolt in Kharanos in Dun Morogh.", sourceObjectiveStatus = "unverified-source-field" }
quests[2928] = { id = 2928, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gyrobohrmatische Exkavation", description = "Es ist schrecklich, {name}. Wir werden nicht genug Teile haben, um unsere Flotte aus gyrobohrmatischen Exkavationatoren nach Dun Morogh zu bringen.\n\nWir brauchen Ersatzteile, {name}. Und welch besseren Ort als Gnomeregan könnte es geben, um Ersatzteile für unsere Fahrzeuge zu besorgen? Es heißt, dass Bots und Mechs dort herumlaufen wie Vieh auf der Weide.\n\nIhr müsst für mich nach Gnomeregan gehen und diese Roboter auseinander nehmen. Bringt mir ihre Innereien. Zwei Dutzend sollten ausreichen.", sourceObjective = "Bringt 24 robomechanische Innereien zu Shoni nach Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[2929] = { id = 2929, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der große Verrat", description = "Ich habe Thermadraht vertraut, {race}. Ich hätte nie vermutet, dass er mich und das ganze Gnomenvolk verraten würde. Und wofür? Macht? Reichtum? Alles Dinge, die er mit der Zeit auch so erlangt hätte. Jetzt sind wir aus unserer Heimat verdrängt worden und dieser Wahnsinnige ist dafür verantwortlich. Der König des Nichts...\n\nWir werden Gnomeregan zurückerobern, {name}. Wir werden nicht ruhen, bis die Stadt wieder unter unserer Kontrolle steht. Wenn Ihr Euch unserem Kampf anschließen wollt, habe ich eine einfache Bitte an Euch: Tötet den Verräter. Vernichtet Robogenieur Thermadraht.", sourceObjective = "Reist nach Gnomeregan und tötet Robogenieur Thermadraht. Kehrt zu Hochtüftler Mekkadrill zurück, wenn der Auftrag ausgeführt ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[2930] = { id = 2930, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Datenrettung", description = "Als wir aus Gnomeregan flohen, haben wir so viele Daten zurückgelassen! Lebenswichtige Informationen!\n\nIch brauche die Daten auf einer Prismalochkarte aus einem Matrix-Prägographen 3005-D, einem Hochsicherheitsterminal, tief in Gnomeregan. Ihr müsst auf dieses Terminal zugreifen, aber dafür braucht Ihr die Zugangsberechtigung...und um die zu erhalten, müsst Ihr erst Zugang zu den Terminals niedrigerer Sicherheitsstufen - Modelle A, B und C - haben. DAFÜR wiederum braucht Ihr Sicherheitslochkarten, angefangen mit einer weißen...Und wir haben alle Lochkarten in der Stadt vergessen.\n\nDas ist eine Katastrophe! Könnt Ihr helfen?", sourceObjective = "Bringt Mechanikermeister Gussmuff in Eisenschmiede eine Prismalochkarte.", sourceObjectiveStatus = "unverified-source-field" }
quests[2931] = { id = 2931, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gussmuffs Auftrag", description = "Mechanikermeister Gussmuff in Eisenschmiede sucht Abenteurer! Er organisiert Teams, um Gnomeregan auf einer Datensicherungsmission höchster Sicherheitsstufe und Wichtigkeit zu betreten.\n\nGussmuff mag zwar nicht wie ich ein Mitglied der Erleuchteten Vereinigung für Arkanologie, Alchemie und Ingenieurwissenschaften sein, aber er ist dennoch ein kluger Gnom, und wenn er es für wichtig hält, dann besteht nach meinen Berechnungen eine vierundachtzigprozentige Wahrscheinlichkeit, dass es wirklich wichtig ist.\n\nDas ist eine gute Chance!", sourceObjective = "Sprecht mit Mechanikermeister Gussmuff in Eisenschmiede.", sourceObjectiveStatus = "unverified-source-field" }
quests[2932] = { id = 2932, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grausige Botschaft", description = "Die Trolle der Bleichborken waren einst Verbündete der Horde, aber sie haben Thrall hintergangen... und das muss bestraft werden!\n\nHier, nehmt meine Pike und geht weit gen Norden ins Hinterland. Ihr werdet es nordöstlich von Tarrens Mühle vorfinden, einem Dorf, das von unseren Verbündeten, den Verlassenen, kontrolliert wird.\n\nWenn Ihr ins Hinterland kommt, jagt Trolle der Bleichborken. Sammelt ihre Schädel und rammt meine Pike in einem ihrer kleineren Dörfer in den Boden: in Hiri'watha oder Zun'watha.\n\nZeigt ihnen, dass ihre heimtückischen Taten Konsequenzen nach sich ziehen!", sourceObjective = "Sammelt Schädel der Bleichborken und hängt sie an Nimboyas Pike. Platziert Nimboyas behängte Pike in einem der Bleichborkendörfer im Hinterland und kehrt dann zu Nimboya ins Schlingendorntal zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[2933] = { id = 2933, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Giftflaschen", description = "Diese Flaschen enthalten ein übles grünes Gift.\n\nWenn man die Anzahl der Flaschen in diesem Dorf bedenkt, müssen die Bleichborken es für sehr wichtig halten. Vielleicht will einer der Apotheker im nahe gelegenen Tarrens Mühle eine Probe davon.", sourceObjective = "Bringt eine Giftflasche zu einem Apotheker nach Tarrens Mühle.", sourceObjectiveStatus = "unverified-source-field" }
quests[2934] = { id = 2934, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unbeschädigter Giftbeutel", description = "Ich benötige eine frische Probe von dem Gift, das Ihr mir gebracht habt. Die Spinnen, von denen es gesammelt wurde, dürften im Hinterland leben. Jagt sie, bis Ihr einen unbeschädigten Giftbeutel findet, und bringt ihn mir. Ihr findet viele Spinnen nahe der Trollstadt Shadra'Alor.\n\nUnd trödelt nicht rum, {name}, denn der Giftbeutel muss frisch sein, wenn Ihr ihn abliefert.", sourceObjective = "Bringt Apotheker Lydon in Tarrens Mühle einen unbeschädigten Giftbeutel.", sourceObjectiveStatus = "unverified-source-field" }
quests[2935] = { id = 2935, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Konsultiert Meister Gadrin", description = "Das Gift der Brutwachen war nicht so potent wie das Gift, das Ihr mir ursprünglich gebracht habt. Es muss von einer anderen Spinne gewesen sein.\n\nIch will eine frische Probe dieses Gifts. Um herauszufinden, woher es kam, müsst Ihr Euch mit einem Troll unterhalten, der die Bleichborken gut kennt – Meister Gadrin im Dorf Sen'jin. Reist nach Durotar und sprecht mit Gadrin. Wenn wir Glück haben, weiß er, woher die Bleichborken ihr Gift bekommen.", sourceObjective = "Sprecht mit Meister Gadrin in Sen'jin.", sourceObjectiveStatus = "unverified-source-field" }
quests[2936] = { id = 2936, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Spinnengott", description = "Die Bleichborken verehren einen Spinnengott und von ihm bekommen sie ihr wirkungsvolles Gift. Wenn Ihr also ihr Gift wollt, müsst Ihr ihren Gott beschwören!\n\nUm das zu tun, müsst Ihr seinen wahren Namen wissen und dieser Name steht auf einer Tafel, die in Tanaris, in der Trollstadt von Zul'Farrak, in einer Gruft vergraben ist, die von Theka dem Märtyrer bewacht wird.\n\nBesiegt Theka und findet und lest diese Tafel, um den Namen des Spinnengottes herauszufinden. Wenn Ihr ihn kennt, kehrt zu mir zurück.", sourceObjective = "Lest von der Schrifttafel des Theka, um den Namen des Spinnengottes der Bleichborken zu erfahren, und kehrt dann zu Meister Gadrin zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[2937] = { id = 2937, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Beschwörung von Shadra", description = "Nehmt dieses Pergament und verlest es am Altar von Shadra'Alor tief in der Welt der Bleichborken im Hinterland. Dies wird Shadra, den Spinnengott, beschwören.", sourceObjective = "Besiegt Shadra am Altar von Shadra'Alor und bringt ihr Gift zu Apotheker Lydon nach Tarrens Mühle.", sourceObjectiveStatus = "unverified-source-field" }
quests[2938] = { id = 2938, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gift für Unterstadt", description = "Das Gift, das Ihr vom Spinnengott der Bleichborken beschafft habt, ist ein großer Fund! Ich konnte mit nur einem Tropfen von dem Zeug fast zwei Dutzend Hasen töten! Na gut, einige dieser Hasen waren sehr jung und klein genug, um auf eine Handfläche zu passen, und daher war ihre Widerstandskraft gegen Toxine bestimmt niedrig, aber man kann nicht leugnen, dass dieses Gift mächtig ist!\n\nIch würde gern eine Probe zu meinem Vorgesetzten, Apotheker Faranell, in das Apothekarium von Unterstadt entsenden. Ich bin sicher, er würde es gern selbst testen.", sourceObjective = "Bringt Faranells Päckchen zu Apothekermeister Faranell nach Unterstadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[2939] = { id = 2939, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der Suche nach Wissen", description = "Auch wenn die Ruinen von Feralas ziemlich gefährlich sein können, so erzählen sie doch viel darüber, was hier passiert ist...\n\nAls ich vor einigen Tagen das Geröll südlich von hier durchstöberte, fand ich etwas, das wie ein gewöhnlicher Stock aussah. Allerdings werde ich das Gefühl nicht los, dass es mehr damit auf sich hat. Angelas und ich haben über unseren Büchern hier gebrütet, aber wir konnten nichts darüber herausfinden.\n\nIch habe aber eine Kollegin in Darnassus, die uns vielleicht erzählen kann, was das ist, {name}. Warum sprecht Ihr nicht mit ihr und seht, ob sie uns helfen kann?", sourceObjective = "Sprecht mit Daryn Leuchtwind im Dorf Rut'theran.", sourceObjectiveStatus = "unverified-source-field" }
quests[2940] = { id = 2940, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feralas: Ein historischer Abriss", description = "Es sieht so aus, als sei dieses Buch seit langer Zeit von niemandem mehr geöffnet worden. Sein Einband ist ziemlich abgenutzt und seine Seiten sind vergilbt, aber nach einer kurzen Untersuchung stellt Ihr fest, dass es genau das sein könnte, was Troyas sucht.\n\nIhr steckt es ein, aber dann fällt Euch ein, dass Ihr vielleicht vorher fragen solltet, bevor Ihr es ausleiht.", sourceObjective = "Fragt Daryn Leuchtwind, ob Ihr Euch ihr Buch ausleihen dürft.", sourceObjectiveStatus = "unverified-source-field" }
quests[2941] = { id = 2941, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Borger", description = "Ich habe in meinem Leben viele Dinge studiert und meine jüngste Leidenschaft sind die Schnappkiefer, die den Strand im Hinterland bevölkern. Es gibt einen bestimmten, den ich gern sehen würde, einen Riesenschnappkiefer namens Gammerita. Ich würde gern selbst hingehen, aber meine Forschungen halten mich hier. Ein Bild von Gammerita wäre wohl die nächstbessere Lösung.\n\nBringt diesen Brief zu Curgle Kurbelhüpf nach Tanaris. Sie hat etwas für mich erfunden, das Bilder einfangen kann. Ich glaube, sie nannte es \"Schnappschuss\"...", sourceObjective = "Bringt den Brief zu Curgle Kurbelhüpf nach Tanaris.", sourceObjectiveStatus = "unverified-source-field" }
quests[2942] = { id = 2942, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Morgenstein", description = "In dem Moment, in dem das Artefakt vom Monolithen getrennt wird, fühlt Ihr, wie die Energie im Stock von Equinex sich zu verflüchtigen beginnt.", sourceObjective = "Bringt den funkelnden Stein und den Stock von Equinex zu Troyas Mondhauch in die Mondfederfeste.", sourceObjectiveStatus = "unverified-source-field" }
quests[2943] = { id = 2943, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Troyas", description = "Hier, {name}. Bitte, passt auf mein Buch auf.\n\nNun aber schnell. Troyas wartet bestimmt schon ganz ungeduldig auf Eure Rückkehr.", sourceObjective = "Liefert das Buch bei Troyas Mondhauch in der Mondfederfeste ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[2944] = { id = 2944, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Superschnapper FX", description = "Werft erst mal einen Blick auf meine neue Erfindung, {name}. Visiert einfach an, wovon Ihr ein Bild haben möchtet, und drückt dann auf den Knopf.\n\nWas war das für eine Kreatur aus dem Hinterland, die Ihr erwähnt habt? Gammerita? Tja, viel Erfolg bei der Suche nach ihr. Ich bin sicher, Daryn wird mit dem Schnappschuss, den Ihr ihr zurückbringt, sehr zufrieden sein.\n\nWie auch immer, hier habt Ihr den Superschnapper. Viel Spaß!", sourceObjective = "Benutzt den Superschnapper FX, um einen Schnappschuss von Gammerita zu machen, und kehrt dann zu Daryn Leuchtwind nach Rut'theran zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[2945] = { id = 2945, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schmutzverkrusteter Ring", description = "Ihr habt bei einer der Leichen der Dunkeleisenzwerge etwas entdeckt, das wie ein Ring aussieht. Es ist jedoch schwer zu sagen, was für ein Ring das ist. Das Ding ist derart mit Dreck und Verkrustungen überzogen, dass man es unmöglich an einen Finger stecken kann. Ihr glaubt, unter den Verkrustungen Edelmetall schimmern und vielleicht sogar einen Edelstein glitzern zu sehen.\n\nWenn Ihr diesen Ring verwenden wollt, müsst Ihr nach etwas suchen, das die Verkrustungen entfernt.", sourceObjective = "Findet einen Weg, den schmutzverkrusteten Ring zu säubern.", progress = "Der Gnomenapparat vor Euch trägt eine Plakette mit der Aufschrift \"Der Funkelmat 5200\". Laut der Anleitung unter der Plakette besteht der Sinn dieser Maschine darin, jedweden Schmutz von Gegenständen abzuschrubben. Um den Vorgang zu starten, legt man den Gegenstand in die Maschine und wirft drei Silbermünzen in den Münzschlitz.\n\nEs scheint, als sei der verkrustete Ring, den Ihr gefunden habt, geradezu perfekt, um diese Maschine auszuprobieren.", completion = "Ihr legt den Ring in den Funkelmat 5200 und werft eine Silbermünze in den Schlitz.\n\nFurchtbares Knirschen und Mahlen dringt aus der Maschine, als sie heftig zu ruckeln beginnt. Man kann nur raten, was mit dem Ring in der Maschine passiert...\n\nDann stoppt die Maschine plötzlich, ihren Stillstand mit einem einfachen \"Ding!\" verkündend. Der Aufnahmebehälter öffnet sich und offenbart eine kleine, hübsch verpackte Schachtel mit einer roten Schleife. Es scheint, als würde der Funkelmat 5200 alles auch gleich noch als Geschenk verpacken!", sourceObjectiveStatus = "unverified-source-field" }
quests[2946] = { id = 2946, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mal sehen, was passiert...", description = "Wir möchten, dass Ihr die Mininaturscheiben, die Ihr gefunden habt, zu den versiegelten Toren von Uldum bringt. Wir... wir sind uns nicht ganz sicher, was dann passieren wird.\n\nEs klingt ein bisschen riskant, sicher, das geben wir auch zu. Es könnte allerdings auch sein, dass überhaupt nichts passiert. Vielleicht müsst Ihr mit den Scheiben irgendetwas anstellen. Vielleicht öffnen sich die Türen, wenn Ihr die Scheiben bei Euch habt. Versucht alles Mögliche und seid offen für alles, was passieren könnte.\n\nKehrt nach Eisenschmiede zurück, wenn Ihr herausgefunden habt, was die Scheiben bewirken. Es wird einiges zu untersuchen geben, wenn Ihr das erledigt habt!", sourceObjective = "Bringt die Miniaturplatinscheiben zu den Toren von Uldum in Tanaris und sucht nach Hinweisen auf die Verbindung zwischen beidem.", sourceObjectiveStatus = "unverified-source-field" }
quests[2947] = { id = 2947, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rückkehr des Rings", description = "Ihr öffnet die Schachtel, die der Funkelmat 5200 ausgegeben hat, und entdeckt, was Ihr vermutet hattet - einen glänzenden Ring! Beim Anstecken des Rings fühlt Ihr magische Macht durch Euren Körper fließen.\n\nAuf der Innenseite des Rings befindet sich eine kleine, aber dennoch klar erkennbare Gravur des Siegels von Eisenschmiede. Daneben sind drei kleine Initialen eingraviert: \"TdK\". Dies könnten entweder die Initialen des ursprünglichen Besitzers oder die des Herstellers des Rings sein. Den Ring behalten...oder ihn dieser Person zurückgeben? Entscheidungen über Entscheidungen...", sourceObjective = "Ihr könnt den Ring entweder behalten oder die Person finden, die für die Prägung und Gravuren auf der Innenseite des Rings verantwortlich ist.", progress = "He, immer mit der Ruhe, Partner - ich bin ein wichtiger Geschäftsmann! Der Kurier, der die Miete überbringen sollte, ist bestimmt einfach nur spät dran... Moment mal... Ihr seid ja gar nicht mein Vermieter.\n\nNatürlich seid Ihr das nicht - wie dumm von mir! Ihr seid hier, weil Ihr den besten Juwelier in ganz Eisenschmiede sucht, einen, der KEINE VERFLUCHTEN Gegenstände herstellt. Jawohl!\n\nHm... Was braucht Ihr?", completion = "Ein Ring, sagt Ihr? Lasst mich mal sehen... Ja, und wie ich diesen Ring gefertigt habe.\n\nBevor Gnomeregan verloren ging, hatte ich dort einen kleinen Laden. Vielleicht ist es einer von denen, die ich zurückließ, als ich in die Hügel geflohen bin. Er ist recht schlicht gehalten und ich habe mehrere dieser Art hergestellt. Vielleicht gehörte er auch jemandem, der es nicht bis nach draußen geschafft hat.\n\nDunkeleisenzwerge hatten ihn? Tja, das fügt den ganzen Verschwörungstheorien, die bereits herumgeistern, eine weitere Ebene hinzu. Vielleicht interessieren sich offizielle Stellen dafür. Für Leute wie mich ist so etwas unwichtig.\n\nAber jetzt zurück zu diesem Ring...", sourceObjectiveStatus = "unverified-source-field" }
quests[2948] = { id = 2948, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gnomenverbesserungen", description = "Hört mir zu, {name}. Dieser Ring gehört Euch, das ist schon richtig... aber ich kann Euch einen besseren machen! Das Design ist, wie ich bereits sagte, wirklich einfach. Ich bin heutzutage wesentlich geschickter und für die läppische Summe von dreißig Silbermünzen werde ich ihn für Euch aufpeppen! Na ja, eigentlich etwas mehr als dreißig...\n\nIch bin derzeit in einer misslichen Lage. Mein ganzer Materialvorrat ist aufgebraucht. Wenn Ihr mir einen Barren Silber und einen Moosachat bringt, verziere ich Euch den Ring damit und peppe ihn richtig schön auf!!\n\nVertraut mir!", sourceObjective = "Bringt Talvash del Kissel in Eisenschmiede den glänzenden Goldring, einen Silberbarren, einen Moosachat und 30 Silbermünzen.", progress = "Habt Ihr die Materialien, die ich benötige? Ich würde Euch nicht darum bitten, wenn ich nicht gerade völlig vom Glück verlassen wäre...", completion = "Ah, genau das, was ich brauchte! Eines Tages, wenn ich es aus diesem Loch, in dem ich mich ungerechterweise befinde, herausgearbeitet habe, werde ich für Euch, nein für JEDERMANN die besten Schmuckstücke in ganz Azeroth herstellen! Bis es so weit ist, danke ich Euch, dass Ihr in Bezug auf die Reagenzien so anständig wart. Ich würde normalerweise zehnmal so viel für einen Ring von dieser Qualität verlangen, wie ich Euch abgeknöpft habe...\n\nWo wir gerade davon sprechen, hier ist Euer neuer Ring!", sourceObjectiveStatus = "unverified-source-field" }
quests[2949] = { id = 2949, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rückkehr des Rings", description = "Ihr öffnet die Schachtel, die der Funkelmat 5200 ausgegeben hat, und entdeckt einen glänzenden Ring! Beim Anstecken des Rings fühlt Ihr magische Macht durch Euren Körper fließen.\n\nAuf der Innenseite des Rings befindet sich eine kleine, aber dennoch klar erkennbare Gravur des Siegels von Orgrimmar. Daneben sind Buchstaben eingraviert, aber selbst nach der Säuberung sind nur die ersten drei zu erkennen: 'NOG...'\n\nDies könnten entweder die Initialen des ursprünglichen Besitzers oder die des Herstellers des Rings sein. Den Ring behalten...oder 'NOG' suchen - Entscheidungen, Entscheidungen...", sourceObjective = "Ihr könnt den Ring entweder behalten oder die Person finden, die für die Prägung und Gravuren auf der Innenseite des Rings verantwortlich ist.", progress = "Man sollte meinen, wir finden selbst einen Weg, diese dreckigen kleinen Gnome zu übertrumpfen. Ich würde sogar wetten, dass sie uns diese Maschine ursprünglich gestohlen haben! Pah, diese schleimigen, schmutzigen... ähm, ja? Braucht Ihr etwas?", completion = "Ein Ring aus Gnomeregan? Lasst mich mal sehen... nicht von mir, aber interessant.\n\nDiese Sache mit Gnomeregan - das hätte keinen größeren Trotteln passieren können. Jahrelang sind sie ein Witz und auf einmal bauen sie quasi über Nacht bessere Maschinen als wir?\n\nDunkeleisenzwerge hatten den Ring bei sich? Das wird ja immer interessanter! Hmmm, vielleicht haben die Gnome ja deren verrückte Golempläne gestohlen und verändert... Diese Dunkeleisenzwerge, die würden ihnen das bestimmt gern ordentlich heimzahlen. Es lohnt sich ganz sicher, da mal nachzuforschen.\n\nUnd da ist schließlich die Sache mit dem Ring...", sourceObjectiveStatus = "unverified-source-field" }
quests[2950] = { id = 2950, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noggs Ringerneuerung", description = "Nein, nein, nein - ich behaupte nicht plötzlich, der Ring sei meiner. Normalerweise mache ich so etwas nicht, aber Eure Information über die Dunkeleisenzwerge war sehr nützlich. Ich werde diesen Ring für Euch so verbessern, dass selbst der, der dieses einfache kleine Ding hergestellt hat, es nicht hätte besser machen können. Wahrscheinlich war es irgendein Gnom...\n\nWenn Ihr mir einen Barren Silber, einen Moosachat und dreißig Silbermünzen bringt, verziere ich den Ring damit derart, dass seine Magie noch verstärkt wird. Interessiert?", sourceObjective = "Bringt Nogg in Orgrimmar den glänzenden Goldring, einen Silberbarren, einen Moosachat und 30 Silbermünzen.", progress = "Habt Ihr die Materialien, die ich benötige? Ich kann dieses Stück nicht ohne die Dinge verbessern, um die ich Euch gebeten habe.", completion = "Hier habt Ihr Euren Ring, besser als je zuvor. Danke nochmals für die Information über diese Dunkeleisenzwerge. Das sieht nach einem vernünftigen Hinweis darauf aus, woher diese Gnome auf einmal mit Inspiration nach Goblinart gesegnet wurden.", sourceObjectiveStatus = "unverified-source-field" }
quests[2951] = { id = 2951, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Funkelmat 5200!", description = "Dieser Apparat ist etwas ganz Besonderes unter den Gnomen, er bietet dem Wahnsinn außerhalb dieses Raums tapfer die Stirn. Eine kleine Plakette auf dem Gerät besagt: \"Der Funkelmat 5200\", gefolgt von einem kurzen Text:\n\n\"Schmutz und Verkrustungen ruinieren Euer Funkelzeug? Der Funkelmat 5200 definiert das Wort Glanz neu! Gebt den Gegenstand hinein, den Ihr gesäubert haben wollt, und werft drei Silbermünzen in den Münzschlitz. Lasst den Funkelmat 5200 einen Moment arbeiten - und voilà! Eure Wertgegenstände werden sauber und glänzend herauskommen!\"", sourceObjective = "Gebt einen schmutzverkrusteten Gegenstand in den Funkelmat 5200 und stellt sicher, dass Ihr drei Silbermünzen habt, um die Maschine zu aktivieren.", progress = "Es scheint, als brauche das Gerät irgendein schmutzverkrustetes Objekt zum Säubern sowie drei Silbermünzen, um den Apparat in Gang zu bringen. Ist beides vorhanden, sollte der Funkelmat 5200 funktionieren...", completion = "Ihr füttert den Funkelmat 5200 mit dem schmutzverkrusteten Gegenstand sowie mit drei Silbermünzen. Die Maschine erwacht schlagartig zum Leben und versucht hektisch, den unbekannten Gegenstand vom Schmutz zu reinigen. Laute, heftige, peitschende Geräusche schlagen Euch aus dem Herzen der Maschine entgegen. Der Metallrahmen des Apparates knarrt und ächzt, als er hin und her schlingert...", sourceObjectiveStatus = "unverified-source-field" }
quests[2952] = { id = 2952, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Funkelmat 5200!", sourceObjective = "Der Funkelmat 5200 stoppt so schnell, wie er losgelegt hat. Ein einfaches \"Ding\" ist aus der Maschine zu hören und der Aufnahmebehälter der Maschine springt auf. Im Funkelmat 5200 liegt eine kleine Schachtel, die von einem Schleifchen umschlungen ist. Offensichtlich verpackt die Maschine ein Objekt, nachdem sie die Schmutzverkrustung entfernt hat. Selbst wenn die Maschine nicht funktioniert hat, ist der Gegenstand jetzt immerhin in einer hübschen Schachtel verpackt.\n\nTja, es gibt nur einen Weg herauszufinden, ob sie den Gegenstand gesäubert hat oder nicht...", sourceObjectiveStatus = "unverified-source-field" }
quests[2953] = { id = 2953, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Funkelmatastisch", progress = "Der Funkelmat 5200 ist leer und wartet auf ein schmutzverkrustetes Objekt zum Säubern sowie auf drei Silbermünzen, um loszulegen!", completion = "Der Funkelmat 5200 erwacht hin und her schlingernd zum Leben. Innen wird der hilflose Schmutz, der das eingelegte Objekt verkrustet hat, vom Gnomenlösungsmittel der Maschine pulverisiert.\n\nDer Funkelmat 5200 kommt zum Stillstand, angekündigt durch ein vertrautes \"Ding!\". Der Aufnahmebehälter der Maschine springt auf und offenbart eine ordentlich eingewickelte Schachtel." }
quests[2954] = { id = 2954, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Steinbehüter", description = "Willkommen - Ich bin der Wächter des Eingangs. Ich werde Euch den Zugang zum Areal von Uldum nur gewähren, wenn Ihr die Platten von Uldum in Euren Scheibensatz integriert habt.\n\nDas Erscheinen des Steinbehüters von Norgannon muss die Reaktion sein, die man sich davon erhoffte, als man Euch mit den Platinscheiben in die Tanariswüste schickte. Wie Euch aufgetragen, werdet Ihr die Geschichte, die hinter dem Steinbehüter steckt, herausfinden müssen, bevor Ihr weitermachen könnt.", sourceObjective = "Findet den Zweck des Steinbehüters von Norgannon heraus und interagiert dann mit dem Podest von Uldum in der Tanariswüste.", sourceObjectiveStatus = "unverified-source-field" }
quests[2962] = { id = 2962, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das einzige Heilmittel ist mehr grünes Leuchten", description = "Eure Probe war nicht nur von unzureichender Menge, sondern auch noch verunreinigt.\n\nWas wir brauchen, ist mehr von dem grünen Leuchten. Die Troggs sind offensichtlich nicht stark genug verstrahlt, um unseren Ansprüchen zu genügen. Ihr werdet nach Gnomeregan gehen und etwas der radioaktiven Ablagerung direkt von der Quelle besorgen müssen. Ich spreche von den bestrahlten Schleimen, Lauerern und Schrecken. Seid gewarnt, diese Art von Ablagerung ist schwer abzufüllen. Es könnte Euch mehrere Versuche mit der Phiole kosten, bis Ihr eine geeignete Probe bergen könnt.", sourceObjective = "Reist nach Gnomeregan und bringt etwas von der hoch konzentrierten radioaktiven Ablagerung zurück. Seid gewarnt, die Ablagerung ist instabil und wird ziemlich schnell zerfallen.\n\nOzzie wird außerdem Eure schwere bleierne Phiole benötigen, nachdem die Aufgabe erledigt ist.", sourceObjectiveStatus = "unverified-source-field" }
